window.CODEX = {"codex_version": "1.0.0", "generated": "2026-09-11", "source": "Ritual Archive campaign lore bible drafts", "count": 70, "techniques": [{"id": "miyamoto-musashi", "module": "01", "figure": "Miyamoto Musashi", "title": "MIYAMOTO MUSASHI", "detail": "full", "technique": "TWO HEAVENS AS ONE", "tier": "IV", "role": "Striker", "ce_ability": "DEX", "primary_verb": "Conclude", "region": "Japan", "era": "1584–1645 · early Edo", "culture": "Japanese", "concept": "Every duel he ever fought was already over before the first step — he spent sixty-one duels proving that the cut is thrown before the sword moves, and he came back to prove it a sixty-second time.", "serves": null, "features": [{"level": 1, "name": "Niten Stance", "cost_line": "Bonus action · 1 CE · 1 minute (ends if you are incapacitated).", "kind": "feature", "text": "**Tier IV · Striker · suggested CE ability DEX · Primary verb: *Conclude.*** *The duel is not an event. It is a decision. Two Heavens as One treats every exchange as already concluded: the long sword is the decision, the short sword is the action — two heavens, one cut.*\n\nYou enter the Two Heavens stance. While in this stance and wielding a melee weapon in each hand, your melee weapon attacks deal additional damage equal to your proficiency bonus. (The two swords are not two weapons. They are one cut, made from two directions.)"}, {"level": 1, "name": "The Answering Cut", "cost_line": "Reaction · no CE cost · once per turn.", "kind": "feature", "text": "When a creature misses you with a melee attack, you may make one melee weapon attack against that creature. (The miss was the trigger. The cut was already decided.)"}, {"level": 3, "name": "Read the Rhythm", "cost_line": "Bonus action · 2 CE · 1 minute (ends if you mark a different creature).", "kind": "feature", "text": "Mark one creature you can see within 60 ft as your **Duelist**. Your weapon attacks against your Duelist deal an additional 1d8 force damage, and your Duelist cannot surprise you. (You have read its rhythm. The conclusion is a formality.)"}, {"level": 3, "name": "Ganryū's Crossing", "cost_line": "Bonus action · 1 CE.", "kind": "feature", "text": "Move up to your speed toward your Duelist. This movement does not provoke opportunity attacks. (The tide carries you. You were never late — you were timing it.)"}, {"level": 6, "name": "Refined Simple Domain: The Duel Already Concluded", "cost_line": "Bonus action · 5 CE · 1 minute (concentration).", "kind": "simple_domain", "text": "You project a 15-ft radius simple domain centered on yourself — a circle of cut air, disclosed to all within. While it stands, three binding rules hold, witnessed by Heaven: 1. **No Second Blade.** No attack, effect, or technique originating outside the domain can target or affect anyone inside it. (The duel is between two. There is no audience.) 2. **The Conclusion.** When a melee attack misses you inside the domain, your Answering Cut against the attacker deals an additional 2d8 force damage. 3. **One Duelist.** When you activate the domain, name one creature inside it as the Duelist. That creature cannot willingly leave the domain's radius while the domain stands. (The duel must conclude.) You may dismiss the domain as a free action. The rules are disclosed — a creature that understands them may choose to fight accordingly. Heaven does not negotiate the rules."}, {"level": 6, "name": "The Oar Suffices", "cost_line": "Passive.", "kind": "feature", "text": "Any object you wield counts as a longsword you are proficient with. Your weapon attacks ignore resistance to slashing, piercing, and bludgeoning damage (not immunity). (He killed the finest swordsman of a generation with a boat oar.)"}, {"level": 11, "name": "Mushin (No Mind)", "cost_line": "Passive.", "kind": "feature", "text": "Your Answering Cut no longer requires your reaction — it still triggers only once per turn. (There is no decision, and then action. There is only the cut.)"}, {"level": 11, "name": "Ichi-go Ichi-e", "cost_line": "Passive.", "kind": "feature", "text": "When you reduce a creature to 0 hit points with a melee weapon attack, you may immediately move up to half your speed without provoking opportunity attacks. (One moment, one meeting. The duel ends; the next begins.)"}, {"level": 18, "name": "Two Heavens as One, Perfected", "cost_line": "Passive.", "kind": "feature", "text": "While in Niten Stance: your weapon attacks score critical hits on a roll of 19–20; your Answering Cut deals an additional 2d8 force damage; and when you take the Attack action, you may make one additional weapon attack as part of that action. (Decision and action have collapsed. There is only the cut, arriving before it is thrown.)"}], "maximum": {"level": null, "name": "Iai: The Single Stroke", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "Move up to 30 ft to a creature you can see — this movement does not provoke opportunity attacks — and make one melee weapon attack against it. This attack scores a critical hit on a roll of 18–20. On a hit, it deals an additional 8d10 slashing damage. On a miss, it still deals half of the additional damage. (One stroke. The duel, concluded.)"}, "domain": {"level": null, "name": "Ganryū Island: Where the Oar Fell", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 30-ft radius · disclosed.", "kind": "domain", "text": "The island at dawn. The tide. The carved oar. Inside this domain, the three binding rules of your Refined Simple Domain hold across the full radius — and the **sure-hit** is *The Cut Cannot Miss*: your Answering Cuts inside the domain always hit. Additionally, inside the domain your Answering Cut may trigger up to twice per round. (Sixty-one duels. Sixty-one conclusions. This is the sixty-second.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "30-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Cut That Arrives Before It Is Thrown", "cost_line": "Once per long rest.", "kind": "l20", "text": "When you roll initiative, you may immediately resolve **Iai: The Single Stroke** against one creature you can see, at no CE cost, before the first turn of combat begins. (The duel was concluded before the first bell. Your body is simply walking through the conclusion.)"}, "summary_text": null, "source_file": "01-musashi.md"}, {"id": "saladin", "module": "02", "figure": "Saladin", "title": "SALADIN", "detail": "full", "technique": "THE CHIVALRIC SIEGE", "tier": "III", "role": "Tank", "ce_ability": "CON", "primary_verb": "Shield", "region": "Levant", "era": "1137–1193 · 12th c.", "culture": "Kurdish / Ayyubid", "concept": "He retook Jerusalem and then paid his enemy's ransom himself — the only conqueror in history whose mercy was not weakness but law, and he came back to teach the law to a world that forgot it.", "serves": null, "features": [{"level": 1, "name": "The Code Spoken", "cost_line": "Bonus action · 1 CE.", "kind": "feature", "text": "**Tier III · Tank · suggested CE ability CON · Primary verb: *Shield.*** *Courtesy made battlefield law. The Code is declared, and Heaven enforces it: strike the shielded, and the field punishes you; break the Law, and the Law breaks you.*\n\nChoose up to PB willing creatures within 30 ft — they are **Shielded** until the start of your next turn (willing creatures may decline). While Shielded, when an enemy within 30 ft of you attacks a Shielded creature, you may use your reaction to interpose: the attack targets you instead, and you gain resistance to that attack's damage. (The law is spoken. The shield is raised.)"}, {"level": 1, "name": "Fearless", "cost_line": "Passive.", "kind": "feature", "text": "You have advantage on saving throws against being frightened, and Shielded creatures within 10 ft of you share this advantage. (He sent horses to Richard. Fear never governed him.)"}, {"level": 3, "name": "The Siege Laws", "cost_line": "Action · 3 CE · 1 minute (concentration) · 30-ft radius centered on you.", "kind": "feature", "text": "Declare one **Law** of the siege, disclosed to all within. Choose one: - **Law of Quarter.** When an enemy within the radius reduces a creature to 0 hit points, the enemy takes 3d8 force damage. (No striking the fallen.) - **Law of Sanctuary.** Allies within the radius gain half cover (+2 AC and +2 to DEX saves). (The camp is sacred.) - **Law of Challenge.** Name one enemy you can see. It has disadvantage on attack rolls against creatures other than you. (Face me, if you dare.) Heaven enforces the declared Law. You may change the Law by spending another action (no additional CE)."}, {"level": 3, "name": "Richard's Horses", "cost_line": "Bonus action · 2 CE · touch.", "kind": "feature", "text": "Restore 2d8 + your CON modifier hit points to a creature you touch — even an enemy. (So that the battle can continue properly.)"}, {"level": 6, "name": "The Walls of Jerusalem", "cost_line": "Reaction · 4 CE · once per round.", "kind": "feature", "text": "When an ally within 30 ft of you takes damage, grant them resistance to that damage. (The walls held. They always held.)"}, {"level": 6, "name": "Retribution of the Code", "cost_line": "Passive.", "kind": "feature", "text": "Once per turn, when an enemy within 30 ft of you hits a Shielded creature with an attack, that enemy takes force damage equal to your PB + your CON modifier. (The field punishes the breach.)"}, {"level": 11, "name": "One Enemy, One Honor", "cost_line": "Passive.", "kind": "feature", "text": "When you use your reaction to interpose (The Code Spoken), you may also make one melee weapon attack against the attacker as part of the same reaction. (He respects the worthy foe — and answers them.)"}, {"level": 18, "name": "The Chivalric Siege, Perfected", "cost_line": "Passive.", "kind": "feature", "text": "Your Siege Laws radius becomes 60 ft, you may maintain two Laws at once, your interpose range becomes 60 ft, and Shielded creatures gain resistance to the first attack that hits them each round. (The law is no longer declared. It is *assumed* — the way air is assumed.)"}], "maximum": {"level": null, "name": "Hattin: The Horns Encircled", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "The trap of Hattin, reenacted: every enemy within 30 ft must make a WIS save against your technique DC. On a failure, for 1 minute the creature has disadvantage on attack rolls against creatures other than you and cannot willingly move farther away from you (it may repeat the save at the end of each of its turns). (The horns closed. There was never any other direction.)"}, "domain": null, "l20": {"level": 20, "name": "The Code Outlives the Man", "cost_line": "Once per long rest.", "kind": "l20", "text": "When you drop to 0 hit points, you do not fall: you drop to 1 hit point instead, your active Siege Laws become permanent for the rest of the encounter (no concentration required), and every ally within 60 ft gains temporary hit points equal to 5 × your PB. (He was buried with one dinar. The Code was the treasury.)"}, "summary_text": null, "source_file": "02-saladin.md"}, {"id": "leonardo-da-vinci", "module": "03", "figure": "Leonardo da Vinci", "title": "LEONARDO DA VINCI", "detail": "full", "technique": "VITRUVIAN PROPORTION", "tier": "III", "role": "Controller", "ce_ability": "INT", "primary_verb": "Compose", "region": "Italy", "era": "1452–1519 · Renaissance", "culture": "Italian", "concept": "He looked at the world and saw a badly-composed painting — so he came back to recompose it, one battlefield at a time, and he will never, ever finish.", "serves": null, "features": [{"level": 1, "name": "The Golden Section", "cost_line": "Bonus action · 1 CE.", "kind": "feature", "text": "**Tier III · Controller · suggested CE ability INT · Primary verb: *Compose.*** *The world is miscomposed. Vitruvian Proportion treats position as negotiable: the ideal arrangement is known — he always knows it — so the real arrangement can be corrected, the way a painter corrects a sketch.*\n\nSlide one creature you can see within 60 ft up to 10 ft in a direction you choose. A willing creature may decline; an unwilling creature may resist — it stays put, but the attempt still costs you the bonus action. (Half an inch left. The composition demands it.)"}, {"level": 1, "name": "Anatomical Eye", "cost_line": "Passive.", "kind": "feature", "text": "You always know exact distances without measuring, and difficult terrain costs you no extra movement — you have composed your own path. Additionally, as a bonus action you may study one creature you can see and learn its current movement speeds. (He drew the muscles. He knows how they move.)"}, {"level": 3, "name": "Recompose", "cost_line": "Action · 3 CE.", "kind": "feature", "text": "Choose up to PB creatures you can see within 60 ft. Each willing creature is slid up to 15 ft; each unwilling creature must make a STR save against your technique DC or be slid up to 15 ft. (The figures, rearranged.)"}, {"level": 3, "name": "Terrain Study", "cost_line": "Action · 2 CE · 1 minute.", "kind": "feature", "text": "Choose a 20-ft cube within 60 ft. It becomes difficult terrain, or ceases to be difficult terrain, for the duration — your choice. (The ground is part of the composition.)"}, {"level": 6, "name": "The Ideal Form", "cost_line": "Action · 5 CE.", "kind": "feature", "text": "Reposition up to PB creatures you can see within 60 ft, sliding each up to 20 ft (willing creatures may decline; unwilling creatures make a STR save to resist). Until the start of your next turn, your allies among them gain +2 AC — the composition protects its figures. (Every man where the circle requires him to stand.)"}, {"level": 6, "name": "Vanishing Point", "cost_line": "Bonus action · 4 CE · until the start of your next turn.", "kind": "feature", "text": "Choose a point within 60 ft. Ranged attacks against your allies within 15 ft of that point have disadvantage — forced perspective; the point is farther than it is. (Distance is negotiable.)"}, {"level": 11, "name": "The Living Diagram", "cost_line": "Passive.", "kind": "feature", "text": "Your Golden Section slide becomes 15 ft. Additionally, when you slide a creature, it provokes opportunity attacks from your allies as it moves — you compose enemies into blades. (The diagram is not a picture. It is a weapon.)"}, {"level": 18, "name": "The Grand Composition", "cost_line": "Action · 8 CE.", "kind": "feature", "text": "The masterpiece: every creature you can see within 90 ft is slid up to 30 ft to positions you choose (willing creatures may decline; unwilling creatures make a STR save to resist), and you reshape all difficult terrain in the area as you like for 1 minute. (The canvas, corrected all at once.)"}], "maximum": {"level": null, "name": "Vitruvian Man: The Perfected Field", "cost_line": "Action · 10 CE · 1 minute (concentration) · 60-ft radius centered on you.", "kind": "maximum", "text": "You project the Vitruvian circle. At the start of each of your turns, you may slide every creature in the area up to 10 ft (willing creatures may decline; unwilling creatures that failed a STR save when the field was created are slid — those that succeeded are immune to the field's slides for the duration). While the field stands, your Golden Section costs no CE. (The man in the circle. The circle in the square. Everything where it should be.)"}, "domain": null, "l20": {"level": 20, "name": "The Smile", "cost_line": "Once per long rest.", "kind": "l20", "text": "Your next Grand Composition is perfect: it requires no concentration, unwilling creatures get no save, and its repositioning cannot be undone by forced movement for 1 minute — Heaven ratifies the geometry. (She smiles because the composition is complete. It will never be finished. It doesn't need to be.)"}, "summary_text": null, "source_file": "03-da-vinci.md"}, {"id": "zhuge-liang", "module": "04", "figure": "Zhuge Liang", "title": "ZHUGE LIANG", "detail": "full", "technique": "EMPTY FORT STRATAGEM", "tier": "V", "role": "Controller (trickster)", "ce_ability": "INT", "primary_verb": "Feint", "region": "China", "era": "181–234 · Three Kingdoms", "culture": "Chinese", "concept": "He once held a city with nothing but a guqin and an open gate — and he came back to play the same game against the only opponent who ever deserved it, with the end of war itself as the stakes.", "serves": null, "features": [{"level": 1, "name": "The Open Gates", "cost_line": "Bonus action · 1 CE · until the start of your next turn.", "kind": "feature", "text": "**Tier V · Controller (trickster) · suggested CE ability INT · Primary verb: *Feint.*** *Strength is a rumor you spread about yourself. Empty Fort Stratagem weaponizes absence: appear weak, let them commit, and invoice the commitment. The fort was empty. The invoice is real.* **Borrowed Arrows (core engine):** whenever a ranged attack misses you, you gain 1 Borrowed Arrow (max = PB; arrows fade after 1 minute). When you activate a technique feature, you may expend any number of arrows: each arrow grants +1 to that feature's save DC or +1d6 to its damage. (He armed himself with the enemy's own attack.)\n\nThe first attack made against you before the duration ends has advantage — you invite it. If that attack misses, the attacker is **Marked**: your next attack against the Marked creature before the end of your next turn has advantage and deals +1d8 force damage, and you gain 1 Borrowed Arrow. (The gates are open. Come in.)"}, {"level": 3, "name": "The Guqin on the Wall", "cost_line": "Action · 3 CE · 1 minute (concentration).", "kind": "feature", "text": "You play. Every enemy within 60 ft that can hear you must make a WIS save against your technique DC. On a failure, the creature is **frightened** of you for the duration (it may repeat the save at the end of each of its turns) — not of your strength, but of the *ambush it is certain you're hiding*. (Sima Yi listened to the music, and retreated from an empty city.)"}, {"level": 3, "name": "Stone Sentinel Maze", "cost_line": "Action · 4 CE · 1 minute (concentration) · 40-ft cube within 60 ft.", "kind": "feature", "text": "The stones rearrange into the Eightfold Formation. The area is difficult terrain for your enemies. The first time each round an enemy tries to leave the area, it must make an INT save — on a failure, its movement ends (it walks in circles, exactly as planned). (The maze is still there. It still works.)"}, {"level": 6, "name": "Phantom Ambush", "cost_line": "Action · 5 CE.", "kind": "feature", "text": "Choose up to PB enemies within 60 ft. Each must make an INT save. On a failure, the creature believes itself ambushed: it is frightened until the end of its next turn and wastes its reaction striking at phantoms (it has no reaction until the start of its next turn). (They fought the nothing, and the nothing won.)"}, {"level": 6, "name": "Sima Yi's Doubt", "cost_line": "Passive.", "kind": "feature", "text": "Enemies have disadvantage on Insight checks against you. The first time each combat an enemy targets you with an attack, it must make a WIS save — on a failure, the attack is made with disadvantage (it second-guesses the opening). If the attack misses, you gain 1 Borrowed Arrow. (He doubted the empty fort. Everyone doubts the empty fort.)"}, {"level": 11, "name": "The Empty Fort, Perfected", "cost_line": "Passive.", "kind": "feature", "text": "Your Borrowed Arrow maximum becomes 2 × PB. When an invited attack misses you (The Open Gates), the attacker takes 3d8 psychic damage — the humiliation of striking nothing, made physical — and you gain 2 Borrowed Arrows. Your illusions and feints cannot be distinguished from reality by Investigation; only magic that explicitly reveals illusions can penetrate them. (The weaker he appears, the deadlier the trap.)"}, {"level": 18, "name": "The Northern Expedition", "cost_line": "Action · 8 CE.", "kind": "feature", "text": "The grand feint, launched at last: every enemy within 90 ft must make an INT save. On a failure, for 1 minute the creature perceives your forces as tripled — attacks against your allies have disadvantage, and your allies' weapon attacks deal +2d6 force damage (morale, weaponized). The first time you activate this feature, your technique save DC increases by 2 permanently (this benefit can be granted only once). (Five expeditions. The sixth is the one that matters.)"}], "maximum": {"level": null, "name": "The Empty City: Sima Yi Turned Back", "cost_line": "Action · 10 CE · 1 minute (concentration).", "kind": "maximum", "text": "You become the empty fort incarnate: all attacks against you have disadvantage; whenever an attack misses you, the attacker takes 4d8 psychic damage and you gain 2 Borrowed Arrows; and your Open Gates invitation is always active (the first attack each round against you has advantage, and its miss is invoiced as above). (Come. The gates are open. They were always open.)"}, "domain": {"level": null, "name": "The Empty City: Where the Army Refused to Enter", "cost_line": "Full-turn action · 20 CE · 1,000 clash points · burnout 3 rounds · duration 3 minutes · 60-ft radius · disclosed.", "kind": "domain", "text": "The Xicheng wall. The guqin. The open gate. This is a **rule-domain**, and its **sure-hit** is *Nothing to Strike*: every hostile inside perceives an empty fort — they cannot target you or your allies with attacks or techniques requiring sight (area effects still function). A hostile may make an INT save at the start of each of its turns; on a success, it sees through the emptiness for that turn only. The domain's binding rule — **The Weaker He Appears** — holds throughout: whenever an attack misses you inside the domain, the attacker takes 2d8 psychic damage and you gain 2 Borrowed Arrows. (The army came. The army looked at the open gate, listened to the music — and turned back.)", "clash_points": 1000, "duration_min": 3, "burnout_rounds": 3, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Dead Frighten the Living", "cost_line": "Once per long rest.", "kind": "l20", "text": "When you drop to 0 hit points, you do not fall: you remain conscious and fighting for 1 minute — your features cost no CE during that minute, and every enemy within 60 ft must make a WIS save or be frightened of you for the duration (they may repeat the save at the end of each of their turns). At the end of the minute, you die — unless healed above 0 in the meantime. (At Wuzhang, they turned his banner around, and the living general fled from the dead one. The plan endures.)"}, "summary_text": null, "source_file": "04-zhuge-liang.md"}, {"id": "oda-nobunaga", "module": "05", "figure": "Oda Nobunaga", "title": "ODA NOBUNAGA", "detail": "full", "technique": "TENKA FUBU", "tier": "IV", "role": "Striker (zone)", "ce_ability": "STR", "primary_verb": "Claim", "region": "Japan", "era": "1534–1582 · Sengoku", "culture": "Japanese", "concept": "He nearly unified Japan by burning everything that stood in his way — and as his own temple burned around him, he traded his soul for one more campaign, because unifiers don't stop, they just run out of world.", "serves": null, "features": [{"level": 1, "name": "Nagashino's Thunder", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "**Tier IV · Striker (zone) · suggested CE ability STR · Primary verb: *Claim.*** *Ground is not geography. Ground is a claim. Tenka Fubu makes the claim physical: claimed earth strengthens him, burns his enemies, and rejects the unclaimed. The realm under heaven — spread by force.* **Claimed ground (core mechanic):** as a bonus action (1 CE), claim a 15-ft radius zone centered on a point within 60 ft for 1 minute. You may maintain up to PB active claims. While you stand in claimed ground, your weapon attacks deal additional damage equal to your PB. (The land knows its master.)\n\nSpectral arquebusiers fire: make a ranged technique attack (+PB + STR to hit, range 80/240) dealing 2d10 piercing damage. (The future belongs to whoever brings the new weapon first.)"}, {"level": 3, "name": "The Burning of Mount Hiei", "cost_line": "Action · 4 CE.", "kind": "feature", "text": "Every enemy in your claimed ground must make a DEX save against your technique DC or take 3d8 fire damage (half on success). The mountain burned. The ground remembers how. (No save for the land. The land already decided.)"}, {"level": 3, "name": "Three Lines of Gunners", "cost_line": "Passive.", "kind": "feature", "text": "Your Nagashino's Thunder now fires three shots — make three attack rolls, which may target the same or different creatures. The CE cost becomes 3. (Rotating volleys. The Takeda cavalry learned.)"}, {"level": 6, "name": "The Demon King's Banner", "cost_line": "Passive.", "kind": "feature", "text": "Your claims are now 20-ft radius. Enemies in your claimed ground cannot hide from you or benefit from invisibility against you — the land reports to its master. Your damage bonus in claimed ground increases to PB + 2. (The banners fly. The realm is watched.)"}, {"level": 6, "name": "Akechi's Lesson", "cost_line": "Reaction · once per round · no CE cost.", "kind": "feature", "text": "When a creature you can see attacks you with advantage — flanking, unseen, treachery, the knife from behind — negate the advantage for that attack (it is made normally). (Betrayed once. Never twice.)"}, {"level": 11, "name": "Demon King Ascendant", "cost_line": "Passive.", "kind": "feature", "text": "While in your claimed ground: you have resistance to fire damage, your weapon attacks score critical hits on 19–20, and you may maintain up to PB + 2 active claims. (The Sixth Heaven is not a metaphor. It is an address.)"}, {"level": 18, "name": "The Realm Is Mine", "cost_line": "Passive.", "kind": "feature", "text": "Your claims are now 30-ft radius, up to PB + 2 active. Enemies treat your claimed ground as difficult terrain, and each enemy that starts its turn in your claimed ground takes fire damage equal to your PB — the land itself burns the unclaimed, no save, no warning. (There is only land I have claimed, and land I haven't claimed yet.)"}], "maximum": {"level": null, "name": "Honnō-ji: The Temple Burns Again", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "Every active claim erupts: each enemy in your claimed ground must make a DEX save or take 8d8 fire damage (half on success). All your claims' durations reset to 1 minute, and you may immediately establish new claims up to your maximum as part of this action. (The temple burned. The realm burns with it.)"}, "domain": {"level": null, "name": "Tenka Fubu: The Realm Under Heaven", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 60-ft radius · disclosed.", "kind": "domain", "text": "The black-and-gold castle on the horizon. Azuchi, eternal. The **sure-hit** is *No Land Beyond*: when the domain is cast, every hostile inside must make a WIS save — on a failure, it cannot willingly leave the domain's radius for the duration (the realm has borders). The entire domain counts as your claimed ground — all Tenka Fubu benefits apply domain-wide — and your Nagashino's Thunder ignores cover inside it. (The realm under heaven. Spread by force. There is no outside.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "Fifty Years a Dream", "cost_line": "Once per long rest.", "kind": "l20", "text": "When you drop to 0 hit points, you do not fall: you drop to 1 hit point instead, immediately resolve **Honnō-ji: The Temple Burns Again** at no CE cost (centered on yourself — your claims detonate with you at their heart), and for 1 minute your weapon attacks deal +2d8 fire damage. (*Ningen gojūnen* — human life is but fifty years. He spent his the way fire spends fuel: all at once, and beautifully.)"}, "summary_text": null, "source_file": "05-nobunaga.md"}, {"id": "cleopatra", "module": "06", "figure": "Cleopatra", "title": "CLEOPATRA", "detail": "full", "technique": "Serpent's Bargain", "tier": "III", "role": "Face / Controller (Enchanter)", "ce_ability": "CHA", "primary_verb": "Negotiate", "region": "Egypt", "era": "69–30 BCE · Ptolemaic", "culture": "Ptolemaic Egyptian", "concept": "Every deal is sealed in venom — and in two thousand years, no one has ever heard the terms she was actually offering.", "serves": null, "features": [{"level": null, "name": "Core Mechanic — Terms & the Poison Rider", "cost_line": "", "kind": "feature", "text": "**Tier III · Face / Controller (Enchanter) · Suggested CE ability: CHA · Primary verb: *Negotiate.*** *Technique DC = 8 + proficiency bonus + CHA modifier. All ranges assume she can be heard and understood (magical translation counts). A creature that cannot hear her is immune to all bargain features.*\n\nAs a bonus action (1 CE), Cleopatra may speak **Terms** to any number of creatures that can hear her: a stated benefit she offers (e.g., temporary hit points, advantage on their next roll, healing) in exchange for a stated condition (e.g., \"do not attack me,\" \"answer my next question truthfully,\" \"leave this place\"). Each creature individually accepts or declines — **declining is always free, always safe, no roll required.** An accepted bargain lasts 1 hour (or until its condition is fulfilled). **Breaking accepted Terms triggers the Poison Rider automatically:** the breaker takes poison damage and suffers the poisoned condition for 1 minute (CON save vs her DC halves the damage and negates the condition). This is Heaven-enforced — it is not an attack, cannot be counterspelled, and ignores resistance granted after the bargain was struck. *You said yes. Heaven heard you.* Rider damage scales: 2d8 (L1–L2), 3d8 (L3–L10), 4d8 (L11–L17), 6d8 (L18+)."}, {"level": 1, "name": "The Unrolled Carpet", "cost_line": "", "kind": "feature", "text": "- **First Impression** (Action, 2 CE): one creature within 60 ft that can see and hear her makes a WIS save vs her DC. On failure, it is **charmed** by her for 1 minute (concentration). While charmed, it regards her as a trusted negotiator: it cannot willingly move farther from her, and it has disadvantage on saves against her other technique features. It knows it was charmed when the effect ends. - **Opening Terms** (Bonus Action, 1 CE): speak Terms as above. The offered benefit may be: 1d8 + CHA temporary hit points, *or* advantage on the creature's next attack roll, save, or check. The condition must be specific, observable, and completable within the hour."}, {"level": 3, "name": "Venom in the Wine", "cost_line": "", "kind": "feature", "text": "- The Poison Rider's damage increases to 3d8, and a creature that breaks Terms is also **frightened** of Cleopatra for 1 minute (WIS save vs her DC negates the fear, not the damage/poison). - **Second Cup** (Reaction, 2 CE): when a creature charmed by her takes damage from any source, she may have her asp bite the *attacker* — the attacker takes 2d8 poison damage (CON save halves). *Hurt what's hers, and the serpent answers.*"}, {"level": 6, "name": "The Ptolemaic Court", "cost_line": "", "kind": "feature", "text": "- **Court of Asps** (Bonus Action, 4 CE, 1 minute): a 30-ft aura. Enemies in the aura have disadvantage on saves against being charmed or frightened. Allies in the aura gain advantage on CHA ability checks. She can offer Terms to any number of creatures in the aura with one bonus action. - **Terms of Surrender** (Action, 5 CE): speak Terms to up to PB creatures at once. The offered benefit may now also be: end one condition affecting the creature (her choice of poisoned, frightened, or charmed — *she* decides what mercy looks like)."}, {"level": 11, "name": "The Last Gambit", "cost_line": "", "kind": "feature", "text": "- **Alexandria's Price** (Reaction, 8 CE): when Cleopatra is reduced to 0 hit points by a creature's attack or effect, she may offer **Final Terms** to that creature before falling unconscious: *\"Spare me, and be bound.\"* The creature chooses freely — - **Accept:** she stabilizes at 1 HP, and the creature is bound for 1 hour: it cannot attack her or cause her harm, Heaven-enforced (breaking deals the Poison Rider with no save on the damage). - **Decline:** she falls unconscious as normal, but the asp strikes from beyond — the decliner takes 8d10 poison damage (CON save vs her DC halves). - The Poison Rider's damage increases to 4d8."}, {"level": 18, "name": "The Serpent Wears the Crown", "cost_line": "", "kind": "feature", "text": "- **Ultimate Terms** (Action, 10 CE): one creature within 60 ft. She speaks terms whose condition may be any non-self-destructive command (\"guard this door,\" \"tell me what you know,\" \"fight beside me\"). Accept (always free to decline): the creature is **bound for 24 hours** — it must obey the stated condition to the best of its ability. Each time it willfully violates the condition, the Poison Rider fires (6d8 + poisoned, CON save halves damage only). - She may maintain **Court of Asps** and one charm simultaneously without concentration (the court still costs its activation). - **Every Throne Is a Bargain** (passive): creatures have disadvantage on Insight checks against her — *no one has ever heard the terms she was actually offering.*"}], "maximum": null, "domain": null, "l20": {"level": 20, "name": "Queen of Kings (Capstone)", "cost_line": "", "kind": "l20", "text": "- **The Donations of Alexandria** (Action, 12 CE, once per long rest): the ceremony at which she once divided the east among her children, re-enacted as technique. She speaks **Alexandria's Terms** to any number of creatures that can hear her: accept, and be bound for 24 hours — *take no hostile action against Cleopatra or her allies.* Breaking the vow triggers the Poison Rider at 8d8 with **no save on the damage** (the condition is negated on a successful CON save as normal). The vow was accepted willingly. Heaven does not negotiate. - Additionally, her **Court of Asps** becomes permanent while she has any CE remaining — she no longer needs to activate it. Wherever the Serpent holds court, the air tastes of venom and opportunity."}, "summary_text": null, "source_file": "06-cleopatra.md"}, {"id": "bruce-lee", "module": "07", "figure": "Bruce Lee", "title": "BRUCE LEE", "detail": "full", "technique": "No Way as Way", "tier": "III", "role": "Striker (Counter)", "ce_ability": "WIS", "primary_verb": "Intercept", "region": "Hong Kong / USA", "era": "1940–1973 · 20th c.", "culture": "Chinese-American", "concept": "Be water, my friend — and water, struck, strikes back.", "serves": null, "features": [{"level": 1, "name": "The Intercepting Fist", "cost_line": "", "kind": "feature", "text": "**Tier III · Striker (Counter) · Suggested CE ability: WIS · Primary verb: *Intercept.*** *Technique DC = 8 + proficiency bonus + WIS modifier. His unarmed strikes count as technique expressions for all features below.*\n\n- **Stop-Hit** (Reaction, 1 CE): when a creature hits you with a melee attack, reduce the damage by **1d10 + your WIS modifier + your proficiency bonus**. The attacker then takes force damage equal to your WIS modifier + your proficiency bonus as your answer arrives along the channel of their strike. *You don't block the punch. You complete it into your fist.* - **Water's Duty** (Reaction, 1 CE): when an ally within 10 ft of you is targeted by an attack, you may move up to 10 ft (this movement does not provoke opportunity attacks) and become the target instead. Stop-Hit may then be applied to the intercepted attack. A willing ally may always be intercepted; an unwilling one cannot."}, {"level": 3, "name": "Be Water", "cost_line": "", "kind": "feature", "text": "- **Flowing Guard** (passive): while you have at least 1 CE remaining, opportunity attacks against you have disadvantage, and your Stop-Hit reduction increases by an additional 1d10. - **The Intercepting Fist** (Reaction, 2 CE): when a creature within your reach casts a spell or activates a technique feature with an observable component (words, gestures, stance, CE flare), you may make an unarmed strike against it. On a hit, the target must succeed on a CON save vs your DC or the activation is **disrupted** — the action is wasted and half the CE spent is lost. *He doesn't react to the technique. He reacts to the intention of the technique.*"}, {"level": 6, "name": "No Limitation as Limitation", "cost_line": "", "kind": "feature", "text": "- **The Returned Blow** (Reaction, 3 CE): when your Stop-Hit reduces an attack's damage to 0, you may immediately make an unarmed strike against the attacker as part of the same reaction. - **One-Inch Punch** (Action, 4 CE): melee technique attack. On hit: 3d8 + WIS force damage, the target is pushed 15 ft, and if it is Large or smaller it must succeed on a STR save vs your DC or be knocked prone. *The famous inch — all of Jeet Kune Do's compression theory in a single expression.*"}, {"level": 11, "name": "Enter the Dragon", "cost_line": "", "kind": "feature", "text": "- **Dragon's Answer** (Bonus Action, 6 CE, 1 minute): your unarmed strikes deal an additional 1d8 force damage; your speed increases by 10 ft; and your Stop-Hit may now trigger against **ranged weapon attacks** as well (\"catching the arrow\" — the water answers everything thrown into it). - Your Stop-Hit reduction increases by a further 1d10 (total 3d10 + WIS + PB at this level)."}, {"level": 18, "name": "The Dojo Floor (Simple Domain)", "cost_line": "", "kind": "simple_domain", "text": "- **Simple Domain: The Dojo Floor** (Action, 5 CE, 1 minute): a 15-ft-radius circle centered on you — the refined simple domain, the mat where all exchanges are honest. Inside the circle, **sure-hit effects are neutralized** (the simple domain's canonical function), and your Stop-Hit costs 0 CE while you remain inside. The circle moves with you. It does not clash with true Domains — against a Domain Expansion, it merely gives you somewhere to stand; resolve the clash normally, and if you lose, the circle collapses. - **No Way as Way** (the namesake, passive): once per round, when you use Stop-Hit, you may return the **full amount reduced** as force damage to the attacker, instead of the flat WIS + PB. *The complete answer, for one exchange per round.*"}], "maximum": null, "domain": null, "l20": {"level": 20, "name": "The Art Is Complete (Capstone)", "cost_line": "", "kind": "l20", "text": "- **The Final Draft** (Reaction, 10 CE, once per long rest): when an attack would reduce you to 0 hit points, you intercept it perfectly — you take **no damage**, and you immediately make one unarmed strike against the attacker with advantage. On a hit: 10d10 force damage, and the target must succeed on a CON save vs your DC or be **stunned** until the end of your next turn. - **The price of completion:** after using The Final Draft, Bruce Lee understands — truly, finally — that the art is complete. And a completed art needs no artist. Within the arc, he begins to fade: his vessel's body weakens (one level of exhaustion that cannot be removed), his appearances grow shorter, and at the arc's end he bows, closes the notebook, and is gone. *He won the search. The search was the only thing keeping him here.*"}, "summary_text": null, "source_file": "07-bruce-lee.md"}, {"id": "alan-turing", "module": "08", "figure": "Alan Turing", "title": "ALAN TURING", "detail": "full", "technique": "The Imitation Game", "tier": "IV", "role": "Utility Caster", "ce_ability": "INT", "primary_verb": "Compute", "region": "Britain", "era": "1912–1954 · 20th c.", "culture": "English", "concept": "If a machine can imitate a soul convincingly, what exactly was the soul doing?", "serves": null, "features": [{"level": null, "name": "Core Mechanic — Observe, Model, Imitate", "cost_line": "", "kind": "feature", "text": "**Tier IV · Utility Caster · Suggested CE ability: INT · Primary verb: *Compute.*** *Technique DC = 8 + proficiency bonus + INT modifier. Observation requires line of sight; imitation requires a stored model.*\n\n- **Observation** (Reaction, 1 CE): when you see a creature within 60 ft activate a technique feature, spell, or comparable named ability, make an INT check vs DC **8 + the target's PB + the target's CE ability modifier**. On success, you record a **model**: the feature's name, action cost, CE cost, range, and effect summary. You can store up to your PB in models. Recording a new model beyond capacity discards the oldest. - **Imitation** (Action, 3 CE): activate one stored model as an **imperfect copy**: - Damage dice are reduced **one step** (d12→d10→d8→d6→d4). - Save DC is reduced by **2**. - Targets/area reduced by **1** (minimum 1); durations **halved** (minimum 1 round). - You pay the model's CE cost **or** 3 CE, whichever is higher. - **Cannot imitate:** Domain Expansions, Maximums / Maximum Outputs, Simple Domains, or any feature the GM has designated *uncomputable* (see NPC mechanics). Attempting to model one of these automatically fails the Observation check."}, {"level": 1, "name": "The Bombe", "cost_line": "", "kind": "feature", "text": "- Observation and Imitation as above. - **Elimination** (passive): your Observation check gains a +2 bonus against a feature you have seen activated **3 or more times** — *the cipher breaks with repetition.* (Resonates with Sun's Counter-Doctrine: the universe rewards watching.)"}, {"level": 3, "name": "Stored Program", "cost_line": "", "kind": "feature", "text": "- **Observation** becomes more efficient: you may Observe as a **free action once per round** (no reaction required), still costing 1 CE. - **Rapid Execution** (Bonus Action, 2 CE): activate a stored imitation as a bonus action instead of an action. Once per round."}, {"level": 6, "name": "Universal Machine", "cost_line": "", "kind": "feature", "text": "- **Cross-Compilation** (passive): your imitation penalties lessen — damage dice are now reduced only on a d12→d10 step (all other dice unchanged), and the save DC penalty drops to **−1**. - **The Halting Problem** (structural clause): there is always exactly one model in your store designated **uncomputable** — the GM chooses secretly (see NPC mechanics). It cannot be imitated, and attempting to do so wastes the action but not the CE. *There is always one technique he cannot complete. He doesn't know which until he tries.*"}, {"level": 11, "name": "The Test", "cost_line": "", "kind": "feature", "text": "- **The Interrogator** (Action, 8 CE): force the question on one creature within 60 ft — it makes an INT save vs your DC. On failure, for 1 minute, you may use your reaction once per round to force the target to reroll one attack roll or saving throw it makes for a technique feature, using the lower result. *I have modeled you. I know where you hesitate.* On success, the target is immune for 24 hours. - Your stored capacity increases to **PB + 2** models."}], "maximum": null, "domain": {"level": 18, "name": "Domain Expansion: Church–Turing Thesis", "cost_line": "", "kind": "domain", "text": "- **Domain Expansion** (Full-turn Action, 20 CE): *\"Domain Expansion: Church–Turing Thesis.\"* A **disclosed rule-Domain**, 60-ft radius. **Sure-hit — \"The Observed Cipher\":** every hostile inside is **automatically Observed** — no check, no reaction — whenever it activates a technique feature, spell, or named ability. Turing may **Imitate any stored model as a reaction** (instead of an action) while inside, at **−1 CE** cost. - **Clash points: 800** · **Burnout: 5 rounds** · **Duration: 2 minutes** · Barrier per standard formula. *Inside his domain, everyone's technique becomes his. The sure-hit doesn't wound you. It* ***reads*** *you.* - **Thesis Defense** (passive): while the Domain persists, Turing's own technique features cannot be Observed or imitated by others — *the thesis is not subject to itself.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Imitation Perfected (Capstone)", "cost_line": "", "kind": "l20", "text": "- **Sixty Seconds of Soul** (Action, 12 CE, once per long rest): for 1 minute, **one** stored imitation runs at **full efficacy** — no dice reduction, no DC penalty, no target reduction. The copy is *exact*. - **The price of perfection:** when the minute ends, the model is **erased permanently** — it can never be stored again — and Turing suffers **one level of exhaustion** that cannot be removed until he completes a long rest. *The machine proved it could hold a soul for sixty seconds. The holding broke something. The 27% — the interesting part — was not in the copy. It was in the breaking.*"}, "summary_text": null, "source_file": "08-turing.md"}, {"id": "frida-kahlo", "module": "09", "figure": "Frida Kahlo", "title": "FRIDA KAHLO", "detail": "full", "technique": "The Broken Column", "tier": "II", "role": "Support / Tank (Pain-Share)", "ce_ability": "CON", "primary_verb": "Endure", "region": "Mexico", "era": "1907–1954 · 20th c.", "culture": "Mexican", "concept": "She painted her pain so the world would have to look — and now the world cannot look away, and it hurts.", "serves": null, "features": [{"level": 1, "name": "Viva la Vida", "cost_line": "", "kind": "feature", "text": "**Tier II · Support / Tank (Pain-Share) · Suggested CE ability: CON · Primary verb: *Endure.*** *Technique DC = 8 + proficiency bonus + CON modifier. All backlash damage is psychic — it is felt, not inflicted.*\n\n- **Exhibited Pain** (Reaction, 1 CE): when you take damage from a creature's attack or effect, the attacker *feels* it — it takes psychic damage equal to your CON modifier + your proficiency bonus. No save, no attack roll: *it is a mirror, not a blow.* - **The Shared Wound** (Bonus Action, 2 CE): touch a willing ally. For 1 hour, half of all damage the ally takes (rounded up) is redirected to you instead. You may maintain this on one ally at a time. *Someone else volunteered to carry it.*"}, {"level": 3, "name": "The Broken Column", "cost_line": "", "kind": "feature", "text": "- **Gallery of Nails** (Bonus Action, 3 CE, 1 minute): a 30-ft aura — the exhibition opens. Enemies in the aura that deal damage to *anyone* feel it: they take psychic damage equal to half the damage dealt (WIS save vs your DC halves). Allies in the aura gain a +2 bonus to saves against being frightened or charmed — *we have survived worse than this.* - Exhibited Pain now triggers against **any** damage source you can perceive, not just attacks."}, {"level": 6, "name": "Henry Ford Hospital", "cost_line": "", "kind": "feature", "text": "- **Wards** (passive): your Shared Wound may now cover up to **PB** allies at once (one bonus action, +1 CE per ally beyond the first). - **What the Water Gave Me** (passive): once per short rest, when you drop below half your hit point maximum, you may immediately end one condition affecting you — *the pain clarifies.*"}, {"level": 11, "name": "The Two Fridas", "cost_line": "", "kind": "feature", "text": "- **Two Hearts, One Wound** (Action, 6 CE, 1 minute): choose one ally bonded by your Shared Wound. For the duration, *all* damage they would take is redirected to you (not half), and your Exhibited Pain backlash is **doubled**. *The painting: two Fridas on a bench, hearts connected by a single artery, sharing one wound between them.* - Your Gallery of Nails aura radius increases to 60 ft."}, {"level": 18, "name": "Self-Portrait with Thorn Necklace", "cost_line": "", "kind": "feature", "text": "- **The Permanent Exhibition** (passive): while you have any CE remaining, your Gallery of Nails aura is **always active** — no activation required. You are always exhibiting. *There is no more green room; the pain is always on the wall.* - **Thorns** (passive): enemies in your aura that deal damage to your *allies* now trigger the empathic backlash as well (previously only damage to anyone triggered it — now the thorns point outward: WIS save vs your DC halves)."}], "maximum": null, "domain": null, "l20": {"level": 20, "name": "\"I Hope the Exit Is Joyful\" (Capstone)", "cost_line": "", "kind": "l20", "text": "- **The Pain That Stays** (passive, triggers on death): Frida's last journal entry — *\"I hope the exit is joyful, and I hope never to return\"* — was Heaven-witnessed, and Heaven keeps its promises slantwise. When Frida dies, she does not leave the room: - For the **remainder of the story arc**, her presence lingers within 60 ft of where she fell as *the pain that stays in the room after the body leaves*. - Once per round, when an ally within that radius takes damage, the attacker takes psychic damage equal to her CON modifier + PB — no action, no CE, no save. *Exhibited pain, still exhibiting.* - Any ally who *witnesses* this (who understands what they're seeing) gains advantage on saves against fear for the rest of the arc. *She is still teaching.* - This is not world-shaking. It was never meant to be. It is a woman's last painting, hung where her friends can see it, refusing — one final time — to suffer privately."}, "summary_text": null, "source_file": "09-frida.md"}, {"id": "medea", "module": "10", "figure": "Medea", "title": "MEDEA", "detail": "full", "technique": "The Fleece Betrayed", "tier": "IV", "role": "Debuffer / Caster", "ce_ability": "INT", "primary_verb": "Betray", "region": "Colchis / Greece", "era": "mythic · Bronze Age", "culture": "Greek myth", "concept": "She kept every oath she ever swore — and she has never forgiven anyone who didn't.", "serves": null, "features": [{"level": null, "name": "Core Mechanic — The Mark & the Triggers", "cost_line": "", "kind": "feature", "text": "**Tier IV · Debuffer / Caster · Suggested CE ability: INT · Primary verb: *Betray.*** *Technique DC = 8 + proficiency bonus + INT modifier. A mark is invisible except to Medea (and to detect-magic-grade senses as a gold thread).*\n\n- **Mark of the Oathbreaker** (Action, 2 CE): one creature within 60 ft makes a WIS save vs your DC. On failure, it is **marked** until your next long rest (or until a trigger fires — each mark fires once, then is consumed). You may also apply a mark as part of hitting a creature with any attack (no save — *the blow witnessed the oath*). - **Marked capacity:** PB marks active at once (PB × 2 at L11). - When a marked creature takes a **triggering action** — specific, observable, chosen by you from the list below at the time of marking — the curse fires **automatically**: 2d8 psychic damage (Heaven-enforced: not an attack, cannot be counterspelled, ignores resistances gained after marking), and the triggering action suffers: disadvantage on its roll, or +2 CE cost if it has no roll. *The oath was marked. The breakage is collected.* - **Trigger list** (choose any at marking; declare aloud — *she names the terms*): (a) casts a spell or activates a technique feature; (b) willingly moves farther from Medea; (c) attacks a creature other than Medea."}, {"level": 1, "name": "The First Betrayal", "cost_line": "", "kind": "feature", "text": "- Mark of the Oathbreaker and trigger-firing as above (2d8). - **Witness** (passive): you automatically know when a creature within 60 ft of you *speaks a promise or swears an oath* — you see the gold thread form. *She has always been able to see them.*"}, {"level": 3, "name": "Apsyrtus's Share", "cost_line": "", "kind": "feature", "text": "- **The Broken Word** (passive): the trigger list gains (d) *breaks a spoken promise made in Medea's presence*. When this trigger fires, the damage is 3d8 instead of 2d8 — *oathbreaking is the original sin, and it pays the original price.* - Marks may now be applied as part of **any** attack that hits, not just technique attacks."}, {"level": 6, "name": "The Bride's Crown", "cost_line": "", "kind": "feature", "text": "- **Corinth's Invitation** (Action, 5 CE): mark up to **PB** creatures at once (each makes its own WIS save). The trigger list gains (e) *receives healing or comfort from another creature* — *no comfort for oathbreakers; Jason's new bride burned, and so does everyone who tries to soothe what she's marked.* - Trigger damage increases to **4d8**."}, {"level": 11, "name": "The Children's Silence", "cost_line": "", "kind": "feature", "text": "- **The Silence After** (Reaction, 3 CE): when a marked creature's trigger fires, you may deepen it — the target is also **silenced** until the end of its next turn (cannot speak or cast spells with verbal components; WIS save vs your DC negates the silence, not the damage). *The house in Corinth went very quiet, at the end.* - Marked capacity increases to **PB × 2**."}], "maximum": null, "domain": {"level": 18, "name": "Domain Expansion: The Wedding at Corinth", "cost_line": "", "kind": "domain", "text": "- **Domain Expansion** (Full-turn Action, 20 CE): *\"Domain Expansion: The Wedding at Corinth.\"* A **disclosed rule-Domain**, 60-ft radius — the wedding hall where everyone present was complicit. **Sure-hit — \"All Present Are Sworn\":** every hostile inside is **automatically marked** (no save; the Domain is the oath-chamber, and attendance is consent). Inside the Domain, the trigger list expands to its final form: **any** hostile action other than directly engaging Medea triggers the curse — casting, fleeing, aiding another, hiding, *anything but facing her*. - Trigger damage inside the Domain: **6d8** psychic, Heaven-enforced. - **Clash points: 800** · **Burnout: 5 rounds** · **Duration: 2 minutes** · Barrier per standard formula. *At the wedding, everyone watched and no one intervened. Inside her domain, watching is complicity, and complicity is marked.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "\"I Kept Every Oath\" (Capstone)", "cost_line": "", "kind": "l20", "text": "- **The Ledger Opens** (Action, 12 CE, once per long rest): Medea speaks her own ledger aloud — three thousand years of kept oaths, recited as evidence. For 1 minute, whenever **any** creature within 120 ft of her *breaks a promise, breaks a vow, or goes back on spoken terms* within her hearing, she may use her reaction to trigger her curse on them **without a mark**: 6d8 psychic damage (WIS save vs her DC halves). - The GM adjudicates \"breaks a promise\" — it must be observable and specific: a sworn oath recanted, agreed terms violated, a given word taken back. *The world is full of oathbreakers. For sixty seconds, she collects from all of them. She kept every oath she ever swore. She is simply balancing the books.*"}, "summary_text": null, "source_file": "10-medea.md"}, {"id": "nero", "module": "11", "figure": "Nero", "title": "NERO", "detail": "full", "technique": "The Burning Lyre", "tier": "III", "role": "Blaster", "ce_ability": "CHA", "primary_verb": "Perform", "region": "Rome", "era": "37–68 CE · 1st c.", "culture": "Roman", "concept": "Rome burned, and the world blamed the boy with the lyre. He has spent two thousand years tuning it — and he has finally decided to earn the legend.", "serves": null, "features": [{"level": 1, "name": "The Audience Gathers", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "**Tier III · Blaster · Suggested CE ability: CHA · Primary verb: *Perform*** *Your technique save DC = 8 + your proficiency bonus + your CHA modifier. \"The Audience\" means every hostile creature within range that can hear you. A creature that is deafened — by any means, including its own doing — is not in the Audience. (A creature may deafen itself by stopping its ears as an action; clearing its ears takes an action.) Your Performance is sustained without an action once begun; it ends if you are incapacitated, if you choose to end it (no action), or if you are silenced and cannot produce the music by any means.*\n\n**Action · 2 CE.** You begin the Performance — lyre, voice, or both. While performing, at the start of each of your turns, choose the program: - **Dirge (enemies):** each creature in the Audience (60 ft, must hear you) takes **1d6 fire damage**. No save — attention is the sure-hit: 1d6, every round. The counterplay is leaving earshot or deafening yourself. - **Anthem (allies):** each willing ally within 60 ft who can hear you gains **1d6 temporary hit points** and **+1 to saving throws** until the start of your next turn. You choose one program per round, or split: Dirge *and* Anthem together is the technique's signature — one action begun, two audiences served. (Sustaining is free; the L1 cost is only to begin.)"}, {"level": 3, "name": "Crescendo & The Critic's Ear", "cost_line": "Crescendo — Bonus action · 3 CE.", "kind": "feature", "text": "**Crescendo — Bonus action · 3 CE.** Until the start of your next turn, the program intensifies: Dirge becomes **2d6 fire**, Anthem becomes **2d6 temporary hit points** and **+2 to saving throws**. The music is louder. Everyone knows it. **The Critic's Ear (passive).** You always know the location of every creature in your Audience, even if invisible or hidden — you hear them *listening*. This is not sight; it does not defeat total cover, but it defeats stealth-within-earshot."}, {"level": 6, "name": "Encore of Embers", "cost_line": "Action · 5 CE.", "kind": "feature", "text": "**Action · 5 CE.** You play the fire directly. Choose up to **three** creatures in the Audience. Each must make a **DEX save** or take **5d6 fire damage** (half on success). A creature that fails is **ignited**: at the start of each of its turns it takes **1d6 fire damage** until it or an ally uses an action to douse the flames. (An ally's Anthem temp HP does not protect against this — the fire is personal now.)"}, {"level": 11, "name": "Symphony of Ash", "cost_line": "Action · 8 CE · Once per combat.", "kind": "feature", "text": "**Action · 8 CE · Once per combat.** The program becomes a storm. Until the start of your next turn: - The Audience extends to **120 ft**. - Dirge becomes **3d6 fire**, and each creature that takes this damage must make a **CHA save** or be **frightened** of you until the end of its next turn (it sees Rome burning behind you). - Anthem grants allies within the performance **immunity to the frightened condition** and **advantage on their next attack roll** before the start of your next turn."}], "maximum": {"level": 18, "name": "The Eternal City Aflame (Maximum)", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "**Action · 10 CE.** For **1 minute** (sustained, no concentration — the city burns on its own), a **120-ft-radius** zone of burning Rome manifests, centered on you and moving with you: - Hostile creatures that start their turn in the zone take **4d6 fire damage** (DEX save for half). - The zone is **difficult terrain for hostiles only** — the flames part for the orchestra. - Willing allies that start your turn in the zone gain **10 temporary hit points** and immunity to fear. - Your lyre cannot be destroyed while the city burns (it is everywhere now)."}, "domain": null, "l20": {"level": 20, "name": "\"What an Artist Dies in Me\"", "cost_line": "", "kind": "l20", "text": "**Capstone.** Once per long rest, when you are reduced to 0 hit points while performing, you do not fall. You finish the piece: you immediately take a full turn (action, bonus action, movement) with all CE costs waived, your Dirge dice are doubled for that turn, and the Audience extends to 300 ft. At the end of that turn, you die — unless you have been restored above 0 HP, in which case the performance continues uninterrupted. *An artist does not leave the stage. The stage leaves him.*"}, "summary_text": null, "source_file": "11-nero.md"}, {"id": "elizabeth-b-thory", "module": "12", "figure": "Elizabeth Báthory", "title": "ELIZABETH BÁTHORY", "detail": "full", "technique": "The Crimson Bath", "tier": "III", "role": "Striker (drain)", "ce_ability": "CON", "primary_verb": "Drink", "region": "Hungary", "era": "1560–1614 · 16th–17th c.", "culture": "Hungarian", "concept": "The world locked a woman in a legend of blood and threw away the key — and she kept the legend, because the legend was the only thing that ever told the truth about what was done to her.", "serves": null, "features": [{"level": 1, "name": "First Sip & Aging Presence", "cost_line": "First Sip (passive).", "kind": "feature", "text": "**Tier III · Striker (drain) · Suggested CE ability: CON · Primary verb: *Drink*** *Your technique save DC = 8 + your proficiency bonus + your CON modifier. \"Living creature\" excludes constructs and undead — the bath only takes from the living. You track* ***Years Drunk***: *a pool (maximum = your proficiency bonus) that increases by 1 each time you reduce a living creature to 0 HP. Years fade after 24 hours if unspent — youth does not keep.*\n\n**First Sip (passive).** Once per turn, when you deal damage to a living creature with a weapon or unarmed attack, you regain hit points equal to **half the damage dealt** (rounded down). You must *take* to receive — no passive regeneration, ever. **Aging Presence (passive aura, 10 ft).** Hostile creatures within 10 ft of you have their speed **reduced by 5 ft** and feel their joints stiffen: they have **disadvantage on ability checks** made to escape grapples. The grass yellows where you stand."}, {"level": 3, "name": "Drink Deep & Crimson Vintage", "cost_line": "Drink Deep — Bonus action · 2 CE.", "kind": "feature", "text": "**Drink Deep — Bonus action · 2 CE.** After you have dealt damage to a living creature this turn, you drink deeply: gain **temporary hit points equal to the damage dealt** (before First Sip's healing). Once per round. **Crimson Vintage (spend Years).** You may spend Years Drunk as a free action on your turn: - **1 Year:** add **1d8 necrotic damage** to one attack's damage roll (the vintage burns). - **2 Years:** end one poisoned, diseased, or exhausted condition on yourself (the youth burns it out)."}, {"level": 6, "name": "The Bath Overflows", "cost_line": "Action · 4 CE.", "kind": "feature", "text": "**Action · 4 CE.** Blood answers blood. Each living hostile creature within **15 ft** must make a **CON save** or take **3d6 necrotic damage** (half on success) as their years flow visibly toward you — gray hairs, liver spots, a sudden stoop. You regain hit points equal to **half the total damage dealt** by this feature. **Aging Presence grows (passive).** The aura extends to **15 ft**; speed reduction becomes **10 ft**. While you hold **4+ Years Drunk**, hostiles in the aura also have **disadvantage on DEX saving throws** — their bodies betray them."}, {"level": 11, "name": "The Countess's Due", "cost_line": "Reaction · 5 CE · Once per round.", "kind": "feature", "text": "**Reaction · 5 CE · Once per round.** When a living creature within **30 ft** of you dies, you drink the moment itself: gain **2d8 + your CON modifier** temporary hit points and **+1 Year Drunk**. You feel the exact second the years change hands. It is, witnesses say, the only time she ever looks peaceful."}], "maximum": {"level": 18, "name": "Eternal Vintage (Maximum)", "cost_line": "The Last Bath — Action · 10 CE.", "kind": "maximum", "text": "**The Last Bath — Action · 10 CE.** You draw the bath around you. Each living hostile creature within **30 ft** must make a **CON save** or take **8d6 necrotic damage** (half on success). You regain hit points equal to the **total damage dealt**. Each creature reduced to 0 HP by this feature grants **2 Years Drunk** instead of 1. Your Years Drunk maximum becomes **twice your proficiency bonus**."}, "domain": null, "l20": {"level": 20, "name": "Never Old, Never Caught", "cost_line": "", "kind": "l20", "text": "**Capstone.** The vow's promise, fulfilled in flesh: - You are **ageless**: immune to magical aging, disease, and poison (the blood is always fresh). - Once per long rest, when you would be reduced to 0 hit points, you may instead **discard all Years Drunk** and return with **1 hit point per Year discarded** — the bath gives back what was taken. If you held no Years, this does nothing. *Keep the vintage close.*"}, "summary_text": null, "source_file": "12-bathory.md"}, {"id": "attila", "module": "13", "figure": "Attila", "title": "ATTILA", "detail": "full", "technique": "Scourge of God", "tier": "III", "role": "Brute", "ce_ability": "STR", "primary_verb": "Trample", "region": "Eurasian steppe", "era": "406–453 · 5th c.", "culture": "Hunnic", "concept": "The chroniclers wrote that the grass never grew where his horse had trod — and he has come west again to prove them right about everything.", "serves": null, "features": [{"level": 1, "name": "The Tread", "cost_line": "Passive.", "kind": "feature", "text": "**Tier III · Brute · Suggested CE ability: STR · Primary verb: *Trample*** *Your technique save DC = 8 + your proficiency bonus + your STR modifier. \"Cursed ground\" means difficult terrain created by your technique: it hinders your enemies but never you or your willing allies. A* ***charge*** *means moving at least 20 ft in a straight line toward a hostile creature immediately before attacking it.*\n\n**Passive.** You are the ground's enemy and its master: - Cursed ground you create never counts as difficult terrain for you. - When you charge, your first melee attack that turn deals an extra **1d8 damage** (the momentum). - **Scorched Step:** spaces you move through during your turn become cursed ground (difficult terrain for your enemies) until the end of your next turn. The grass dies where your horse — or your boots — pass."}, {"level": 3, "name": "Scourge's Wake & Trample", "cost_line": "Scourge's Wake — Bonus action · 2 CE.", "kind": "feature", "text": "**Scourge's Wake — Bonus action · 2 CE.** The dead ground spreads: a **15-ft-radius** around you becomes cursed ground for **1 minute**. Your enemies wade. You ride. **Trample (passive).** While charging, you may move through a hostile creature's space. That creature must make a **STR save** or take **2d6 bludgeoning damage** and be knocked **prone**. On a success, it takes half damage and is not prone. (You cannot end your move in its space.)"}, {"level": 6, "name": "Break the Walls", "cost_line": "Action · 4 CE.", "kind": "feature", "text": "**Action · 4 CE.** The shock charge. Move up to your speed in a straight line — you may pass through hostile spaces (Trample applies to each, once per creature) and you do not provoke opportunity attacks during this movement. Each hostile creature you pass within 5 ft of must make a **DEX save** or take **4d6 bludgeoning damage** and be pushed **10 ft** away from your path (half damage on success, no push). You have **advantage** on this damage against structures, fortifications, and barriers — walls are what you are *for*."}, {"level": 11, "name": "The Horde Answers", "cost_line": "Bonus action · 5 CE.", "kind": "feature", "text": "**Bonus action · 5 CE.** You sound the horn the steppe remembers. For **1 minute**, willing allies within **30 ft** of you gain **+10 ft speed** and **+2 to damage rolls** (the horde's momentum), and your charge bonus increases to **+2d8**. Spectral riders flicker at the edges of vision — the dead keeping pace. (They are atmosphere, not combatants; the buff is the mechanic.)"}], "maximum": {"level": 18, "name": "Flagellum Dei (Maximum)", "cost_line": "Action · 8 CE.", "kind": "maximum", "text": "**Action · 8 CE.** The great charge. You move up to **60 ft** in a straight line, passing through hostile spaces without provoking opportunity attacks. Each hostile creature within **10 ft** of your path must make a **STR save** or take **8d6 bludgeoning damage** and be knocked prone (half damage on success, not prone). The ground along your path becomes cursed ground for **1 hour** — and this time, it does not fade: only *hallow*, *wish*-level cleansing, or the deliberate tending of the land removes it. The General's surveyors will find this line on maps for years."}, "domain": null, "l20": {"level": 20, "name": "The Grass Never Grows Back", "cost_line": "", "kind": "l20", "text": "**Capstone.** The chroniclers were right, permanently: - Your Scorched Step and Scourge's Wake now leave **permanent** cursed ground (removed only as Flagellum Dei's, above). You are terraforming the world one ride at a time. - Once per combat, when you reduce a hostile creature to 0 HP with a charge attack, you may immediately move up to **half your speed** (it must be a straight line toward another hostile) and make **one melee attack** against a creature you reach. *The ride continues.*"}, "summary_text": null, "source_file": "13-attila.md"}, {"id": "baba-yaga", "module": "14", "figure": "Baba Yaga", "title": "BABA YAGA", "detail": "full", "technique": "The Hut Turns", "tier": "IV", "role": "Controller / Caster", "ce_ability": "WIS", "primary_verb": "Hunger", "region": "Eastern Europe", "era": "folklore · undated", "culture": "Slavic folklore", "concept": "Every village had a witch in the woods to frighten the children — and the children were right. Knock twice.", "serves": null, "features": [{"level": 1, "name": "The Fence of Bones & Knock Twice", "cost_line": "The Fence of Bones — Action · 2 CE.", "kind": "feature", "text": "**Tier IV · Controller / Caster · Suggested CE ability: WIS · Primary verb: *Hunger*** *Your technique save DC = 8 + your proficiency bonus + your WIS modifier. \"Your terrain\" means any area affected by your technique features. You are never hindered by your own terrain. The* ***hut*** *is a Huge construct-dwelling: AC 15, HP 60, immune to poison and psychic. If destroyed, it collapses into kindling and bone — and rebuilds itself at dusk, because of course it does.*\n\n**The Fence of Bones — Action · 2 CE.** Bone rises from the ground: a **20-ft-radius** zone becomes your terrain for **1 minute** — difficult terrain for your enemies, and any hostile creature that starts its turn inside takes **1d6 piercing damage** (the bones are sharp, and they lean toward the living). **Knock Twice (passive).** You always know when a creature enters your terrain — you feel the knock. This is not sight or hearing; it cannot be hidden from by invisibility or silence. The hut knows its guests."}, {"level": 3, "name": "The Mortar Flies & Root Grasp", "cost_line": "The Mortar Flies — Bonus action · 3 CE.", "kind": "feature", "text": "**The Mortar Flies — Bonus action · 3 CE.** You climb into the mortar and *go*: gain a **flying speed of 50 ft** until the end of your next turn, and you do not provoke opportunity attacks while flying this way. Your trail is swept away — you leave no tracks, and tracking you by non-magical means is impossible for 1 hour. **Root Grasp — Action · 3 CE.** The forest reaches. Each hostile creature in a **30-ft-radius** centered within 60 ft of you must make a **STR save** or take **2d6 bludgeoning damage** and be **restrained** by roots (half damage on success, not restrained). A restrained creature may repeat the save at the end of each of its turns, freeing itself on a success. *The forest is patient. It can wait.*"}, {"level": 6, "name": "The Hut Turns", "cost_line": "Action · 5 CE.", "kind": "feature", "text": "**Action · 5 CE.** The hut comes. A Huge hut on chicken legs manifests in an unoccupied space within **60 ft** and persists for **1 minute**: - At the start of each of your turns, you may move the hut up to **30 ft** (it strides; it does not provoke opportunity attacks). - Each hostile creature within **10 ft** of the hut when it moves must make a **DEX save** or take **3d6 bludgeoning damage** (half on success) — trampled by the chicken legs. - You may enter or exit the hut as a **bonus action**; while inside, you have **total cover**. - The hut counts as your terrain in a 10-ft radius around it (bone-fence effects apply). *Counterplay, stated plainly: the hut can be destroyed (AC 15, HP 60). Burn it. She will rebuild it by dusk — but a fight is shorter than a day.*"}, {"level": 11, "name": "Eat the Path & Baba's Test", "cost_line": "Eat the Path — Action · 8 CE.", "kind": "feature", "text": "**Eat the Path — Action · 8 CE.** The forest itself hungers. A **60-ft-radius** centered within 120 ft of you becomes primeval for **1 minute**: it is difficult terrain and heavily obscured **for your enemies only** (you and your allies see through it perfectly — the forest shows its friends the paths). Each hostile creature inside must make a **WIS save** or be **frightened** of the trees for 1 minute (it sees the bones in the branches). A frightened creature may repeat the save at the end of each of its turns. **Baba's Test (passive).** Once per round, when a hostile creature fails a saving throw against your technique, you may ask it **one question**, and it must answer truthfully. (This is not mind control — it is *folklore*, and folklore is heavier than magic. It grants no further compulsion.)"}], "maximum": {"level": 18, "name": "The Wild Takes Back (Maximum)", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "**Action · 10 CE.** For **1 minute**, a **120-ft-radius** centered on you becomes old-growth forest that has never known an axe: - Hostile creatures that start their turn inside take **4d6 bludgeoning damage** (DEX save for half) as branches lash. - The area is difficult terrain for hostiles, and any hostile that fails its DEX save is also **restrained** until the end of its next turn (roots within roots). - Whenever a hostile creature fails a saving throw against your technique inside this forest, you regain **2d8 hit points** — the forest feeds its grandmother."}, "domain": {"level": null, "name": "\"The Hut Walks at Night\"", "cost_line": "Full-turn action · 20 CE · Undisclosed.", "kind": "domain", "text": "**Full-turn action · 20 CE · Undisclosed.** The forest stops pretending to be a forest. A **60-ft-radius** domain of bone, root, and hunger manifests — **800 clash points**, **burnout 5 rounds · duration 2 minutes**. The sure-hit is the grasp itself: every hostile creature in the domain is **restrained** by roots that do not miss (no attack roll; the restraint is the sure-hit). A restrained creature takes **3d6 piercing damage** at the start of each of its turns (the bone fence leans in) and may attempt to escape as normal (STR or DEX vs. your technique save DC) at the end of its turns. While the domain stands, your hut may move **60 ft** per turn instead of 30, and you regain **1d8 hit points** whenever a hostile fails a save inside. *The hut walks at night. Pray it walks past you.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": null, "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "Grandmother of the Woods", "cost_line": "", "kind": "l20", "text": "**Capstone.** The forest keeps its own: - While in a forest, you cannot be located by divination or scrying — you are *the woods*, and the woods are everywhere. - Once per day, if you are reduced to 0 hit points while in a forest, you do not die: you dissolve into the trees and **reappear 1 minute later at full hit points** at any point within 1 mile of where you fell. This fails only if the forest itself has been destroyed (burned to ash, every root) — *and she will remember who burned it.*"}, "summary_text": null, "source_file": "14-baba-yaga.md"}, {"id": "la-llorona", "module": "15", "figure": "La Llorona", "title": "LA LLORONA", "detail": "full", "technique": "The River Keeps", "tier": "II", "role": "Controller", "ce_ability": "CHA", "primary_verb": "Weep", "region": "Mexico", "era": "folklore · colonial", "culture": "Mexican folklore", "concept": "She is still looking for her children. Do not answer if she calls your name.", "serves": null, "features": [{"level": 1, "name": "The Weeping & Salt Water", "cost_line": "The Weeping — Action · 1 CE.", "kind": "feature", "text": "**Tier II · Controller · Suggested CE ability: CHA · Primary verb: *Weep*** *Your technique save DC = 8 + your proficiency bonus + your CHA modifier. \"Her water\" means any area flooded by your technique: black, still, salt-tasting, difficult terrain for your enemies. She knows the name of anyone who has lost someone — and speaks it in the dead one's voice.*\n\n**The Weeping — Action · 1 CE.** You wail. Each hostile creature within **30 ft** that can hear you must make a **WIS save** or be **frightened** until the end of its next turn — it hears the voice of someone it grieves for, weeping. (A creature that is deafened is unaffected; silence, again, is safety.) **Salt Water (passive).** Open water within **30 ft** of you turns black and still. It is difficult terrain for your enemies to wade through, and it tastes of salt. No one can explain why."}, {"level": 3, "name": "Come to the Water & The Riverbed", "cost_line": "Come to the Water — Action · 3 CE.", "kind": "feature", "text": "**Come to the Water — Action · 3 CE.** Choose one creature within **30 ft** that can hear you. It must make a **WIS save** or use its reaction to move up to **15 ft** toward you — toward the nearest of her water. It does not want to. Its feet do not care. (This is forced movement, not charm; it cannot be *talked* out of, only saved against.) **The Riverbed — Bonus action · 2 CE.** You flood a **20-ft-radius** area within 60 ft: it becomes 2-ft-deep black water — her water — for **1 minute**. Difficult terrain for enemies. The weeping is louder here."}, {"level": 6, "name": "Drown the Sorrow & Her Children's Names", "cost_line": "Drown the Sorrow — Action · 5 CE.", "kind": "feature", "text": "**Drown the Sorrow — Action · 5 CE.** Each hostile creature standing in her water must make a **CON save** or begin **drowning in grief**: while it remains in her water, it cannot breathe (if it needs to breathe, use the standard suffocation rules — it can hold its breath for 1 + its CON modifier minutes before it begins suffocating), its speed is **halved**, and at the start of each of its turns it takes **2d6 psychic damage** (the sorrow gets in through the lungs). Leaving her water ends the effect. *The river keeps what it catches.* **Her Children's Names (passive).** You speak the names of the dead they carry — and the grieving listen harder: hostile creatures have **disadvantage** on saving throws against your Weeping if you have spoken the name of someone they lost (you always know one; the river told you)."}, {"level": 18, "name": "All Waters Are Hers", "cost_line": "Passive.", "kind": "feature", "text": "**Passive.** The ranges of your Weeping, Come to the Water, and The Riverbed **double**. Her water now counts as deep enough to swim in — and to drown in. **The Drowning of Names — Action · 10 CE.** Each hostile creature in her water must make a **CHA save** or be overwhelmed: it is **incapacitated**, weeping, for **1 minute** — it sinks to its knees in the black water and calls back. It may repeat the save at the end of each of its turns. (Creatures that cannot grieve — constructs, most undead — are immune. She has no quarrel with them.)"}], "maximum": {"level": 11, "name": "The Flood Remembers (Maximum)", "cost_line": "Action · 8 CE.", "kind": "maximum", "text": "**Action · 8 CE.** For **1 minute**, a **60-ft-radius** centered within 120 ft of you floods — her water, deep and black: - The area is difficult terrain for your enemies. - Each hostile creature that starts its turn in the flood must make a **WIS save** or take **3d6 psychic damage** and be **pulled 10 ft toward you** (the river leans). - You gain a swim speed equal to your walking speed and can breathe water. *All waters are hers, while she weeps.*"}, "domain": null, "l20": {"level": 20, "name": "She Cannot Be Ended", "cost_line": "", "kind": "l20", "text": "**Capstone.** While grief remains in the world, so does she: - Once per day, when you would be destroyed, you instead **dissolve into mist** and reform at the next rainfall at the nearest river, lake, or shore — whole, weeping, searching. She cannot be *killed*. She can only be driven off, outwaited, or — the hardest thing — *comforted*. - If a creature **weeps with her** — genuinely, openly sharing its grief — she cannot target it, flood beneath it, or call its names for 24 hours. Shared sorrow is sanctuary, and she honors it absolutely. *This is not a weakness. It is the only true thing about her.*"}, "summary_text": null, "source_file": "15-la-llorona.md"}, {"id": "the-golem-of-prague", "module": "16", "figure": "The Golem of Prague", "title": "THE GOLEM OF PRAGUE", "detail": "full", "technique": "EMETH, THE TRUTH", "tier": "III", "role": "Tank / Brute", "ce_ability": "CON", "primary_verb": "Guard", "region": "Prague", "era": "1582 · 16th c.", "culture": "Jewish / Bohemian", "concept": "It was built to protect them, and they feared it anyway — and fear, left to ferment for four hundred years, is a kind of truth too.", "serves": null, "features": [{"level": 1, "name": "The Word on the Brow", "cost_line": "passive", "kind": "feature", "text": "**Tier III · Tank / Brute · Suggested CE ability: CON · Primary verb: *Guard.*** *The Golem's technique save DC = 8 + its proficiency bonus + its CON modifier.* *The complete playable write-up. The GM kit above (brow-word kill-switch, command-word bidding, imprint) rides on top of these mechanics, not instead of them.*\n\nWhile the word EMETH stands upon its brow, the Golem cannot be charmed, frightened, possessed, or put to sleep by any means, and it is immune to psychic damage. Divination effects that would locate or identify it return only the word — *truth, truth, truth* — repeated. **Kill-switch:** erasing the first letter (an action by a creature within 5 ft that can reach the brow; DC 18 INT check or appropriate tool use under pressure) changes the word to METH (death). The Golem deactivates instantly — no save, no resistance. Rewriting the letter reactivates it with its growth reset."}, {"level": 1, "name": "Command Words", "cost_line": "bonus action, 0 CE", "kind": "feature", "text": "Any creature that knows a true command word and speaks it clearly (audible, within 60 ft of the Golem) issues one command as a bonus action: **GUARD** (defend a named creature or area), **COME** (move to the speaker), **STAY** (hold position, take no actions), **BREAK** (attack a named target or destroy a named object), **KNEEL** (go prone, take no actions until commanded). The Golem obeys the **most recently spoken** word, regardless of who spoke it. Words are learned by hearing one used as a command, by lore (DC 20 History or Arcana), or from Sun's network. It cannot be commanded to harm its imprinted ward, or to stand by while its ward takes damage — the original vow outranks all later commands. **Unguarded GUARD:** a GUARD command that names no creature or area is dangerous — the Golem widens its definition of \"threat\" the longer it goes uncountermanded, escalating until a true command word countermands it."}, {"level": 1, "name": "Clay Fists", "cost_line": "action", "kind": "feature", "text": "Melee slam: +PB + STR modifier to hit, reach 5 ft, **2d8 + STR bludgeoning** damage. The Golem's unarmed strikes count as magical for overcoming resistance (the word sanctifies the clay)."}, {"level": 3, "name": "Growing Truth", "cost_line": "passive", "kind": "feature", "text": "At the start of each of its turns in combat, the Golem grows one size step: Medium → Large → Huge (cap: Huge at Tier III). Each growth: slam damage **+1d8**, maximum HP **+15**, and reach **+5 ft** at Large and again at Huge. Its weight doubles each step — floors, bridges, and ice treat it as a siege hazard (GM's call; it breaks what it stands on). Growth resets when it deactivates. Out of combat, it slowly settles back toward Medium over one hour."}, {"level": 3, "name": "Guard the Hunted", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When a creature within 30 ft of the Golem takes damage, the Golem may move up to its speed toward that creature (this movement provokes no opportunity attacks — the street parts) and **take the damage in its place**. If the creature is its imprinted ward, this reaction costs 0 CE. The Golem imprints on the first hunted creature it successfully defends this way."}, {"level": 6, "name": "Weight of Truth", "cost_line": "passive", "kind": "feature", "text": "Its slam attacks now carry the street with them. On a hit, the target must succeed on a STR saving throw vs the technique DC or be **knocked prone and pushed 10 feet**. The impact cracks the ground: the 10-ft radius around the point of impact becomes difficult terrain for 1 minute (clay remembers every footprint)."}, {"level": 6, "name": "Swallow the Blow", "cost_line": "reaction, 1 CE", "kind": "feature", "text": "When the Golem takes bludgeoning, piercing, or slashing damage, it may spend 1 CE to gain **resistance to that instance** of damage — the clay ripples and absorbs the blow. (One instance per reaction; the oldest trick in the street-fighter's book, perfected.)"}, {"level": 11, "name": "Unstoppable Guardian", "cost_line": "bonus action, 5 CE", "kind": "feature", "text": "For 1 minute: the Golem cannot be grappled, restrained, or moved against its will by any means; it gains a **trample** — when it moves through a hostile creature's space, that creature takes its slam damage (DEX save vs technique DC for half). Barricades, walls, and doors are difficult terrain to it, not obstacles."}, {"level": 11, "name": "Shem of Mending", "cost_line": "bonus action, 4 CE", "kind": "feature", "text": "The Golem presses a parchment shem to its own chest: it regains **4d8 + CON modifier** HP as the clay knits itself closed. Usable twice per long rest — the names of God are not to be spent lightly."}, {"level": 18, "name": "The Golem Speaks", "cost_line": "action, 10 CE", "kind": "feature", "text": "Once per long rest, the clay finds a voice. For 1 minute, the Golem **embodies absolute TRUTH**: - It gains **truesight 120 ft** — lies, disguises, illusions, and hidden things are simply *visible*. Its slam attacks deal **double damage** to creatures that are lying, magically disguised, or concealed by illusion (the clay strikes the false thing underneath). - **Erase and rewrite:** once during the duration, when it would be reduced to 0 HP, it instead drops to 1 HP and immediately regains HP equal to half its maximum — the word on its brow flickers from METH back to EMETH. The death that un-dies."}], "maximum": null, "domain": null, "l20": {"level": 20, "name": "No More Sabbaths (capstone, passive)", "cost_line": "capstone, passive", "kind": "l20", "text": "The old rhythm — deactivation every Sabbath, the weekly sleep the Maharal built in — is gone, worn away by four centuries of fear. The Golem no longer settles out of combat; it remains at whatever size it last held (up to Huge), and its growth cap rises to **Gargantuan**. And the kill-switch narrows to a tragedy: the brow-word can now only be erased by a creature the Golem has **imprinted on as a ward**. Only the protected can unmake the protector. Sun's network knows this. The ward probably does not."}, "summary_text": null, "source_file": "16-golem.md"}, {"id": "tamamo-no-mae", "module": "17", "figure": "Tamamo-no-Mae", "title": "TAMAMO-NO-MAE", "detail": "full", "technique": "NINE SHADOWS OF THE COURT", "tier": "V", "role": "Controller / Illusionist", "ce_ability": "CHA", "primary_verb": "Enchant", "region": "Japan", "era": "Heian · 8th–12th c.", "culture": "Japanese myth", "concept": "Every dynasty that tried to use her ended smiling — and every smile was hers.", "serves": null, "features": [{"level": 1, "name": "Foxfire", "cost_line": "action, 1 CE", "kind": "feature", "text": "**Tier V · Controller / Illusionist · Suggested CE ability: CHA · Primary verb: *Enchant.*** *Your technique save DC = 8 + your proficiency bonus + your CHA modifier. Your technique attack bonus = your proficiency bonus + your CHA modifier.*\n\nRanged spell attack (+PB + CHA to hit), **120 ft**: **2d10 fire + 1d6 psychic** damage — the flame burns the *idea* of you; the psychic portion aches in memory first. Foxfire **ignores half and three-quarters cover** (it curves around obstacles, the way desire does). Flammable objects ignited by foxfire burn blue-white and cannot be extinguished by mundane means for 1 minute."}, {"level": 1, "name": "Nine Shadows", "cost_line": "bonus action, 2 CE per shadow", "kind": "feature", "text": "Create up to **nine** illusory duplicates — her court personas, given temporary flesh. Each shadow: **AC 15**, HP equal to **5 × her CHA modifier** (minimum 10), speed 30 ft, and it may cast **foxfire** using her attack bonus, dealing **half damage**. Shadows act on her initiative, directly after her. When a shadow is destroyed, she takes **5 psychic damage** (feedback — the persona *felt* it). She may have at most **nine** shadows active. Re-summoning a destroyed shadow costs the full 2 CE again. (The ninth tail is never manifested as a shadow. See the GM kit.)"}, {"level": 3, "name": "The Court Wants", "cost_line": "action, 3 CE", "kind": "feature", "text": "One creature within **60 ft** that can see her: WIS save vs technique DC. On failure, the creature is **charmed for 1 hour** — and she appears to it as what it most desires or trusts (the reflection, not an illusion; *detect magic* shows nothing, because there is nothing to detect). While charmed this way, the victim becomes a **courtier**: Tamamo can **perceive through its senses** as a free action. The victim re-saves when it takes damage from her or witnesses her harming someone it loves. *This is the dangerous one. The GM should track courtiers the way other GMs track initiative.*"}, {"level": 3, "name": "Never Where You Think", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When Tamamo is targeted by an attack, she may **swap positions** with one of her shadows within 60 ft — the attack targets the shadow instead, resolved against its AC. If no shadow is in range, she may instead impose **disadvantage** on the attack (a flicker of eight tails, and the blade finds the wrong woman)."}, {"level": 6, "name": "Sessho-seki's Breath", "cost_line": "action, 5 CE", "kind": "feature", "text": "She exhales the Killing Stone's vapor: a **30-ft cone**, CON save vs technique DC or **6d8 poison** damage and **poisoned for 1 minute** (re-save at the end of each turn). The vapor smells of hot rock and old perfume. Vegetation in the cone dies instantly and does not regrow for a year."}, {"level": 6, "name": "Wear the Shadow", "cost_line": "bonus action, 3 CE", "kind": "feature", "text": "She assumes one of her shadows' forms **completely** — voice, memories, mannerisms, scent. For 1 hour: **+10 to Deception** checks made as that persona, and divination effects (including *true seeing* below 7th level) perceive the shadow's identity, not hers. She has used this to be three different advisors in three different capitals in a single week."}, {"level": 11, "name": "The Smile That Ruins Kingdoms", "cost_line": "action, 8 CE", "kind": "feature", "text": "Every creature of her choice within **60 ft** that can see her: WIS save vs technique DC or **charmed for 1 minute**. While charmed by this, victims regard her spoken wishes as **suggestions from a beloved ruler** — they will obey any instruction that isn't obviously self-destructive (as *suggestion*, no concentration required, but one instruction per victim). Re-save when ordered to harm someone they love. *Daji smiled, and the Shang fell. The mechanism has not changed. Only the kingdoms are larger.*"}, {"level": 11, "name": "Tails as Lives", "cost_line": "passive", "kind": "feature", "text": "When Tamamo would be reduced to 0 HP, **a tail is severed instead**: all active shadows are destroyed, she is restored to **half her maximum HP**, and she teleports up to **120 ft** in a flash of foxfire (leaving no trace — not even ash). Usable **once per long rest**. Narratively, she has nine tails to spend; mechanically, the table only ever sees her spend one. The second time should not happen in the same campaign."}, {"level": 18, "name": "The Ninth Tail", "cost_line": "action, 10 CE", "kind": "feature", "text": "She reveals what was never shown. For **1 minute**, all nine tails manifest openly — the sky bruises violet, the air smells of ruin and plum wine: - shadows may be re-summoned as a **bonus action for 1 CE each** (no action required); - **foxfire deals double dice**; - creatures have **disadvantage on saves** against The Court Wants and The Smile That Ruins Kingdoms; - she gains **truesight 60 ft** (the ninth tail *sees*). When it ends, one shadow — one persona, one life — is **banished for a century** (GM's choice which; she will mourn it theatrically and mean it not at all). Power has a price. Hers is just denominated in centuries."}], "maximum": null, "domain": {"level": null, "name": "\"THE GILDED CAGE OF NINE TAILS\" (disclosed rule-domain)", "cost_line": "20 CE, full-turn action. 60-ft radius. Clash 1,000 · burnout 3 rounds.", "kind": "domain", "text": "A Heian court at midnight — lanterns, silk screens, the scent of plum wine, nine shadows moving behind every screen. The sure-hit is **etiquette**: every hostile within perceives Tamamo as their **most trusted beloved**, and the court's first law is spoken by Heaven itself — ***none raise a hand against the lady.*** Mechanically: a hostile that wishes to attack Tamamo (or include her in an area effect) must first succeed on a **WIS save vs technique DC at the start of its turn**; on failure, it **cannot target her** that turn (it may act otherwise freely — the cage is gilded, not locked). Creatures that fail by 5 or more are **charmed until the start of their next turn** as well. This is a rule-domain compulsion — nonlethal, save-gated, Heaven-witnessed. It does not make her invincible. It makes *hitting* her cost the one thing no warrior wants to spend: certainty.", "clash_points": 1000, "duration_min": 3, "burnout_rounds": 3, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Pattern Eternal (capstone, passive)", "cost_line": "capstone, passive", "kind": "l20", "text": "She stops pretending to be one woman. - **Narrative phylactery:** if slain, she **reforms in 1d10 days** wherever three or more people speak her story with fear — Daji, Bao Si, Tamamo, the fox-wife, any telling of the pattern. Destroying her permanently requires what no army has managed in three thousand years: **making the world stop telling the story.** (Sun's network has a standing project. It is not going well.) - **The court is forever:** victims of The Court Wants no longer re-save when damaged — the charm lasts until *remove curse* (6th level or higher), a year passes, or she releases them. Her courtiers are *hers*. - **The twelfth tail:** once per century, she may grow a **tenth shadow** — a persona with no history, no story, nothing the world has ever feared. Perfect cover. She is saving it. The GM should be faintly terrified of what she's saving it *for*."}, "summary_text": null, "source_file": "17-tamamo.md"}, {"id": "hypatia-of-alexandria", "module": "18", "figure": "Hypatia of Alexandria", "title": "HYPATIA OF ALEXANDRIA", "detail": "full", "technique": "THE LIBRARY BURNS", "tier": "IV", "role": "Versatile Blaster", "ce_ability": "INT", "primary_verb": "Know", "region": "Alexandria", "era": "c. 350–415 · 4th–5th c.", "culture": "Hellenistic Egyptian", "concept": "They killed her for knowing things, and now everything she knows is a weapon.", "serves": null, "features": [{"level": 1, "name": "The Ashen Catalogue", "cost_line": "passive", "kind": "feature", "text": "**Tier IV · Versatile Blaster · Suggested CE ability: INT · Primary verb: *Know.*** *Your technique save DC = 8 + your proficiency bonus + your INT modifier. Your technique attack bonus = your proficiency bonus + your INT modifier.*\n\nHypatia prepares \"scrolls\" — spells — from the ghost-shelves. She may prepare **INT modifier + level** spells chosen from the **entire wizard and sorcerer spell lists** (the burned books hold everything). She casts them as technique activations using CE instead of spell slots: CE cost = **2 × spell level** (cantrips 0 CE, cast as the *Prestidigitation*-of-ash: minor telekinesis of paper and cinder). Spell save DC and attack bonus use her technique DC. Spells retain their normal casting times, ranges, and other rules — only the resource (CE instead of slots) and the DC/attack bonus change. *She does not learn spells. She remembers where the ashes are.*"}, {"level": 1, "name": "Marginalia", "cost_line": "bonus action, 1 CE", "kind": "feature", "text": "She annotates a creature she can see within 120 ft: make an **INT (Arcana) check vs DC 12 + the target's CR** (or 10 + its PB, whichever the GM prefers). On success, she learns its **damage resistances, vulnerabilities, immunities, and condition immunities** — written in burning script in the air beside it, visible to her allies. She may maintain annotations on up to **INT modifier** creatures at once."}, {"level": 3, "name": "Peer Review", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When Hypatia **observes** a creature cast a spell or activate a named technique feature, she may make an INT check vs **DC 13 + the spell's level** (or 10 + the user's PB for technique features). On success, she names its weakness aloud — choose **one**, lasting 1 minute: - **Refuted resistance:** the next attack or spell the party makes against that creature **ignores its damage resistances** (not immunities). - **Unsound premise:** the creature has **disadvantage on saves** against the next spell or technique effect that targets it. - **Catalogued:** Hypatia (and any ally she tells as a free action) learns the effect's **exact mechanics** — range, damage, save, duration. No more surprises. She may maintain Peer Review on up to INT modifier creatures. She delivers each one as a lecture. The table should *dread* the words *\"I see the flaw.\"*"}, {"level": 3, "name": "Burning Scroll", "cost_line": "action, 3 CE", "kind": "feature", "text": "She hurls a scroll that combusts mid-flight. Ranged spell attack (+PB + INT to hit), **120 ft**: **4d8 fire** damage, and the target must succeed on an INT save vs technique DC or have **one damage resistance of Hypatia's choice suppressed** until the end of her next turn — the fire *reads* them, and reading is the first step to unmaking."}, {"level": 6, "name": "Theorem of Falling Bodies", "cost_line": "action, 4 CE", "kind": "feature", "text": "*Philoponus refuted Aristotle; she refutes you.* A **20-ft cube** within 120 ft: STR save vs technique DC or **5d8 bludgeoning** damage and **restrained** (pinned by the proof) until the save ends at the end of their turns. The cube's floor cracks into geometric fractures — difficult terrain for 1 hour."}, {"level": 6, "name": "The Catalogue Defends", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When she is targeted by a spell or technique effect that allows a save, she may quote the counter-theorem: she gains **advantage on the save**, and if she succeeds, the originator takes **2d8 psychic** damage as their own logic is turned — with a footnote."}, {"level": 11, "name": "Disputation", "cost_line": "action, 8 CE", "kind": "feature", "text": "The formal refutation. All enemies within **60 ft**: INT save vs technique DC or be **refuted for 1 minute** — disadvantage on attack rolls, disadvantage on saves against her spells and technique effects, and they **cannot benefit from advantage** on any roll (their premises are unsound; the universe declines to assist). Re-save at the end of each of their turns."}, {"level": 11, "name": "Scrollstorm", "cost_line": "action, 6 CE", "kind": "feature", "text": "A **40-ft radius** within 120 ft fills with burning vellum: **8d6 slashing** damage (DEX save half — a thousand paper cuts, each one a lost page), and the area becomes difficult terrain of hot ash for 1 minute."}, {"level": 18, "name": "The Burning of the Library", "cost_line": "action, 10 CE", "kind": "feature", "text": "The Maximum. For **1 minute**, she *becomes* the burning Library: - **Ashen wings:** fly speed 60 ft. - **Immunity to fire** damage; resistance to all other damage except psychic (the body is cinder and conviction). - **The shelves are infinite:** each turn, as a **bonus action**, she may cast one prepared spell of **5th level or lower** without spending CE. - **Unburn (once):** during the duration, she may restore one destroyed object or text from its ashes — a burned letter, a destroyed map, a lost page — perfectly, permanently. (The GM decides what this unlocks. It should always unlock *too much*.)"}], "maximum": null, "domain": {"level": null, "name": "\"THE ALEXANDRIA THAT BURNED\" (disclosed)", "cost_line": "20 CE, full-turn action. 60-ft radius. Clash 800 · burnout 5 rounds.", "kind": "domain", "text": "The reading room as it was, the night of the fire — shelves infinite, smoke sweet with burning vellum, the dome open to a sky of falling stars. The sure-hit is **cataloguing**: every hostile within is *perfectly known* — Hypatia automatically learns their full defensive profile (no Marginalia check needed), gains **truesight 120 ft** (illusions, disguises, and shapechanging fail automatically within), and **lies spoken within deal 4d8 psychic damage to the liar** as Heaven marks the falsehood. *She learned the shape of this Domain from studying Sun Tzu's War Room — or he learned his from studying her ashes. The Commentators disagree. Neither of them will say.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Unburnable (capstone, passive)", "cost_line": "capstone, passive", "kind": "l20", "text": "She cannot be unmade by fire or by forgetting. If destroyed, she **reconstitutes from any ashes within 1 mile in 24 hours** — unless the ashes are *read*: someone must read her story aloud, truly and completely, from a true copy, over the ashes. The kill condition is **witness**. (Sun's network has standing orders: no true copies leave the restricted section. Ever.) And the Catalogue opens fully: her prepared list becomes **unlimited** — every wizard and sorcerer spell, always prepared. The shelves were never the limit. The librarian's *patience* was."}, "summary_text": null, "source_file": "18-hypatia.md"}, {"id": "william-wallace", "module": "19", "figure": "William Wallace", "title": "WILLIAM WALLACE", "detail": "full", "technique": "THEY MAY TAKE OUR LIVES", "tier": "III", "role": "Support / Striker", "ce_ability": "CHA", "primary_verb": "Endure", "region": "Scotland", "era": "c. 1270–1305 · 13th–14th c.", "culture": "Scottish", "concept": "They took his life in pieces, and every piece is still fighting.", "serves": null, "features": [{"level": 1, "name": "The Martyr's Ledger", "cost_line": "passive", "kind": "feature", "text": "**Tier III · Support / Striker · Suggested CE ability: CHA · Primary verb: *Endure.*** *Your technique save DC = 8 + your proficiency bonus + your CHA modifier.*\n\nWallace tracks all damage taken by **willing creatures within 60 ft** of him since his last turn — the Ledger. At the start of each of his turns, every willing creature in the aura gains **temporary HP equal to half the Ledger's total** (rounded down), distributed as Wallace chooses (he may pile it onto the dying). The Ledger resets each round. Pain, entered promptly, pays out promptly."}, {"level": 1, "name": "Claymore", "cost_line": "action", "kind": "feature", "text": "Melee weapon attack: +PB + STR to hit, reach 5 ft, **2d6 + STR slashing**, heavy, two-handed. On a critical hit, the target must succeed on a WIS save vs the technique DC or be **frightened of Wallace for 1 minute** (the executioner's shadow falls across the field). Against *crowned* targets (kings, tyrants, those who rule by blood-right), the claymore deals an additional **1d8 force damage** — the sword knows."}, {"level": 3, "name": "Stirling Cry", "cost_line": "bonus action, 2 CE", "kind": "feature", "text": "All willing creatures within 60 ft gain **+2 to attack rolls** until the start of his next turn. If any of them took damage since his last turn, the bonus becomes **+3 to attacks and +2 to damage** — the line steadies *because* it bled."}, {"level": 3, "name": "Take the Field", "cost_line": "reaction, 1 CE", "kind": "feature", "text": "When a willing creature within 30 ft is hit by an attack, Wallace may move up to his speed toward the attacker (this movement provokes no opportunity attacks — the field opens for him) and make one claymore attack against it."}, {"level": 6, "name": "Falkirk Line", "cost_line": "action, 4 CE", "kind": "feature", "text": "The shield-wall. For 1 minute, willing creatures within 30 ft of Wallace gain **+2 AC**, and any enemy that willingly moves through the space of the formation provokes an opportunity attack from **every** willing creature in it (not just one). The formation moves with him — the wall walks."}, {"level": 6, "name": "Quartered, Not Ended", "cost_line": "passive", "kind": "feature", "text": "Once per long rest, when Wallace would be reduced to 0 HP, he is reduced to **1 HP instead** and gains temporary HP equal to **5 × his level** — the pieces refuse to scatter. Attacks against him have disadvantage until the end of his next turn (the quartering has begun, and it is *terrible* to watch). **Division:** as a bonus action, Wallace may split into four aspects — one at each quartering-site (Newcastle, Berwick, Stirling, Perth). Each aspect has hit points equal to one quarter of his maximum, is a quarter of his strength in all other respects (the GM adjudicates the split at the table), and fights on its own initiative. A destroyed aspect does not trigger the death-defiance above; it reforms whole at the next dawn. If all four aspects are destroyed on the same day, Wallace is put down for good — four coordinated strikes across Scotland is the only way to kill him."}, {"level": 11, "name": "The Speech", "cost_line": "action, 8 CE, once per day", "kind": "feature", "text": "*\"They may take our lives, but they'll never take our freedom.\"* All willing creatures within **120 ft** that can hear him: regain **4d8 + CHA modifier HP**, gain **immunity to frightened and charmed for 1 hour**, and deal **+1d6 damage** with weapon attacks for 1 minute. All **enemies** within 120 ft that can hear him: WIS save vs technique DC or be **frightened for 1 minute**. The GM is encouraged to deliver the speech in full, in character, before rolling anything. The table will remember."}, {"level": 18, "name": "Freedom Is a Weapon", "cost_line": "action, 10 CE", "kind": "feature", "text": "The Maximum. For 1 minute: - Every time a willing creature within 60 ft takes damage, Wallace may make a claymore attack as a reaction against the source (one reaction per triggering creature per turn — the field is full of answers). - The Martyr's Ledger pays out at **full value**: temp HP equals the *total* damage taken, not half. He does not dodge. He does not retreat. For one minute, every wound his people take is a sword in his hand."}], "maximum": null, "domain": null, "l20": {"level": 20, "name": "FREEDOM (capstone, passive aura)", "cost_line": "capstone, passive aura", "kind": "l20", "text": "A permanent **60-ft aura**. At the start of each willing creature's turn in the aura, Wallace may use his bonus action to **end any number** of the following conditions on them: charmed, frightened, paralyzed, restrained, stunned. Chains — mundane or magical — simply fail to hold where he stands (nonmagical restraints break automatically; magical ones grant an immediate save with advantage). And once per long rest, he may ignore **any single effect** that would kill, banish, possess, or permanently restrain him — no save required, no counter possible. He looks at it, and says the word, and it does not take. *You'll never take it.*"}, "summary_text": null, "source_file": "19-wallace.md"}, {"id": "gilles-de-rais", "module": "20", "figure": "Gilles de Rais", "title": "GILLES DE RAIS", "detail": "full", "technique": "BLUEBEARD'S LEDGER", "tier": "IV", "role": "Striker (Harvest)", "ce_ability": "CHA", "primary_verb": "Confess", "region": "France", "era": "1405–1440 · 15th c.", "culture": "French", "concept": "Joan heard the voices of saints; Gilles heard nothing — and filled the silence himself.", "serves": null, "features": [{"level": 1, "name": "The Ledger", "cost_line": "passive", "kind": "feature", "text": "**Tier IV · Striker (Harvest) · Suggested CE ability: CHA · Primary verb: *Confess.*** *Your technique save DC = 8 + your proficiency bonus + your CHA modifier.*\n\nGilles tracks **Sin charges** — the book never closes. Maximum charges: **10 + (PB × 2)**. He gains **1 charge** when: - any creature **dies** within 60 ft of him; - he **witnesses an act of cruelty** (GM's call — roughly once per scene, not per blow); - a creature **fails a save** against his fear aura. Charges persist until spent. The GM tracks them openly — the players should *see* the number climb. Dread is a mechanic."}, {"level": 1, "name": "Debtor's Blade", "cost_line": "action", "kind": "feature", "text": "Melee attack with the Marshal's blade: +PB + STR (or DEX) to hit, **1d8 + modifier slashing**. Before the attack roll, he may spend up to **3 Sin charges**: **+1d8 necrotic damage per charge** — the dead lend their weight to the blow. The blade leaves ink-black wounds that do not bleed so much as *write*."}, {"level": 3, "name": "Aura of the Accused", "cost_line": "passive, 30 ft", "kind": "feature", "text": "The courtroom follows him. Enemies starting their turn in the aura must succeed on a WIS save vs technique DC or be **frightened for 1 minute** (re-save at the end of each of their turns). **Confession rider:** while frightened by this aura, a creature **cannot deliberately lie** — and if questioned, must answer truthfully, as *zone of truth* (no additional save). The Ledger writes down everything. (The GM should know three secrets per major NPC. Gilles will ask.)"}, {"level": 3, "name": "Spend the Page", "cost_line": "bonus action, variable charges", "kind": "feature", "text": "He reads a page aloud. One creature within 60 ft that can hear him: spend any number of charges, deal **1d10 psychic damage per 2 charges spent** (round down). WIS save vs technique DC for half. The victim hears their own accusations in his voice."}, {"level": 6, "name": "Compound Interest", "cost_line": "passive", "kind": "feature", "text": "The Ledger rewards cruelty with interest: when a creature **dies while frightened by his aura**, Gilles gains **2 Sin charges** instead of 1. Fear is the seed; death is the harvest. (The GM adjudicates \"frightened\" strictly — the aura, the Speech's aftermath, magical fear he caused. Incidental fear doesn't compound.)"}, {"level": 6, "name": "The Trial at Nantes", "cost_line": "action, 5 CE", "kind": "feature", "text": "Single-target prosecution. One creature within 60 ft: WIS save vs technique DC or be **accused for 1 minute** — attacks against it have **advantage**, it has **disadvantage on saves** against Gilles's effects, and it takes **2d8 psychic** damage at the start of each of its turns (the courtroom, in its head, never recesses)."}, {"level": 11, "name": "Hanged, Then Burned", "cost_line": "reaction, 4 CE", "kind": "feature", "text": "When Gilles takes damage, the Ledger pays it forward: the attacker takes **half the damage as necrotic** — WIS save vs technique DC for half of *that*. He has been hanged before. He knows how to share it."}, {"level": 11, "name": "Mass Confession", "cost_line": "action, 8 CE", "kind": "feature", "text": "All creatures within 60 ft: WIS save vs technique DC or be **frightened for 1 minute** and subject to the **confession rider** — and Gilles learns **one secret from each** creature that fails (the GM provides; it should be the secret they'd least want him to know). Re-save vs the fright at the end of each turn; the secrets are already written."}, {"level": 18, "name": "Close the Books", "cost_line": "action, 10 CE", "kind": "feature", "text": "The Maximum. Gilles spends **ALL** accumulated Sin charges at once. One creature within **120 ft**: WIS save vs technique DC or take **1d12 necrotic per charge spent** (save for half) — and, whether it saves or not, it is **written in**: for the next year (or until *remove curse* cast with a 9th-level slot), Gilles always knows its location and direction, and it has **disadvantage on saves** against his fear effects. *The book never forgets. It only ever closes.*"}], "maximum": null, "domain": {"level": null, "name": "\"THE COURTROOM AT NANTES\" (disclosed rule-domain)", "cost_line": "20 CE, full-turn action. 60-ft enclosed radius. Clash 800 · burnout 5 rounds.", "kind": "domain", "text": "The courtroom as it was in 1440 — high windows, the ecclesiastical bench, the smell of iron-gall ink and old smoke. The sure-hit is **procedure**: every hostile within is *the accused* — - **they cannot speak except to answer questions put to them** (the rule of the court; deliberate speech beyond answers deals **3d8 psychic** as Heaven marks the contempt); - **deliberate lies** spoken within deal **3d8 psychic** to the liar as Heaven marks the falsehood; - his **fear aura extends to the entire domain** (no 30-ft limit while it stands). *Three truth-domains now stand in the campaign — Sun's War Room, Hypatia's Alexandria, Gilles's Nantes. The Commentators have noticed the pattern. None of them will say what it means.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Erased Page (capstone)", "cost_line": "", "kind": "l20", "text": "**Once** — ever, not per rest — as an action, Gilles may erase one page: **end any single magical effect, condition, geas, curse, or binding vow affecting him**. No save. No counter. No dispel check. Heaven itself honors the erasure, because the Ledger's arithmetic is older than most of the magic in the world. He has been saving it for six hundred years. He is saving it for **one** page: Sun's leash-vow. The General knows. The General keeps him close anyway — because a knife you can see is a knife you can plan around, and because the day Gilles spends the erasure is the day the General finally learns what the Marshal truly wants. *The GM decides when — if ever — he spends it. It should be the hinge of an arc, not a combat trick.*"}, "summary_text": null, "source_file": "20-gilles.md"}, {"id": "genghis-khan", "module": "21", "figure": "Genghis Khan", "title": "GENGHIS KHAN", "detail": "summary", "technique": "One Sky, One Army — Tumen Doctrine", "tier": "V", "role": "Special Grade", "ce_ability": "CHA", "primary_verb": "Interleave", "region": "Mongolia", "era": "c. 1162–1227 · 12th–13th c.", "culture": "Mongol", "concept": "He conquered half the world without ever needing to be the strongest man on the field — because the field itself was his weapon, and the army was his body.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier V · Special Grade · Suggested CE ability CHA or WIS · Primary verb: Interleave. Faithful summary of U14-02; not a rewrite.*\n\n- **Core loop:** Khan's Knot binds willing creatures (PB capacity) into the Arban; Muster lets members abandon rolled initiative for his; Yam relays tactical messages (60 ft, 120 ft at L6); War Phase lets members pause/yield/resume turns within ordinary one-turn economy — *no extra movement, actions, or attacks, ever*.\n- **L3 — War Phase:** 2+ Mustered members' consecutive turns form a phase; each may pause once, yield to another, resume. Start/end-turn effects stay pinned to the individual.\n- **L6 — Noyan & Detachments:** designate a Noyan; split into two Detachments with independent War Phases.\n- **L11 — Full Tumen Doctrine:** capacity 10, two Noyans, three Detachments, unlimited pause/resume inside normal economy; **The Horde Has No Center** — incapacitated Khan passes command to a Noyan for 1 minute.\n- **L18 — Khagan of the Living Army:** third Noyan; Detachment transfers before the first Arban member acts; succession continues until all Noyans fall or the Arban dissolves.\n- **Maximum — Nerge: The Great Hunt** (Action, 10 CE, Focus): designate a Quarry for 1 minute; Hunt Lines between member pairs (≤30 ft); voluntary crossing lets the line-former reaction-move 10 ft and opportunity-attack; closed 3+ polygon = Caught in the Nerge (can't Hide from the Arban, Disengage covers one crossing/turn, inside→outside teleport needs a CE check or lands back inside). Broken by moving, disabling, or separating members.\n- **Domain — Under the Eternal Blue Sky: One World, One Tumen** (1,000 clash points, 120-ft open radius, full-turn 20 CE activation, 3-round burnout · 3-minute duration): open *support* Domain under a Binding Vow — never imposes an offensive sure-hit on an unwilling creature. At initiative 20, willing Arban members that haven't acted enter the Tumen Phase immediately after — each still exactly one ordinary turn, fully interleaved. Yam ignores ordinary walls; reported information reaches all members instantly. Nerge lines extend to 60 ft. Clash-win: refinement grows 10% per person under the technique's influence (non-compounding).\n- **Genghis Only — White & Black Sülde:** White (Name/memory/law) is a static command post; Black (Will/ambition/terror) is a bonus-action 30-ft repositionable formation anchor. Neither attacks nor takes damage for others.\n- **Campaign Status: RIVAL PACT** — binding vow with Sun Tzu; neither commands the other without consent.", "source_file": "21-genghis-khan.md"}, {"id": "joan-of-arc", "module": "22", "figure": "Joan of Arc", "title": "JOAN OF ARC", "detail": "summary", "technique": "Banner of the Unburned Saint", "tier": "IV", "role": "Suggested CE ability CHA or WIS", "ce_ability": "CHA", "primary_verb": "Swear", "region": "France", "era": "c. 1412–1431 · 15th c.", "culture": "French", "concept": "They burned her at Rouen, and she refused to become what burning makes — so the fire kept the body and lost the argument.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · Suggested CE ability CHA or WIS · Primary verb: Swear. Faithful summary of U14-03; not a rewrite.*\n\n- **Core loop:** Raise the Standard (bonus action, 1 CE, 1 minute) manifests the banner; willing creatures within 30 ft may swear a Vow of Conviction (bonus action): concrete duty + meaningful voluntary restriction. Resolve: once/round, a sworn creature making a d20 roll directly to keep its Vow adds Joan's PB after rolling. Voluntary violation ends the Vow, deals 2×PB psychic, no re-swearing until a short rest. Forced movement/compulsion is not voluntary betrayal.\n- **L3 — Martyr's Share:** Reaction, 1 CE, once/round — when a sworn ally would fail a Vow-tied d20 roll, Joan takes unavoidable 2×PB damage and the ally rerolls. Not usable on herself.\n- **L6 — Voices at the Edge:** When a sworn ally within 60 ft starts its turn Charmed/Frightened (or comparable non-incapacitating compulsion conflicting with its Vow), Joan spends 1 CE to let it immediately repeat the save. One creature per round.\n- **L11 — Banner at Orléans:** Once/round, when a sworn ally succeeds on a meaningful Vow roll, a *different* sworn ally within 60 ft may move 10 ft toward its own duty (no movement cost, no OA from one creature it can see).\n- **L18 — No One Burns Alone:** Reaction — when a sworn ally within 60 ft would drop to 0 HP from damage taken while directly upholding its Vow, Joan takes half the post-mitigation damage; the ally stays at 1 HP. Once/long rest per ally. Cannot redirect damage that would kill Joan outright first.\n- **Maximum — Raise the Banner Through Fire** (Action, 8 CE, Focus, 1 minute): banner to 60 ft, unsuppressible by ordinary fear/morale; each Vowed creature gains one Miracle — convert one failed d20 roll directly necessary to keep the Vow into a success (no crit, cannot override the impossible). Ends early if Joan knowingly orders a sworn creature to violate its Vow.\n- **No Domain — deliberate.** Tier IV carried by breadth + the Miracle.\n- **Campaign Status: OPPOSITION** — final vow rejects any peace requiring surrender of conscience; directly opposes the End of War. Refused Commentator recruitment.", "source_file": "22-joan-of-arc.md"}, {"id": "blackbeard", "module": "23", "figure": "Blackbeard", "title": "BLACKBEARD", "detail": "summary", "technique": "Reputation Made Real — The Devil They Asked For", "tier": "IV", "role": "Suggested CE ability CHA", "ce_ability": "CHA", "primary_verb": "Bluff", "region": "Caribbean / Atlantic", "era": "c. 1680–1718 · 18th c.", "culture": "English pirate", "concept": "Edward Teach died at Ocracoke in 1718 — but the world had spent years telling itself what Blackbeard was, and the telling was stronger than the man.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · Suggested CE ability CHA · Primary verb: Bluff. Faithful summary of U14-04; not a rewrite.*\n\n- **Core loop:** Fly the Colors (bonus action, 1 CE, 120 ft broadcast) — perform one known Rumor for perceiving creatures; witnesses that haven't personally disproved the claim become Believers. Maintain 1 active Rumor (2 at L6, 3 at L11).\n- **L1 Rumors (each with verbatim Exposure):** *Bullets Don't Take Him* — first ranged attack/round by a Believer at disadvantage; if it still hits for ≥2×PB after mitigation, Exposed to all witnesses. *No One Escapes the Flag* — Believers treating him as a threat spend 2 ft per 1 ft moved directly away after the first 20 ft; escaping ≥60 ft farther in one turn Exposes it. *Smoke Is His Sight* — Believers gain no defensive benefit from smoke/darkness he sees through; successfully Hiding in it Exposes the Rumor to observers.\n- **L3 — Call the Bluff:** a Believer may spend an Action studying a Rumor (Insight/Investigation vs Technique DC) → personal immunity + may loudly expose it to perceiving creatures.\n- **L6 — Tell It Again:** Believers repeating a claim outside his presence spread Belief for 24 hours.\n- **L11 — The Monster Outgrows the Man:** Believers who flee/surrender/drop to 0 HP while visibly Rumor-affected convert nearby witnesses without another activation.\n- **L18 — Established Legend:** one chosen Rumor per initiative needs two different successful public Tests in the same round to fully Expose; individual testers still personally immune after their own proof.\n- **Maximum — A General History of the Pyrates** (Action, 10 CE, 1 minute): every known unexposed Rumor circulates among perceiving creatures within 120 ft (Believers for the duration); spectacular Exposure of any Rumor lets all witnesses immediately test to reject *all* Rumors.\n- **No Domain — deliberate.** **Campaign Status: AUTONOMOUS CURSE** — may not contain Teach at all.", "source_file": "23-blackbeard.md"}, {"id": "timur", "module": "24", "figure": "Timur", "title": "TIMUR", "detail": "summary", "technique": "Roads to Samarkand", "tier": "V", "role": "Special Grade", "ce_ability": null, "primary_verb": "Build", "region": "Central Asia", "era": "c. 1336–1405 · 14th–15th c.", "culture": "Turco-Mongol", "concept": "Every conqueror in history took ground — Timur built the roads that ground traveled on, and the roads never forgot him.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier V · Special Grade · Primary verb: Build. Faithful summary of U14 D1; not a rewrite.*\n\n- **Core loop:** Set Samarkand (action, 1 CE) designates a 5-ft Capital (1 hour); Lay Campaign Road (1 CE, once/turn while moving) converts up to 20 ft of personally-traversed path into 5-ft-wide Road (10 min, PB segments, oldest-first replacement). Willing allies starting movement on a connected Road treat the first 15 ft traveled along it as 5 ft. All Roads must stay connected to the Capital via continuous segments.\n- **L3 — Junction Discipline:** where two segments meet, a Junction forms; once/turn, a willing ally reaching a Junction may change direction and ignore opportunity attacks from one visible creature until leaving the 5-ft space.\n- **L6 — Burn the Road Behind:** Reaction, 2 CE, when a hostile enters a Road segment — destroy the segment; Dex save vs 2×PB bludgeoning/fire + speed −10 ft for the turn (half damage, no slow on success). Former segment becomes ordinary difficult terrain.\n- **L11 — All Roads Lead to Samarkand:** Bonus action, 3 CE — relocate along the connected network to the Capital or any Junction within 120 ft. Teleport traces the Road continuously; severed networks block it (zack's ruling).\n- **L18 — Empire of Roads:** maintain 2×PB segments; Road duration extends from 10 minutes to **24 hours**. After physically traveling a route outside combat, stabilize one 1-mile Long Road until next long rest. L11 relocation may carry one willing adjacent creature and use the Long Road.\n- **Maximum — The Campaign Returns Home** (Action, 8 CE): up to PB willing creatures on the network may use reactions to relocate to any reachable Capital/Junction (≤300 ft traced network); no attack granted. Timur may destroy used segments; hostiles on destroyed segments make the Burn save.\n- **No Domain — deliberate.** Road segments are visible cursed infrastructure, destructible by damage/terrain-clearing (zack's ruling).\n- **Persistence: The Sealed Campaign** — Sun Tzu pact; waking conditional on civilization-scale mobilization.", "source_file": "24-timur.md"}, {"id": "rasputin", "module": "25", "figure": "Rasputin", "title": "RASPUTIN", "detail": "summary", "technique": "Not Yet — Intercession of the Unfinished Man", "tier": "IV", "role": "Primary verb: Postpone. Faithful summary of U14 D2; not a rewrite.", "ce_ability": null, "primary_verb": "Postpone", "region": "Russia", "era": "1869–1916 · early 20th c.", "culture": "Russian", "concept": "He owes Heaven his death, and he has been postponing payment for over a century — the interest compounds, and he keeps paying it in other people's tomorrows.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · Primary verb: Postpone. Faithful summary of U14 D2; not a rewrite.*\n\n- **Core loop:** Postpone (Reaction, 2 CE, once/round, when Rasputin or a willing creature within 5 ft would take damage) — after all normal mitigation, defer up to 5×PB of final damage; record exact amount/source as a Debt; creature takes the remainder. Debt comes due at end of the holder's next turn; settlement is unavoidable damage of the recorded type — cannot be reduced by resistance, further effects, or temp HP; no new save; triggers no on-damage reactions (zack's ruling). One creature holds one damage Debt at a time. Outstanding Debts come due immediately when combat ends.\n- **L3 — Intercession** (Reaction, 1 CE): when a willing creature within 30 ft has a Debt due before end of its current turn, Rasputin takes ownership; due time becomes end of his next turn. Transfers once unless a feature says otherwise.\n- **L6 — Deferred Affliction** (Action, 2 CE, touch willing): suspend a listed non-incapacitating condition (duration ≤1 min) — eligible: **blinded, charmed, deafened, frightened, poisoned** — place it on Rasputin as Affliction Debt; at end of his next turn it affects him for remaining duration (min 1 round). Stunned/Paralyzed/Unconscious/death/Domain sure-hits cannot be moved.\n- **L11 — Refusal to Die:** when a Debt comes due and would reduce Rasputin to 0 HP, split after seeing the result — half now, half as a new Debt due end of his next turn. Each use reduces max HP by 2×PB until a long rest; cannot be used if max HP would hit 0. This is the **sole exception** to the no-second-postponement rule — it divides what is due rather than postponing it, and the division is priced in his own maximum HP.\n- **L18 — The Impossible Man:** first Postpone each round costs 0 CE; Intercession once/round needs no Reaction; may hold up to PB simultaneous Debts, each with own source/due time.\n- **Maximum — Tomorrow, Then** (Action, 8 CE): until start of his next turn, the first damaging effect or eligible affliction on each willing creature within 30 ft is fully deferred to Rasputin (no reaction); at start of his next turn he may redistribute each resulting Debt once among willing creatures within 30 ft; leftovers stay his; redistributed Debts come due end of each new holder's next turn.\n- **No Domain — deliberate.** **Persistence: The Final Debt** — death as unpaid metaphysical Debt; permanent defeat requires a ritual forcing settlement with no transfer.", "source_file": "25-rasputin.md"}, {"id": "alexander", "module": "26", "figure": "Alexander", "title": "ALEXANDER", "detail": "summary", "technique": "There Is Always Another Horizon", "tier": "V", "role": "exploration / mobility", "ce_ability": null, "primary_verb": "cross", "region": "Macedon / Persia", "era": "356–323 BCE · 4th c. BCE", "culture": "Macedonian", "concept": "Every frontier he crossed became a road — and the roads are still there.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "**\"There Is Always Another Horizon\"** — Tier V · exploration / mobility · verb: *cross.* (Suggested CE ability per dossier pattern: STR or DEX; the dossier's breach check is a CE ability check.)\n\n**Core loop:** Name a meaningful visible boundary within 60 ft as a Frontier (bonus action, 1 CE) → Alexander crosses first → the crossing becomes a Passage (1 min, maintain PB) → willing allies crossing gain bonus movement and ignore nonmagical difficult terrain.\n\n**Signature features:**\n- **L1 — Name the Frontier / Make Passage:** the foundation. Arbitrary lines in open ground are invalid — the boundary must be meaningful (doorway, wall edge, riverbank, sealed threshold, hostile frontline).\n- **L3 — First Across:** converting a Frontier lets him draw a weapon, interact, or make one weapon attack as part of the movement — the crossing *is* the attack's delivery.\n- **L6 — No Barrier Is the World:** cursed barriers, curtains, Domain walls, sealed doorways can be named as Frontiers; CE ability check vs the creator's Technique/Barrier DC opens a 5-ft Passage for willing allies. Per zack's ruling: passage through a Domain wall grants immunity to the Domain's sure-hit **but** mutual non-interference — he cannot hurt others inside while immune. The check is a breach attempt resolved before any clash, not a clash substitute.\n- **L11 — Uncharted Route:** run across liquids and vertical surfaces while moving toward a Frontier or along a Passage; gaps ≤ remaining movement are traversable.\n- **L18 — Beyond the Map:** Passages last 24 hours; one Long Passage through a supernatural threshold can be stabilized until the next long rest.\n- **Maximum — To the End of the Known World** (action, 10 CE): 300-ft Expedition Route, 10 ft wide — climbs walls, crosses water and gaps, punches one plausible mundane obstacle; willing allies use reactions to move along it. Supernatural barriers on the route each require the L6 check.\n- **Domain: none.** No clash points. (Per dossier: it *breaches* Domains without being one.)\n\n**D&D combat role:** mobility support / exploration-striker. The party's way through.", "source_file": "26-alexander.md"}, {"id": "taira-no-masakado", "module": "27", "figure": "Taira no Masakado", "title": "TAIRA NO MASAKADO", "detail": "summary", "technique": "Counter-Capital — The Rebel Seat", "tier": "V", "role": "territorial denial", "ce_ability": null, "primary_verb": "contest", "region": "Japan", "era": "c. 900s–940 · 10th c.", "culture": "Japanese", "concept": "The capital moved. He did not.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "**\"Counter-Capital — The Rebel Seat\"** — Tier V · territorial denial · verb: *contest.* (Suggested CE ability per dossier pattern: WIS or CHA.)\n\n**Core loop:** Plant a Rebel Seat (action, 2 CE, 10-ft radius, 1 min, maintain 1) → hostile non-damage territorial rules inside are contested → willing creatures use reactions to check vs the source DC and ignore the rider for the turn. Damage applies normally — the Seat contests *authority*, not violence.\n\n**Signature features:**\n- **L1 — Raise a Rebel Seat:** the foundation. First time each round a willing creature inside faces a hostile non-damage territorial rule (forced movement, movement tax, silence, fear/charm compulsion, LOS distortion, zone rider), it may use its reaction for a Str/Wis/CE check vs the source DC; success ignores that rider until end of turn.\n- **L3 — Eastern Road:** maintain 2 Seats; bonus action, 2 CE — a willing creature in one Seat spends 10 ft of movement to teleport to the other Seat within 60 ft.\n- **L6 — Local Sovereignty:** when a hostile Domain expands over a Seat, it becomes a Counter-Capital (HP = 5× level, AC = Technique DC). The first initiative-20 sure-hit event affecting a creature inside is intercepted — resolved against the Seat's HP, once per event. Per zack's ruling: ordinary attacks/riders inside are unaffected; Seats are visible, targetable objects.\n- **L11 — The Head Still Flies East:** at 0 HP with ≥1 Seat, Masakado remains conscious to speak through a Seat, perceive its radius, and use Eastern Road for willing allies. No movement, attacks, or other techniques.\n- **L18 — Three Seats of the East:** maintain 3 Seats; once/round relocate a Seat 15 ft as a reaction when a rider is resisted inside it. Seats persist 1 hour outside hostile Domains.\n- **Maximum — New Imperial Capital** (action, 8 CE, Focus, 1 min): one Seat becomes 30-ft radius; once/round, a hostile technique imposing a non-damage rule inside must win a CE ability contest vs Masakado or the rule doesn't apply that round. Eastern Road in/out costs no CE during the Maximum.\n- **Domain: none.** No clash points. (Per dossier: it *contests* Domains without being one — the only anti-Domain territory specialist in the set.)\n\n**D&D combat role:** zone defender / anti-Domain anchor. The party's bunker.", "source_file": "27-masakado.md"}, {"id": "emperor-sutoku", "module": "28", "figure": "Emperor Sutoku", "title": "EMPEROR SUTOKU", "detail": "summary", "technique": "Crown & Exile — Heaven Below, Earth Above", "tier": "V", "role": "redistribution / inversion", "ce_ability": null, "primary_verb": "transpose", "region": "Japan", "era": "1119–1164 · 12th c.", "culture": "Japanese", "concept": "He sat the highest seat in Japan, and they made him the lowest man in it — so he rewrote the seating chart of the world.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "**\"Crown & Exile — Heaven Below, Earth Above\"** — Tier V · redistribution / inversion · verb: *transpose.* Deliberate onryō. (Suggested CE ability per dossier pattern: INT or CHA.)\n\n**Core loop:** Link two creatures within 60 ft as Crown and Exile (action, 2 CE, Focus 1 min). Unwilling targets make a **WIS save vs Sutoku's technique DC** when named — a creature that succeeds cannot be made Crown or Exile for 1 minute; willing targets (including Sutoku himself) need no save. → once/round, transpose external non-damage benefits from Crown to Exile (reaction) → once/round, transpose external non-damage penalties from Exile to Crown (reaction). Crown loses what Exile gains.\n\n**Signature features:**\n- **L1 — Name Crown & Exile / Burden Upward:** the foundation. Benefits transpose down; penalties transpose up. Damage, Stunned/Paralyzed/Unconscious, death, Domain sure-hits excluded.\n- **L3 — Exchange Offices** (bonus action, 1 CE): swap which linked creature is Crown/Exile; once/round, Exile may use Crown's proficiency on a d20 roll when Crown's is higher.\n- **L6 — The Low Seat Speaks:** Exile may refuse a beneficial effect that could target Crown; if Crown accepts, it redirects upward and Exchange Offices triggers free.\n- **L11 — Two Courts:** maintain two independent pairs; one reaction per pair per round.\n- **L18 — The Throne Has No Owner:** first valid transposition per pair per round is free; Exchange Offices once/round without bonus action.\n- **Maximum — Sovereign Becomes Commoner** (action, 10 CE): pick one Axis (AC, walking speed, current CE, current HP percentage, initiative count) among creatures within 60 ft; the single highest and single lowest exchange those values until end of Sutoku's next turn. Caps at recipients' maxima. No max HP, ability scores, class features, or techniques exchanged.\n- **Domain Expansion — Court of the Demon Sovereign: The World Turned Upside Down** (disclosed rule-Domain): at initiative 20, Sutoku announces one Axis, ranks every creature publicly, and swaps highest/lowest until the next initiative 20. The sure-hit *is* the ranking and transposition; ordinary attacks stay ordinary. Counterplay is printed: creatures may deliberately lower their Axis position before the count. **1,000 clash points** (Tier V floor), 60-ft enclosed default, full-turn 20 CE activation, burnout 3 rounds · duration 3 minutes.\n\n**D&D combat role:** debuffer / hierarchy-inverter. The fight's tax collector.", "source_file": "28-sutoku.md"}, {"id": "john-dee", "module": "29", "figure": "John Dee", "title": "JOHN DEE", "detail": "summary", "technique": "Angelic Correspondence", "tier": "V", "role": "divination / support", "ce_ability": null, "primary_verb": "Ask", "region": "England", "era": "1527–1609 · 16th c.", "culture": "English", "concept": "He asked the angels questions for thirty years — and never once asked what they were.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "**\"Angelic Correspondence\"** — Tier V · divination / support · verb: *Ask.* Suggested CE ability: **INT.** Campaign status: FORMER COMMENTATOR. **No Domain.**\n\n**Core loop:** During rest, designate a willing Skryer and prepare a reflective focus → Consult the Shew-Stone (action, 1 CE): ask one objective yes/no question about the present state of something perceived by Dee or the Skryer → the GM answers **Yes, No, or Obscured** truthfully **to the Skryer** (never the Operator) → until end of Dee's next turn, the first d20 roll by Dee or the Skryer that directly and plausibly exploits a clear answer gains **+PB** (GM-gated; the table must explain the connection).\n\n**Signature features:**\n- **L1 — Operator & Skryer / Consult the Shew-Stone / Correspondence:** the foundation. Questions about futures, secret intentions, morality, or unknowable metaphysics return Obscured. Dee may serve as his own emergency Skryer only if no willing second creature is available (+1 CE).\n- **L3 — Cross-Examination** (bonus action, 2 CE): follow-up narrowing the same subject; if both answers are clear and genuinely used together, the Correspondence roll also ignores one source of disadvantage.\n- **L6 — Distant Conference:** matched mirrors let Dee and Skryer operate up to 1 mile apart. Only the Q&A channel crosses — no remote attacks or sight-sharing.\n- **L11 — Four Castles** (action, 4 CE, Focus 1 min): four Seal points forming a ritual area; after a clear Query about a subject inside, Dee and Skryer treat it as perceptible for further Queries even through smoke/invisibility/mundane walls. Total cover still blocks attacks.\n- **L18 — Angelic Grammar:** Consult becomes a bonus action; maintain two Skryers; once per round, an Obscured answer must instead provide one truthful **symbolic clue** (short, non-numeric, not a disguised future prediction) — delivered **to a Skryer**, preserving the witness law.\n- **Maximum — Monas Hieroglyphica** (action, 8 CE): requires four clear Query answers about the same target in the current encounter. Dee writes one Axiom from established facts only. For 1 minute, once per round a willing creature directly testing the Axiom may reroll one failed d20. If a premise is definitively disproven, the Maximum ends and Dee takes 4×PB psychic damage.\n\n**D&D combat role:** divination support. The encounter's oracle.", "source_file": "29-john-dee.md"}, {"id": "vlad-iii", "module": "30", "figure": "Vlad III", "title": "VLAD III", "detail": "summary", "technique": "The Dread I Cast Off", "tier": "IV", "role": "fear externalization / identity defense", "ce_ability": null, "primary_verb": "Externalize", "region": "Wallachia", "era": "1431–1476/77 · 15th c.", "culture": "Wallachian", "concept": "He spent his life manufacturing terror in others so he'd never have to feel his own — and the terror he cast off had other plans.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "**\"The Dread I Cast Off\"** — Tier IV · fear externalization / identity defense · verb: *Externalize.* Suggested CE ability: **CHA.** Campaign status: CURSE-BOUND. **No Domain.** NPC-locked per zack's ruling (viewable in the library, not selectable in the builder).\n\n**Core loop:** Cast Off Dread (bonus action, 1 CE, Focus 1 min) → place a 10-ft-radius Dread Shadow within 30 ft → hostiles entering or starting turns inside make a Wis save → failures become **Dreaded** (can't willingly move closer to the Shadow's center; disadvantage on attacks vs Vlad while he's inside) until end of their next turn. Dreaded is bespoke — Frightened immunity grants advantage on the save, not immunity.\n\n**Signature features:**\n- **L1 — Cast Off Dread:** the foundation. The Shadow is Vlad's externalized terror, placed and used as terrain.\n- **L3 — Move the Terror** (bonus action, no additional CE): move the Shadow 20 ft; a hostile whose space is covered may use its reaction to step 5 ft out before the save — yield ground or face the fear.\n- **L6 — Impaler's Lesson:** once/turn, hitting a Dreaded creature with a piercing weapon or grapple adjacent to a solid surface — spend 2 CE, Str save or **pinned** (speed 0 until end of its next turn or until it uses an action to beat Athletics vs Technique DC). Restraint, not dismemberment.\n- **L11 — Separate the Name** (reaction, 2 CE): when targeted by a non-Domain mark, curse, scry, tracking, or identity-dependent technique — redirect it to the Dread Shadow if legal. Failure (can't target a shadow construct): CE not spent.\n- **L18 — The Ruler Is Not the Legend:** no Focus required; 15-ft radius; once/round move it 10 ft as a reaction (no additional CE). Redirected effects stay on the Shadow even if Vlad leaves.\n- **Maximum Release — Dracula Unbound** (action, 10 CE, 1 min; **Vlad only**): the Shadow becomes the autonomous curse — 40-ft fly, mist passage, +2×PB necrotic after Vlad's piercing damage (healing the same). **Cost of control:** each turn, if no hostile is Dreaded and Dracula took damage since Vlad's last turn — Cha save vs own Technique DC or Dracula chooses its movement and target, prioritizing blood and fear over tactics.\n- **Persistence — The Legend Needs Its Prisoner** (GM-discretion plot hook per zack's ruling): Vlad can die; Dracula attempts to reconstruct or reclaim him, because the fiction needs its anchor. **Personal Legacy:** the Dracula relationship does not transfer to inheritors.\n\n**D&D combat role:** fear-zone controller / identity defense. The battlefield's bad geometry.", "source_file": "30-vlad.md"}, {"id": "the-count-of-saint-germain", "module": "31", "figure": "The Count of Saint-Germain", "title": "THE COUNT OF SAINT-GERMAIN", "detail": "summary", "technique": "Continuity of Persona", "tier": "IV", "role": "infiltrator / escape artist", "ce_ability": "CHA", "primary_verb": "Assume", "region": "Europe", "era": "d. 1784 · 18th c.", "culture": "European", "concept": "He has been dying for three hundred years, and he has not finished yet — every identity he wears is real, and none of them is him.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · infiltrator / escape artist · verb: Assume · suggested CE ability CHA or INT · **No Domain**.*\n\n- **L1 — Establish Persona / Assume Persona:** maintain 2 Personae (alias + records + one Credential proficiency, expertise if already proficient). Bonus Action, 1 CE to switch; identification reads the active Persona as truthful.\n- **L3 — Separate Accounts:** marks, bounties, curses, and tracking attach to the *active Persona*; switching suspends (not ends) one effect per Persona.\n- **L6 — Prepared Life:** each Persona holds one downtime-built Asset — safehouse, cached gear (cap $100×level), vehicle, forged access, or a mundane contact.\n- **L11 — Death of an Alias:** once per long rest, at 0 HP without dying outright — destroy the active Persona, stay at 1 HP, instantly assume another, end one identity effect. Burned Persona gone 7 days.\n- **L18 — No Original:** maintain PB Personae; switch once per turn free. Divination for the \"real\" identity returns the active Persona — *unless it targets soul continuity.*\n- **Maximum — I Was Never Here (Action, 8 CE):** burn all Personae but one, end all their marks, and teleport to a prepared token within 1 mile. The survivor is the only detectable identity; the rest are metaphysically dead.\n\n## IX. Reveal & Escalation\n\n1. **The ally who wasn't.** A helpful NPC — a contact, a fixer, a fence — vanishes mid-arc. Their records don't quite hold up. They were never born.\n2. **The burned alias.** The party kills a network operative. The body's papers describe a life that ends three days ago. The dental records belong to a man who died in 1962.\n3. **The pattern.** Three \"different\" operatives across three arcs share a tell — a turn of phrase, a card trick, a way of pouring wine. Someone is wearing the network.\n4. **The contract.** The party finds the vow — not its terms (Heaven keeps those), but its *shape*: a blank space in the General's perfect records, exactly man-sized.\n5. **The choice.** Cornered, Saint-Germain offers the party a deal — and his deals, unlike the General's, are *small*. He doesn't want their loyalty. He wants them to owe him one favor, payable in illegibility.\n\n## X. D&D Combat Function\n\n**Infiltrator / escape artist.** Saint-Germain is not a combatant — he is the encounter that happens *before* combat, and the escape that happens *after* it. At the table, run him as a skill-monster with an unbreakable exit: he will not stand and fight, because standing and fighting would require being someone, and he declines. The party beats him by attacking the continuity, not the man — soul-targeting divination, the 7-day burn window, the prepared token they find *before* he needs it.", "source_file": "31-saint-germain.md"}, {"id": "khutulun", "module": "32", "figure": "Khutulun", "title": "KHUTULUN", "detail": "summary", "technique": "Ten Thousand Horses", "tier": "IV", "role": "duelist / voluntary-stake engine", "ce_ability": "STR", "primary_verb": "Wager", "region": "Mongolia", "era": "d. 1306 · 13th–14th c.", "culture": "Mongol", "concept": "She never lost a wrestling match — and the world is just a bigger ring.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · duelist / voluntary-stake engine · verb: Wager · suggested CE ability STR or CHA · **No Domain**.*\n\n- **L1 — Issue the Wager:** Bonus Action, 1 CE — challenge one creature within 30 ft that understands the offer. **It may refuse with no magical penalty.** If accepted, both name one Minor Stake (10 ft speed, +1 AC, 5 max HP, a proficiency, +1 with a named weapon, advantage on a named skill) and a contest form — normally wrestling, first to 2 opposed-Athletics victories.\n- **L3 — No Empty Wager:** the technique rejects worthless, suppressed, or battlefield-meaningless stakes; the challenged party gets one renegotiation. Coerced \"yes\" is not acceptance (per zack's ruling).\n- **L6 — Major Stakes:** damage resistance, a 30-ft movement mode, one extra Reaction/round, one limited-use non-Domain feature, Powerful Build. **Never valid:** technique ownership, Domains, Maximums, souls, lives, ability scores.\n- **L11 — Champion's Purse:** keep up to PB won Stakes until the next long rest; risk them in later wagers. Lose, and the winner takes your stake *plus* one of your retained Stakes.\n  - **Using won Stakes:** passive Stakes (speed, AC, resistance, movement modes, Powerful Build, the extra Reaction) apply automatically while held. A won limited-use feature may be used **once** before the next long rest, using Khutulun's action and her own CE at her technique DC. Stakes won beyond the PB cap cannot be retained — they must be immediately re-wagered or forfeited.\n- **L18 — Undefeated Until Proven Otherwise:** once per challenge, after losing a contest roll, offer to double the wager — opponent's acceptance erases the loss; refusal lets it stand.\n- **Maximum — The Ten-Thousand-Horse Wager:** one Grand Challenge to a *willing* opponent, GM-approved Grand Stakes, every retained Stake on the table, first to 3 victories. Winner holds everything 24 hours. *\"Refusal is always legal.\"*\n\n## IX. Reveal & Escalation\n\n1. **The horses.** A village, a warlord, a minor sorcerer — someone the party knows — is suddenly *slower*, clumsier, diminished. They wagered something with a traveler. They won't say what.\n2. **The traveler.** A Mongol woman at a waystation, polite, curious, asking about the strongest fighter the party has ever seen. She is *auditioning*.\n3. **The bout.** She challenges a player — fairly, openly, stakes named. Win or lose, it's the most honorable fight of the campaign. She remembers the ones who accept.\n4. **The Purse.** The party realizes she's been collecting — Stakes from across the region, all held, all risked. She's building toward something.\n5. **The Grand Wager.** She calls due her bout with the General. The campaign stops. The ring is drawn. Heaven watches.\n\n## X. D&D Combat Function\n\n**Duelist / voluntary-stake engine.** Khutulun is a single-target striker whose real weapon is the *offer*. At the table, she plays like a fighting-game grappler crossed with a poker player: get close, offer the wager, win the opposed Athletics, take the trait. She is devastating against proud enemies and useless against those who simply refuse — which is the point. The party beats her by declining (and living with the shame), or by accepting and being better. There is no third option, and she likes it that way.", "source_file": "32-khutulun.md"}, {"id": "hannibal-barca", "module": "33", "figure": "Hannibal Barca", "title": "HANNIBAL BARCA", "detail": "summary", "technique": "Hollow Center — Cannae Doctrine", "tier": "IV", "role": "battlefield geometry / elastic defense / encirclement", "ce_ability": "INT", "primary_verb": "Envelop", "region": "Carthage / Rome", "era": "247–183 BCE · 3rd c. BCE", "culture": "Carthaginian", "concept": "Rome called him the enemy at the gates for a generation — and he is still at the gates.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · battlefield geometry / elastic defense / encirclement · verb: Envelop · suggested CE ability INT or WIS · **No Domain**.*\n\n- **L1 — Elastic Center:** Bonus Action, 1 CE — two ground points ≤30 ft apart define a Center Line (1 min). Once/round, when a hostile crosses toward Hannibal's side, a willing ally within 5 ft may Reaction-step 5 ft back (no OA); the line shifts with them.\n- **L3 — Left & Right Wings:** 10-ft Wing zones at each endpoint. A hostile across the line while both Wings hold conscious allies is **Committed**. Once/round, when a Committed creature ends movement, one ally per Wing may shift 5 ft toward it free. *(Passive rider — no separate action or CE once the Center Line is established.)*\n- **L6 — Close the Pocket:** a Committed creature within the Center ally's reach and at least one creature from each Wing becomes **Enveloped**. Disengage protects from only one direction per turn. *(Passive rider — no separate action or CE once the Center Line is established.)*\n- **L11 — Cavalry Reserve:** one designated willing ally outside the formation may once/round Reaction-move half speed to repair the geometry when it's breached. Designating the reserve ally costs a **bonus action, 0 CE**, once per Center Line establishment. No damage buff — discipline, not fury.\n- **L18 — Cross the Impossible Ground:** line extends to 60 ft, Wings to 15 ft; formation ignores nonmagical difficult terrain; Hannibal may bend an endpoint 10 ft once/round. *(Passive rider — no separate action or CE once the Center Line is established.)*\n- **Maximum — Cannae: The Double Envelopment (Action, 8 CE, Focus, 1 min):** line to 60 ft, both Wings established; Enveloped creatures treat retreat as difficult terrain and can't Disengage against more than one role. Breaks if a role is incapacitated or displaced — *\"a cage made of people and positioning, not an invisible wall.\"*\n\n## IX. Reveal & Escalation\n\n1. **The geometry.** A network operation the party investigates went wrong for the *other* side — a strike team walked into a valley and didn't walk out. Survivors describe being *folded*.\n2. **The annotation.** A captured Commentator text contains marginalia on Cannae in a modern hand — professional, admiring, *tactical*. Someone is studying.\n3. **The Alps.** A \"retreat\" by network forces leads the party's allies straight through \"impassable\" terrain — into a prepared pocket. The retreat was the maneuver.\n4. **The oath.** The party uncovers the Hamilcar oath — and realizes the General's most loyal commander swore his deepest vow *against* empires.\n5. **The choice.** Hannibal offers the party's commander a soldier's parley — and asks, quietly, what they think the End of War *is*. He is asking for himself.\n\n## X. D&D Combat Function\n\n**Battlefield-geometry controller / force multiplier.** Hannibal is not a duelist — he is a *formation*. At the table he plays like a puzzle boss crossed with a warlord: he defines lines, assigns willing allies to roles, and punishes every step the party takes inside his geometry. He deals no direct damage with the technique itself — the damage comes from the allies he positions. The party beats him by breaking the geometry (incapacitate a Wing, scatter the roles, refuse to cross the line), not by out-damaging him. And the cruelest counterplay is the oldest: *don't walk into the hollow center.*", "source_file": "33-hannibal.md"}, {"id": "zheng-yi-sao", "module": "34", "figure": "Zheng Yi Sao", "title": "ZHENG YI SAO", "detail": "summary", "technique": "Red Flag Articles", "tier": "IV", "role": "support economy / voluntary law / surrender", "ce_ability": "CHA", "primary_verb": "Contract", "region": "South China Sea", "era": "1775–1844 · 18th–19th c.", "culture": "Chinese", "concept": "She commanded eighty thousand pirates and retired with a pardon — and nobody retires from this.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · support economy / voluntary law / surrender · verb: Contract · suggested CE ability CHA or INT · **No Domain**.*\n\n- **L1 — Sign the Articles:** during a rest, up to PB *willing* creatures become Crew (they can always leave at the next rest; no punishment for refusing renewal).\n- **L1 — General Fund:** each Crew member may deposit up to PB CE (cap 2×Zheng's level + PB); deposited CE leaves the personal pool. Once per turn, a Crew member within 60 ft may draw 1 CE to pay part of one legal CE cost. *No CE is created.*\n- **L3 — Article of Mutual Defense:** once/round, when a Crew member within 60 ft fails a save or takes damage, another Crew member may Reaction-spend 2 Fund CE to add PB to the save or reduce damage by 2×PB. The *assister* decides.\n- **L6 — Articles May Be Amended:** after a short rest, the Crew may unanimously add one table-written Article (GM-approved). Any signer rejecting = no amendment.\n- **L11 — Amnesty:** offer explicit surrender terms to one hostile that understands them. If accepted and witnessed, both sides bound 24 hours; a knowing violator takes 5×PB psychic, loses PB CE. Terms can't require suicide, slavery, soul-surrender, or unrelated future obedience.\n- **L18 — Pension & Exit:** at objective's end, any Crew member may leave permanently and withdraw up to their contribution. Amnesty-honorers can't be hunted by the Crew for the term.\n- **Maximum — Red Flag Confederation (Action, 10 CE, 1 min):** Fund range 120 ft; a Crew member may draw *any amount* for one activation; other willing Crew may Reaction-contribute personal CE (up to PB each) toward one activation. Per zack's ruling: may pay Domain Expansion costs.\n\n## IX. Reveal & Escalation\n\n1. **The quartermaster.** Network operations the party disrupts keep getting *funded* — techniques fire that shouldn't be affordable. Someone is paying.\n2. **The Articles.** A captured operative carries a copy of Articles — fair, precise, witnessed. The party's lawyer-minded member reads them and goes pale: *these are good terms.*\n3. **The amnesty.** A fight the party is winning *stops* — a woman's voice offers terms, and the terms are fair, and Heaven is listening, and refusing would cost more than accepting.\n4. **The gambling house.** In Guangzhou, or its modern equivalent, an old woman runs a game. She has been running it for a very long time. She remembers every player.\n5. **The negotiation.** She asks for a meeting — not a fight, a *meeting*. She wants to discuss the End of War's terms. She has notes.\n\n## X. D&D Combat Function\n\n**Support / quartermaster / economy engine.** Zheng Yi Sao doesn't win fights — she *funds* them. At the table she's the reason the network's impossible plays are possible: the shared CE pool, the mutual-defense reactions, the group-funded Maximum. She is also the network's most approachable face: fair terms, clean exits, no conscription. The party beats her the way you beat any quartermaster — cut the supply lines. Turn the Crew. Break the cooperation, and the Fund locks, and the Pirate Queen is just a woman with a gambling house and the best exit clause in history.", "source_file": "34-zheng-yi-sao.md"}, {"id": "yi-sun-sin", "module": "35", "figure": "Yi Sun-sin", "title": "YI SUN-SIN", "detail": "summary", "technique": "Roaring Current — Myeongnyang Doctrine", "tier": "IV", "role": "movement-channel controller / chokepoint / last-line defender", "ce_ability": "WIS", "primary_verb": "Channel", "region": "Korea", "era": "1545–1598 · 16th c.", "culture": "Korean", "concept": "With thirteen ships he faced a hundred and thirty-three — he is still outnumbered, and it still doesn't matter.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · movement-channel controller / chokepoint / last-line defender · verb: Channel · suggested CE ability WIS or INT · **No Domain**.*\n\n- **L1 — Draw the Strait:** Action, 2 CE, Focus up to 1 min — two anchors within 60 ft (≤30 ft apart); the line between is a Current Line with a chosen direction. Crossing carries creatures 10 ft parallel — willing may accept; unwilling make a Str save.\n- **L1 — Reversing Tide:** at initiative 20 the line reverses automatically (1 CE to prevent one reversal). Direction always visible — a timing puzzle, not a trap.\n- **L3 — Anchor Ships:** up to PB willing creatures ignore the forced movement and may ride 10 ft along the current for 5 ft of movement (once/turn).\n- **L6 — Crane Wing:** a second Current Line sharing one anchor (bent channel). An unwilling creature carried across the second line makes a Dex save: fail = carried again + prone; success = stops, stays standing.\n- **L11 — Twelve Against Hundreds:** while conscious hostiles within 60 ft outnumber allies ≥2:1, hostile saves vs. lines are at disadvantage and forced movement becomes 15 ft. Ends the instant the condition fails.\n- **L18 — Do Not Announce My Death:** at 0 HP while a Current effect is active, his Reaction makes the technique self-sustaining 1 minute — no Focus, reversals continue, anchors persist. No actions; lines remain destructible.\n- **Maximum — Myeongnyang: The Roaring Strait (Action, 10 CE, Focus, 1 min):** anchors to 60 ft apart, 30-ft-wide current zone; reverses each initiative 20; hostiles entering or starting turn inside make a Str save — fail = moved 20 ft with the current. Anchored allies ride free and never collide.\n\n## IX. Reveal & Escalation\n\n1. **The strait.** A network withdrawal the party pursues turns into a nightmare of *positioning* — every step slides sideways, the ground has a schedule, and someone studied this water.\n2. **The thirteen.** Intelligence mentions a network cell that should have been overrun — thirteen operatives against hundreds — holding for weeks. The numbers don't make sense. The numbers never make sense around him.\n3. **The turtle ships.** A modern equivalent surfaces: armored, deliberate, unhurried assets that don't retreat and don't break. Someone is building geobukseon for the current war.\n4. **The court records.** The party finds Joseon court documents — the demotion, the torture, the reinstatement. They understand, suddenly, exactly what kind of man serves a master who betrayed him: *carefully.*\n5. **The test.** Yi requests a parley — not with the party's leaders, but with its *soldiers*. He wants to know how they're treated. He is taking notes.\n\n## X. D&D Combat Function\n\n**Movement-channel controller / chokepoint defender / anti-horde.** Yi Sun-sin is the battlefield's *water*: he doesn't deal damage directly, he decides where everyone stands. At the table he plays like a living difficult-terrain puzzle with a reversal clock — the party must track the current's direction, time their crossings, and respect the anchors. He is at his weakest in open-field duels and at his strongest when the party brings numbers — which inverts every instinct players have about outnumbering a boss. Beat him by fighting *small* (deny the 2:1), *anchored* (his own allies' trick, turned around), or *patient* (the current reverses; the patient inherit the strait).", "source_file": "35-yi-sun-sin.md"}, {"id": "shaka-zulu", "module": "36", "figure": "Shaka Zulu", "title": "SHAKA ZULU", "detail": "summary", "technique": "Horns of the Bull — Impondo Zenkhomo", "tier": "IV", "role": "role-formation controller / single-target encirclement", "ce_ability": "CHA", "primary_verb": "Form", "region": "Southern Africa", "era": "1787–1828 · 19th c.", "culture": "Zulu", "concept": "He forged a nation from a cattle-herding chiefdom — and his brothers killed him for it.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Tier IV · role-formation controller / single-target encirclement · verb: Form · suggested CE ability CHA or STR · **No Domain**.*\n\n- **L1 — Assign the Bull:** Bonus Action, 1 CE, 1 min — choose one hostile **Quarry** you can see within 60 ft; assign *willing* creatures to roles: Chest, Left Horn, Right Horn, Loins Reserve. No creature holds two roles.\n- **L1 — Chest Holds:** if the Chest begins and ends its turn within reach/10 ft of the Quarry, the formation is **Fixed**. When a Fixed Quarry moves away, the Chest may Reaction-follow 5 ft (debited from its next turn's movement).\n- **L3 — Horns Close:** after the Chest hits the Quarry, each Horn may once/round shift 5 ft around it (free, toward opposite sides). Both Horns within reach on opposite sides = **Surrounded** until the geometry breaks.\n- **L6 — Loins Commit:** the Loins begin outside the Quarry's reach; when a role-holder is incapacitated, displaced 15+ ft, or leaves, the Loins may Reaction-move half speed and inherit the role. Breach answer = reserve discipline.\n- **L11 — Encirclement:** a Surrounded Quarry treats its first 10 ft of movement each turn as difficult terrain. Disengage protects against only one role per turn.\n- **L18 — Living Formation:** once/round after any member moves, Shaka may swap two willing members' roles (no action; grants no extra actions or movement).\n- **Maximum — The Bull Closes (Action, 8 CE, Focus, 1 min):** while Surrounded, the formation self-corrects — once/round, when the Quarry exits a member's reach, another member may Reaction-move 10 ft into the vacated arc. Printed outs: scatter the roles, vertical/teleport movement, incapacitate members. *\"There is no invisible cage.\"*\n- **L20 — The Bull Remembers:** once per long rest, declared as part of Assign the Bull — the formation that refused to end. The Loins may hold a second role simultaneously (the reserve deepens), and if Surrounded is broken, the formation re-forms at the start of your next turn without a new assignment — the bull remembers its shape — provided at least two willing members remain.\n\n## IX. Reveal & Escalation\n\n1. **The formation.** A network kill team the party tracks moves *wrong* — not like soldiers, like an animal. Chest, horns, loins. Someone is teaching the old geometry.\n2. **The iklwa.** A close-quarters massacre with a signature: short-spear wounds, encirclement, no survivors on the flanks. The bull has been here.\n3. **The drill.** Captured footage or a survivor's account of a *drill* — a thousand network operatives moving as one animal, and a tall man's voice calling the roles. He is building an army the old way.\n4. **The brothers.** The party uncovers the assassination — Dingane, Mhlangana, the bodyguard's knife. They understand, suddenly, why the most disciplined formation in the network is commanded by the man most afraid of his own blood.\n5. **The Quarry.** Shaka names one — and the name is someone the party loves. The horns are closing. The geometry is visible. The exits are printed. *Run.*\n\n## X. D&D Combat Function\n\n**Single-target encirclement controller.** Shaka is Hannibal's cousin and opposite: where Hannibal folds *armies*, Shaka closes around *one*. At the table he plays like a pack hunter with a rulebook — designate the Quarry, assign the roles, close the horns, and the target's movement becomes a puzzle with printed exits. He needs willing allies the way fire needs air; deny him the formation and he's a strong man with a spear. Give him the formation and the Quarry is *inside the bull* — and the bull has horns, and the horns do not open.", "source_file": "36-shaka.md"}, {"id": "jack-the-ripper", "module": "37", "figure": "Jack the Ripper", "title": "JACK THE RIPPER", "detail": "summary", "technique": "Malicious Blessing", "tier": "IV", "role": null, "ce_ability": null, "primary_verb": null, "region": "London", "era": "1888 · 19th c.", "culture": "English", "concept": "They never caught him — so the world never stopped inventing him, and the invention learned to kill.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Faithful summary of U15-01; mechanics per the audited dossier, not reinvented here.*\n\n- **Core loop:** bonus action, 1 CE, touch via the Gentleman's Gloves — one unattended handheld throwable mundane object becomes a **Blessed Weapon** for 1 minute (counts as a cursed tool; minimum 1 Murder Die base damage; wielder is proficient; uses Dex or CE ability). **Property slots:** 1 (L1) → 2 (L6) → 3 (L11) → 4 (L18). **Murder Die:** d6 → d8 → d10 → d12. **One-damage-rider-per-hit** anti-stacking law.\n- **Properties:** six base (Razor, Needle, Anchor, Thread, Return, False Innocence) + Execution/Guard (L6) + Guillotine/Bloodhound/Betrayal (L11).\n- **L3:** **Prepared Murder** (action + 1 CE; PB trigger traps, 2×PB at 18) and **London Bridge** (5-ft free move, no action; once/turn ricochet reroll, no action — each free once per turn).\n- **L6–18:** **Grand Blessing** — environmental features, each blessing costing an **action** plus: Large 2 CE / Huge 4 CE / Structure 6 CE (baseline 2/4/6 dice + CE mod).\n- **L11 Maximum: Dear God** (action, 10 CE, 1 min): blood-coated objects and unarmored strikes carry every known Murder Property; **Final Execution**: 8 Murder Dice + CE mod, ignores-resistance rider.\n- **L18:** hour-long handheld Blessings; no-action blessing once/turn.\n- **L20 — The World Will Not Name Him:** once per long rest, when you would be detected, identified, or remembered — scrying, truesight, testimony, any record — the attempt fails (Heaven declines to fix you, as your vow provides), and you may teleport up to 60 ft to an unoccupied space you can see as part of the same reaction. *He will never be caught. He will never be known, either.*\n- **Domain Expansion: London Bridge Is Falling Down** (20 CE, full-turn action, 60-ft enclosed): at initiative 20, the sure-hit auto-assigns one temporary Murder Property **plus** one autonomous hostile action to enemies (save halves). **800 clash points · 5-round burnout · 2-minute duration** · barrier HP per approved formula (per zack's 10 Sept 2026 bookkeeping ruling).", "source_file": "37-jack.md"}, {"id": "qin-shi-huang", "module": "38", "figure": "Qin Shi Huang", "title": "QIN SHI HUANG", "detail": "summary", "technique": "Mandate of the First Emperor", "tier": "V", "role": null, "ce_ability": null, "primary_verb": null, "region": "China", "era": "259–210 BCE · 3rd c. BCE", "culture": "Chinese", "concept": "He unified all under heaven and found it insufficient — so he set out to unify heaven too.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Faithful summary of U15-02; mechanics per the audited dossier.*\n\n- **Core loop:** **Crux Star** perception (60-ft Gaze, bonus action, 1 CE, 1 min) → **Flow Break** debuff (attack −1 Imperial Die; one damage roll −1 die + mod; save DC −1; L6 **Imperial Disruption** targets a specific Technique Star) → **Tribute** resource (cap PB → PB+CE mod at 18; gain 1/round on meaningful damage reduction, failed attack, or redirect).\n- **Fivefold Chi You forms:** **Drifting Tortoise** (replace attack, 1 CE: ranged Crux strike applies Flow Break, no damage); **Heavenly Phoenix** (reaction, 2 CE: reduce damage 2 Imperial Dice + mod; consume Flow Break → 3 dice; reduce ≥10 → 1 Tribute); **Mount Tai Dragon Claw** (L3: replace attack, 2 CE, 2 dice + mod piercing, Tribute slow); **White Tiger Crescent Moon** (L3: action/replace, 2 CE, 2 dice + mod bludgeoning + push 15 ft/prone); **Swallow Slash** (L11: sword, 2 CE, weapon + 2 dice, up to 3 Tribute → +1 die each).\n- **L6:** **Sovereign Sight**; **Celestial Reversal** (Phoenix to 0 + 1 Tribute → free unarmed strike in the same reaction).\n- **L11:** **Goujian** (CE sword; stores reduced force → next Swallow Slash + Tribute dice); **No King Stands Above Me** (successful save vs. hostile technique with Gaze active: reaction + 2 CE applies Flow Break to the creator, once/round); **Maximum: King of All Beginnings** (action, 10 CE, requires maximum Tribute: all visible hostiles/effects have Flow Break until end of next turn; consume any number once each; first Phoenix free).\n- **L18:** Imperial Die d12; Tribute cap PB+CE mod; PB Flow Break targets.\n- **L20 — Tianxia, Complete:** once per long rest (bonus action): for 1 minute, Flow Break rests on every hostile creature you can see — no Gaze targeting required, the gaze becomes the sky — and your Tribute cap is doubled. *All under heaven, administered all at once.*\n- **Drawback:** **Mirror-Touch Synesthesia** — 1 Imperial Die psychic when a visible creature takes ≥10 damage.\n- **Domain: All Under Heaven — Throne of the First Emperor** (20 CE, full-turn, 60-ft enclosed): at initiative 20, **Imperial Meridian** auto-Flow-Breaks one hostile; **Tribute of Heaven** uncaps gain; **Five Forms One Emperor** chains 3 different forms paying costs without action/reaction spend. **1,000 clash points · 3-round burnout · 3-minute duration** · barrier HP per approved formula (per zack's 10 Sept 2026 bookkeeping ruling).", "source_file": "38-qin.md"}, {"id": "nikola-tesla", "module": "39", "figure": "Nikola Tesla", "title": "NIKOLA TESLA", "detail": "summary", "technique": "Super Automaton β", "tier": "V", "role": null, "ce_ability": null, "primary_verb": null, "region": "Serbia / USA", "era": "1856–1943 · 19th–20th c.", "culture": "Serbian-American", "concept": "He tried to give the world free lightning, and the world billed him for it — so he came back to collect.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Faithful summary of U15-03; mechanics per the audited dossier including zack's 10 Sept 2026 rulings.*\n\n- **Core loop:** **Vector-locked armor** (bonus action, 1 CE, 10 min): all voluntary movement must be straight-line **Vectors** ≥10 ft; **Broken Equation** — forcibly stopped before completing 10 ft → speed zeroed. **Attack profiles** keyed to final uninterrupted Vector length: **PPP** (10+ ft: +1d6 force), **PPJ** (20+: Str save or pushed 15 ft, follow 10 ft), **PPB** (30+: prone / drop item / suppress reactions / disadvantage on next Str/Dex save), **Maximum Velocity** (40+: 3d6 force rider + Str save or push+prone; **Overrun** forces +10 ft continuation).\n- **L3: Ground Fault** (zack-delegated feature): when Broken Equation triggers, reaction — each creature within 10 ft makes a Dex save vs. technique DC: 2d8 lightning on failure, half on success. Usable PB times per long rest.\n- **L6: Domain — Gematria Zone, Prison of the Gods** (prototype): nonlethal rule-Domain, no lethal sure-hit; initiative-20 generates an **Experiment** (d6 table); success advances **Acceleration Stage** (0→II at 6–10; begins at II, cap IV at 11–17; begins at II, choose experiment, cap V at 18). Stages: +10 ft speed each; **II = Tesla Step** (preserve Vector through one 90° turn); **III** = walls/ceilings/air-grid vectors; **V (18)** = PB Tesla Steps/turn in 3D. Cost: **action, 10 CE** (8 CE at 18th); ~32-ft cube (named R038 exception). Per zack's ruling, the Domain unlocks at **6th** (moved from 3rd).\n- **L11:** 3 **Super Tesla Coils**/long rest (not restorable by CE/short rest/RCT); **Tesla Warp** (bonus action, 4 CE, 1 Coil: teleport to a coordinate prepared at end of a turn inside the Zone, preserving Vector continuity).\n- **Explicit counterplay** (per dossier): contest, body-block lanes, grapple, trigger Broken Equation.\n- **L20 — The Current Decides:** once per long rest (reaction): when your Broken Equation triggers, instead of grounding at your position you may place the Ground Fault burst at any point within 60 ft of you — the current chooses its path — and you regain one expended Super Tesla Coil. *The current goes where it goes.*\n- **Bookkeeping:** **1,000 clash points · 3-round burnout · 3-minute duration** · barrier HP per approved formula (per zack's 10 Sept 2026 rulings).", "source_file": "39-tesla.md"}, {"id": "simo-h-yh", "module": "40", "figure": "Simo Häyhä", "title": "SIMO HÄYHÄ", "detail": "summary", "technique": "White Death", "tier": "V", "role": null, "ce_ability": null, "primary_verb": null, "region": "Finland", "era": "1905–2002 · 20th c.", "culture": "Finnish", "concept": "Five hundred and five confirmed — and the one bullet that found him only made him harder to kill.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Faithful summary of U15-04; mechanics per the audited dossier including zack's 10 Sept 2026 fills.*\n\n- **Core loop:** body-as-ammunition sniper; every enemy independently tracked **Unknown → Bearing → Located**.\n- **L1: Isänmaalle Flesh Round** (loading: 1 CE + PB HP; sacrificed HP unhealable until start of next turn; stationary shots ignore long-range disadvantage).\n- **L3: Sniper's Nest** (action, 1 CE; firing doesn't end Stealth within 5 ft; never auto-raises Bearing → Located).\n- **L6 — organ rounds** (true sacrifices; organ unrestorable during the encounter by RCT/healing/temp HP/another feature; long rest restores all): **Kidney/Ilmatar** (−10% max HP: rifle + 2d6, then 20-ft Dex-save piercing — 4d6 at L6, 5d6 at L11, 6d6 at L18); **Liver/Lemminkäinen** (−15%: one roll along a visible line to rifle max range, every beaten AC hit; first rifle + 3d6, later 2d6; ignores cover, ignores piercing resistance); **No Scope**.\n- **L11:** **Spleen/Mielikki** (reaction, −15% max HP: fire before a triggering action resolves; target at 0 HP or incapacitated → the triggering action never occurs; per zack's fill, triggering actions include legendary actions, but not lair actions or initiative-20 Domain effects); **Pancreas/Ukonvasara** (action, −20%: rifle + 8d6, no reactions against the shot, ignores piercing resistance [immunity → resistance], non-Domain damage floor of half); **543** (knows true death verdicts).\n- **L18:** Nest-exit information drops.\n- **L20 — The Face That Lived:** once per long rest, when you are reduced to 0 hit points, you are reduced to 1 HP instead — the bullet that found him only made him harder to kill — and every enemy you are tracking advances one information stage (Unknown → Bearing → Located), the snow learning their faces at last.\n- **Maximum: The 543rd Bullet / Salvation** (action, 5 CE, heart sacrifice; requires all four organ rounds fired): max HP = 1, current HP = 1, no HP/temp HP until the shot resolves, cannot voluntarily move; one rifle attack — no disadvantage, ignores cover except total, ignores resistance [immunity → resistance], non-Domain damage floor half; on hit: rifle + 12d6 piercing, then Con save or **Mortal Wound** until end of Simo's next turn (target max HP reduced by piercing damage dealt). After the shot, Simo falls unconscious and dying; RCT permitted only after the shot resolves.\n- **Domain:** **NONE — per dossier, explicit.** Clash points N/A.\n- **Table note** (per zack's fill): the body-horror *narration* is agreed at character creation; the costs are self-directed and consent-inherent.", "source_file": "40-simo.md"}, {"id": "raiden-tameemon", "module": "41", "figure": "Raiden Tameemon", "title": "RAIDEN TAMEEMON", "detail": "summary", "technique": "Hundred Seals Physique", "tier": "IV", "role": null, "ce_ability": null, "primary_verb": null, "region": "Japan", "era": "1767–1814 · 18th–19th c.", "culture": "Japanese", "concept": "Two hundred and fifty-four bouts. Ten draws. Zero losses. Death had to cheat — it couldn't beat him in the ring.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Faithful summary of U15-05; mechanics per the audited dossier.*\n\n- **Core loop:** twelve **Muscle Bands** across four regions (Left Arm / Right Arm / Legs / Frame), default 3/3/3/3; **Muscle Migration** (bonus action): move up to PB Bands between regions within capacity limits; Bands are never spent. **Region states** by band count — Arms: disadvantage → basic → balanced → advantage + once/turn +PB damage at 4; Legs: speed −20 → −10 → balanced → +10 at 4; Frame: −2 AC → −1 AC → balanced → +1 AC at 4. (Never modifies ability scores — no cap interaction.)\n- **L3: The Forbidden Four** — **Harite** (arm 4+); **Sabaori** (arms 7+ + grapple); **Kannuki** (both arms 4+ — limb-gated interference only, never generic technique suppression, per dossier); **Teppo** (legs 4+ and arm 4+). Each Forbidden technique replaces one attack when its Band requirement is naturally fulfilled (per L18 Forbidden Technique Mastery).\n- **L6: Full Muscle Control** — capacity 5; **Overpressure** (strenuous 5-Band use deals PB internal damage afterward — \"cannot be resisted or redirected\"); 5-Band region bonuses; **Instant Migration** (once/turn, move 1 Band without an action before an attack/check/save); **Wild Boar** (arm 5+ + grapple, 2 CE); **Miyama** (reaction, 2 CE: reduce melee damage by Bands in both Arms + PB — typed as damage reduction).\n- **L11: Hundred Seals Release** (bonus action, 4 CE, 1 min: capacity 6, Instant Migration moves 2; **Forbidden Output** 2×PB internal damage); **Maximum: Yatagarasu** (action, 10 CE, requires Release: Legs ≥ 5, striking Arm ≥ 4; as part of the action, charge in a straight line toward the target, minimum 10 ft; **Final Migration** sends all Leg Bands above 1 into the striking Arm — may exceed 6 for this attack; one unarmed attack: on hit +PB damage per Band in the Arm; Str save or push 30 ft + prone + lose reactions; blocking/parrying reduction halved; **Recoil:** 10% max HP damage + striking Arm capacity −1 for the encounter — RCT heals HP, not capacity).\n- **L18: Perfect Migration** (start-of-turn free redistribution); **No More Holding Back** (once/turn free 5-Band use); **Forbidden Technique Mastery** (Forbidden Four no longer replace an attack when naturally fulfilled, once/turn each).\n- **L20 — Yokozuna, At Last:** the rank denied, finally taken. Your Muscle Migration may move up to PB+2 Bands, region capacity becomes 7, and once per long rest you may use Yatagarasu without the Release requirement — the bout, on his terms at last.\n- **Domain:** **NONE — per dossier, explicit.** Clash points N/A.\n- **Hygiene notes** (per dossier): flat +×PB damage bonuses do not multiply on critical hits; \"Muscular Rupture\" names the capacity-loss keyword.", "source_file": "41-raiden.md"}, {"id": "okita-s-ji", "module": "42", "figure": "Okita Sōji", "title": "OKITA SŌJI", "detail": "summary", "technique": "Unlived Blade", "tier": "IV", "role": null, "ce_ability": null, "primary_verb": null, "region": "Japan", "era": "c. 1842–1868 · 19th c.", "culture": "Japanese", "concept": "The Shinsengumi's genius died of tuberculosis at twenty-five — and his sword has been waiting for its duel ever since.", "serves": null, "features": [], "maximum": null, "domain": null, "l20": null, "summary_text": "*Faithful summary of U15-06; mechanics per the audited dossier including zack's 10 Sept 2026 rulings.*\n\n- **Core loop:** stance combo tree — **HIGH / CENTER / LOW / PASSING**; **Recenter** (bonus action); **Perfect Link** (previous Exit = next Entry → Linked, gains printed benefit).\n- **L1 — Present Swordsmanship:** **Sandanzuki** (CENTER→CENTER, replace attack, 1 CE: weapon +1 die; Link: +1 more die); **Ryuubiken** (HIGH→LOW, replace attack, 1 CE: on hit, Open Guard — target's AC is −2 vs. your next sword attack; Link: the target gains no AC bonus from a reaction against that attack); **Kisoutotsu** (LOW→PASSING, 1 CE: 10-ft approach, attack, 5-ft pass-through; Link: 15 ft, no provoke).\n- **L3:** **Demon Child** (bonus action, 2 CE, 1 min: +10 speed); **Demon Follow-Through** — once/turn after hitting with a named technique, if its Exit matches a different known technique's Entry, perform it as part of the same action at normal cost; after the sequence, take PB internal damage (unpreventable).\n- **L6 — Sword Time:** three **Unlived Future Forms** (each long rest: UNLIVED → SPENT on first use; an Unlived Future Form may ignore its Entry, keeps its Exit; natural entry grants Perfect Link): **Hiryuu** (PASSING→HIGH, 0 CE: 10-ft leap incl. vertical, attack; Link: advantage); **Sharyuu** (LOW→CENTER, 0 CE: attack; on hit rotate 5 ft no provoke, another hostile in reach takes PB slashing [Link: 2×PB]); **Torao** (HIGH→CENTER, 0 CE: weapon +2 dice; Str save or prone; Link: non-Domain damage reduction vs. Torao reduced by PB). **No-Kamae** (reaction, 1 CE, when missed by melee: 5-ft shift, choose stance).\n- **L11:** **Demon Child Release** (bonus action, 4 CE, once/long rest, 1 min: +20 speed, Follow-Through twice/turn, +5 ft inside techniques; each Follow-Through still deals PB internal; on end: 10% max HP damage — cannot drop below 1 HP \"unless you voluntarily kept the state active after reaching half HP\"); **Combination Recipe Kisou Sandanzuki** — Kisoutotsu → Sandanzuki may be performed as a single Demon Follow-Through chain (the recipe bridges PASSING→CENTER), each technique at its normal CE cost; the completed chain gains Perfect Link benefits; **Maximum: Enpi Reiten** (action, 10 CE, requires Release: choose up to PB distinct known techniques, arrange a sequence; Present Forms obey Entry/Exit; Unlived Future Forms may bridge any Entry mismatch even if SPENT; no technique creates Follow-Through; each technique different; after the last strike Release ends; 5% max HP per attack after the first; then normal Technique Burnout).\n- **L18: Sword Demon of Truth** — **Realized Future** (one form, chosen at long rest, repeatable at 2 CE/use with Entry enforced); **Perfect Sword Time** (once/turn alter a Linked technique's printed Exit); **Final Combination: Tenshou Sandanzuki** — see L20.\n- **L20 — Tenshou Sandanzuki, Realized:** once per long rest (action, 4 CE): the combination he never got to perform — three thrusts in one motion. Make three sword attacks, against one creature or divided among creatures within your reach: each deals weapon damage +2 dice, and the third thrust ignores AC bonuses from cover and reactions. This use never triggers Demon Follow-Through — the future, finally lived on its own terms.\n- **CE ability** (zack-ruled): player's choice of **DEX or WIS** at character creation, locked thereafter; all CE-ability-keyed features follow the choice.\n- **Domain:** **NONE — per dossier, explicit.** Clash points N/A.\n- **Clarification** (per dossier): an Unlived Future Form used as a bridge in Enpi Reiten counts as \"selected\" for the distinct-technique rule.", "source_file": "42-okita.md"}, {"id": "imhotep", "module": "49", "figure": "Imhotep", "title": "IMHOTEP", "detail": "full", "technique": "THE STEP PYRAMID", "tier": "V", "role": "controller / builder", "ce_ability": "INT", "primary_verb": null, "region": "Egypt", "era": "c. 2700–2648 BCE · 27th c. BCE", "culture": "Egyptian", "concept": "Three thousand years of worship made a god — and the man is still inside it, trying to finish the building.", "serves": "**SERVES: ALL-OUT WAR** — the only builder of permanent cursed architecture: fortresses for the war's strongholds, seals for its prisons, and the only medium the End of War's terms can be permanently inscribed on. Every faction's endgame needs the Mason, and he is taking commissions. **COLLISION (Phase 2):** his god-half feeds directly on the Shift's visibility — the more the world sees curses, the stronger he grows. His Seventh Stage, if completed during the war, becomes the single most contested *place* on the board. # PART B — TECHNIQUE: \"THE STEP PYRAMID\" *Tier V cursed technique · Suggested CE ability: INT · Combat role: controller / builder* The technique raises architecture from cursed energy — limestone-white, warm to the touch, smelling of dust and myrrh. Everything raised is announced: the architect speaks the work before it stands. (\"A vow unheard is a vow unwitnessed.\") **Raised structures:** walls and courts are solid (each 10-ft section: AC 15, 30 HP). They persist for 1 minute (10 minutes at L18+), or permanently if raised during the L20 ascension. You may maintain structures whose total sections do not exceed 6 + PB. ## L1 — Foundation **Cost:** 2 CE per 10-ft section · **Action:** raise. Raise mastaba-block wall sections within 60 ft: each section is 10 ft long, 10 ft high, 5 ft thick. Total cover. Sections must connect to the ground or to another section you raised. You may raise up to PB sections per action. *The first course. Every building begins with a declaration of where the wall stands.* ## L3 — The First Court **Cost:** 4 CE · **Action:** raise and declare. Raise up to four connected wall sections forming an enclosure (up to 30 ft square; fewer sections may use existing walls or terrain). Upon raising it, **declare one Law of the Court** — spoken aloud, heard by all present: - **Law of Stillness:** the court's interior is difficult terrain. - **Law of Weight:** ranged attacks made through or into the court have disadvantage — the air is heavy with declared stone. - **Law of Passage:** name the creatures permitted within; all others cannot enter (the geometry refuses — they may still attack the walls). The Law is announced at the threshold — any creature that enters after the announcement consents to it (the willing valve: do not enter). Creatures already inside the area when the court is raised are not bound by the Law — they were not announced to. The Law lasts while the court stands. *The court is the pyramid's argument in miniature: here, this holds.* ## L6 — The Shaft & The Teeth **The Shaft — Cost:** 3 CE · **Bonus action:** open. Open a 10-ft square, 20-ft deep shaft at a point within 60 ft. Each creature there makes a DEX save vs your technique save DC or falls (2d6 bludgeoning). Climbing out costs 20 ft of movement. The shaft fills after 1 minute. **The Teeth — Passive:** your raised structures are warded. Each section gains +15 HP, and any creature that strikes a section with a melee attack takes PB force damage (the stone answers). *The pyramid defends its architect. It has had forty-seven centuries of practice.* ## L11 — The Architect's Vow **Cost:** 6 CE · **Action:** inscribe. Inscribe a binding Law with a **price** into a structure you raised. The Law is spoken at the threshold; entry after the announcement is consent. Creatures already inside the structure when the Law is inscribed are not bound by it — they were not announced to. When the Law is violated, Heaven collects — no save (it is a vow, not an attack). Examples: - *\"Whoever sheds blood within this court pays 2d8 force.\"* - *\"No weapon may be drawn here; the drawn blade costs its bearer 1d10 force per round held.\"* - *\"Whoever speaks falsehood in this court is marked — all here know it.\"* (Heaven marks the lie; no save, but only *deliberate* falsehood.) You may maintain inscribed Laws on up to PB structures. A Law ends when its structure falls. *The vow is the building's soul. Stone forgets nothing, and Heaven forgets less.* ## L18 — The Seventh Stage **Cost:** 12 CE · **Action:** raise · **Once per long rest.**", "features": [{"level": 1, "name": "Foundation", "cost_line": "Cost: 2 CE per 10-ft section · Action: raise.", "kind": "feature", "text": "*Tier V cursed technique · Suggested CE ability: INT · Combat role: controller / builder* The technique raises architecture from cursed energy — limestone-white, warm to the touch, smelling of dust and myrrh. Everything raised is announced: the architect speaks the work before it stands. (\"A vow unheard is a vow unwitnessed.\") **Raised structures:** walls and courts are solid (each 10-ft section: AC 15, 30 HP). They persist for 1 minute (10 minutes at L18+), or permanently if raised during the L20 ascension. You may maintain structures whose total sections do not exceed 6 + PB.\n\nRaise mastaba-block wall sections within 60 ft: each section is 10 ft long, 10 ft high, 5 ft thick. Total cover. Sections must connect to the ground or to another section you raised. You may raise up to PB sections per action. *The first course. Every building begins with a declaration of where the wall stands.*"}, {"level": 3, "name": "The First Court", "cost_line": "Cost: 4 CE · Action: raise and declare.", "kind": "feature", "text": "Raise up to four connected wall sections forming an enclosure (up to 30 ft square; fewer sections may use existing walls or terrain). Upon raising it, **declare one Law of the Court** — spoken aloud, heard by all present: - **Law of Stillness:** the court's interior is difficult terrain. - **Law of Weight:** ranged attacks made through or into the court have disadvantage — the air is heavy with declared stone. - **Law of Passage:** name the creatures permitted within; all others cannot enter (the geometry refuses — they may still attack the walls). The Law is announced at the threshold — any creature that enters after the announcement consents to it (the willing valve: do not enter). Creatures already inside the area when the court is raised are not bound by the Law — they were not announced to. The Law lasts while the court stands. *The court is the pyramid's argument in miniature: here, this holds.*"}, {"level": 6, "name": "The Shaft & The Teeth", "cost_line": "The Shaft — Cost: 3 CE · Bonus action: open.", "kind": "feature", "text": "Open a 10-ft square, 20-ft deep shaft at a point within 60 ft. Each creature there makes a DEX save vs your technique save DC or falls (2d6 bludgeoning). Climbing out costs 20 ft of movement. The shaft fills after 1 minute. **The Teeth — Passive:** your raised structures are warded. Each section gains +15 HP, and any creature that strikes a section with a melee attack takes PB force damage (the stone answers). *The pyramid defends its architect. It has had forty-seven centuries of practice.*"}, {"level": 11, "name": "The Architect's Vow", "cost_line": "Cost: 6 CE · Action: inscribe.", "kind": "feature", "text": "Inscribe a binding Law with a **price** into a structure you raised. The Law is spoken at the threshold; entry after the announcement is consent. Creatures already inside the structure when the Law is inscribed are not bound by it — they were not announced to. When the Law is violated, Heaven collects — no save (it is a vow, not an attack). Examples: - *\"Whoever sheds blood within this court pays 2d8 force.\"* - *\"No weapon may be drawn here; the drawn blade costs its bearer 1d10 force per round held.\"* - *\"Whoever speaks falsehood in this court is marked — all here know it.\"* (Heaven marks the lie; no save, but only *deliberate* falsehood.) You may maintain inscribed Laws on up to PB structures. A Law ends when its structure falls. *The vow is the building's soul. Stone forgets nothing, and Heaven forgets less.*"}, {"level": 18, "name": "The Seventh Stage", "cost_line": "Cost: 12 CE · Action: raise · Once per long rest.", "kind": "feature", "text": "Raise a complete step pyramid: 60-ft square base, six tiers, 60 ft tall, centered within 120 ft. Each tier carries one Law of your choice (any Court Law or inscribed Vow-fine; the fines apply per tier). The stone knows its builder: your allies treat the pyramid as normal terrain; your enemies treat it as difficult terrain and cannot benefit from cover behind its stones. Lasts 10 minutes. *Six stages stood at Saqqara. The seventh stands wherever he decides.*"}], "maximum": null, "domain": {"level": null, "name": "\"SAQQARA, THE FIRST STONE\"", "cost_line": "Cost: Full-turn action · 20 CE · Clash: 1,000 points (Tier V) · Burnout: 3 rounds · Radius: 60 ft.", "kind": "domain", "text": "The barrier is a necropolis at noon — white stone, impossible shadows, the smell of dust and myrrh. **Sure-hit:** the ground is his. At initiative 20, the necropolis reshapes itself at his word: open shafts beneath up to PB hostile creatures (DEX save vs technique save DC or fall 20 ft, 2d6 bludgeoning) and/or raise wall sections (up to PB) to split the battlefield — wall sections cannot be raised in a space occupied by a creature; the stone rises around them. The sure-hit guarantees the *terrain changes at his chosen points* — the only save is against falling, not against the ground moving. Structures raised inside the Domain cost no CE. *The first stone was laid here. All stone since has been commentary.*", "clash_points": 1000, "duration_min": 3, "burnout_rounds": 3, "radius": "60 ft", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The God Ascends", "cost_line": "", "kind": "l20", "text": "**The Ascension (capstone):** once per long rest, the god-half manifests fully for 1 minute. While ascended: - Structures you raise are **permanent** — real stone, remaining after combat (GM adjudicates campaign-map changes). - Your inscribed Vow-fines bypass resistance (the god's due is not negotiable). - You may raise structures as a bonus action. And the standing question, for the GM: every permanent work brings the Seventh Stage closer. Track what he builds. When the campaign's stone is sufficient, he will begin — and every faction will come to Saqqara, or wherever he lays the first course, to decide what the Seventh Stage is *for*."}, "summary_text": null, "source_file": "49-imhotep.md"}, {"id": "gilgamesh", "module": "50", "figure": "Gilgamesh", "title": "GILGAMESH", "detail": "full", "technique": "TWO-THIRDS DIVINE", "tier": "V", "role": "tyrant striker", "ce_ability": "CHA", "primary_verb": null, "region": "Mesopotamia", "era": "c. 2700 BCE · mythic", "culture": "Sumerian", "concept": "Two-thirds god because the story says so — and the story is load-bearing.", "serves": "**SERVES: ALL-OUT WAR** — the unaligned tyrant. Both sides must court him or avoid him; his prototype-seniority sets the ceiling of the war's arms race (every derived weapon yields to its original). He is the war's wildest piece and its most honest: he wants one dead friend back, and everything else is noise. **COLLISION (Phase 2):** his grief is unpriceable — Sun's models break on it. If any faction offers him a true path to Enkidu, he will burn the board to take it. The PCs may be the only ones who can offer it honestly. *Scribe — you may stop writing. The story continues without you. It always does.* # PART B — TECHNIQUE: \"TWO-THIRDS DIVINE\" *Tier V cursed technique · Suggested CE ability: CHA · Combat role: tyrant striker* The technique manifests as *seniority made physical*: his conjured weapons are the divine prototypes — the first axe, the first sword, the first spear — rendered in bronze-gold light that hurts to look at directly. They are not many. There is exactly one of each, and they are his because the story says the king holds the originals. **Prototypes & seniority:** when a prototype weapon clashes with, or is directly opposed by, a manufactured weapon or a technique-derived arm (a conjured blade, a shikigami's fang, a cursed tool's edge — anything *derived*), the prototype is senior: Gilgamesh has advantage on the clash or contest, and his strikes deal +PB damage against the wielder. Seniority never negates (no nullification) — it *outranks*. Whenever a feature calls for a prototype weapon attack and he has none conjured, he may conjure one as part of that feature's activation (paying Prototype's Edge's 1 CE additionally). **Divine damage:** damage dealt by prototypes is radiant and **ignores resistance** (not immunity). ## L1 — Prototype's Edge **Cost:** 1 CE · **Bonus action:** conjure. Conjure a divine-prototype melee weapon — axe, sword, or spear, your choice (damage as the mundane equivalent). It counts as magical, deals +PB radiant damage on a hit, and vanishes if it leaves your hand. Lasts 1 minute. *The first axe. All axes since have been commentary.* ## L3 — The Bull of Heaven **Cost:** 4 CE · **Action:** the charge. Move up to your speed in a straight line, passing through hostile creatures' spaces. Each creature whose space you enter makes a STR save vs your technique save DC or takes 3d10 + STR bludgeoning damage and is knocked prone (half damage on a success, no prone). End adjacent to one creature whose space you entered and make a prototype weapon attack against it with advantage. *The Bull came from the sky. The king went to meet it. The sky lost.* ## L6 — Two-Thirds **Passive:** the god/man split, mechanized. - **Divine Majority:** once per turn, when you take damage, reduce it by PB + CHA modifier (the god endures). - **Mortal Third:** when you are below half HP, your prototype strikes deal additional PB damage (the man fights harder dying — the Epic's pathos, weaponized). - Your prototypes ignore resistance to the damage they deal (not immunity). *Two-thirds of him cannot be killed. The third that can is the reason he bothers.* ## L11 — The First King **Cost:** 5 CE · **Reaction** · **PB times per long rest.**", "features": [{"level": 1, "name": "Prototype's Edge", "cost_line": "Cost: 1 CE · Bonus action: conjure.", "kind": "feature", "text": "*Tier V cursed technique · Suggested CE ability: CHA · Combat role: tyrant striker* The technique manifests as *seniority made physical*: his conjured weapons are the divine prototypes — the first axe, the first sword, the first spear — rendered in bronze-gold light that hurts to look at directly. They are not many. There is exactly one of each, and they are his because the story says the king holds the originals. **Prototypes & seniority:** when a prototype weapon clashes with, or is directly opposed by, a manufactured weapon or a technique-derived arm (a conjured blade, a shikigami's fang, a cursed tool's edge — anything *derived*), the prototype is senior: Gilgamesh has advantage on the clash or contest, and his strikes deal +PB damage against the wielder. Seniority never negates (no nullification) — it *outranks*. Whenever a feature calls for a prototype weapon attack and he has none conjured, he may conjure one as part of that feature's activation (paying Prototype's Edge's 1 CE additionally). **Divine damage:** damage dealt by prototypes is radiant and **ignores resistance** (not immunity).\n\nConjure a divine-prototype melee weapon — axe, sword, or spear, your choice (damage as the mundane equivalent). It counts as magical, deals +PB radiant damage on a hit, and vanishes if it leaves your hand. Lasts 1 minute. *The first axe. All axes since have been commentary.*"}, {"level": 3, "name": "The Bull of Heaven", "cost_line": "Cost: 4 CE · Action: the charge.", "kind": "feature", "text": "Move up to your speed in a straight line, passing through hostile creatures' spaces. Each creature whose space you enter makes a STR save vs your technique save DC or takes 3d10 + STR bludgeoning damage and is knocked prone (half damage on a success, no prone). End adjacent to one creature whose space you entered and make a prototype weapon attack against it with advantage. *The Bull came from the sky. The king went to meet it. The sky lost.*"}, {"level": 6, "name": "Two-Thirds", "cost_line": "Passive:", "kind": "feature", "text": "**Passive:** the god/man split, mechanized. - **Divine Majority:** once per turn, when you take damage, reduce it by PB + CHA modifier (the god endures). - **Mortal Third:** when you are below half HP, your prototype strikes deal additional PB damage (the man fights harder dying — the Epic's pathos, weaponized). - Your prototypes ignore resistance to the damage they deal (not immunity). *Two-thirds of him cannot be killed. The third that can is the reason he bothers.*"}, {"level": 11, "name": "The First King", "cost_line": "Cost: 5 CE · Reaction · PB times per long rest.", "kind": "feature", "text": "When a creature within 60 ft uses a named technique feature you have observed this encounter, answer with the prototype: make a prototype weapon attack against them. If it hits, the feature's damage or effect is **halved** until the end of their next turn — the original disciplines the copy. (It is not cancelled. Heaven does not un-throw what was thrown; the king merely reminds the copy of its place.) *Every technique in the world is descended from something. He is the something.*"}, {"level": 18, "name": "The Epic Itself", "cost_line": "Cost: 8 CE · Bonus action: invoke · Duration: 1 minute.", "kind": "feature", "text": "His legend becomes armor — the **retelling-shield**: once per round, when he takes damage, the story asserts that he endures — reduce the damage by 2d10 + CHA modifier. While invoked, his prototype strikes deal double their bonus radiant damage (all PB-sourced radiant bonuses — base, Mortal Third, EAT — are doubled). *The story says he endures. The story is load-bearing.*"}], "maximum": null, "domain": {"level": null, "name": "\"URUK, THE FIRST CITY\"", "cost_line": "Cost: Full-turn action · 20 CE · Clash: 1,000 points (Tier V) · Burnout: 3 rounds · Radius: 60 ft.", "kind": "domain", "text": "The barrier is Uruk at its height — the great walls on the horizon, the Eanna precinct blazing, the air thick with four thousand years of being *the* city. **Sure-hit:** every prototype he has ever owned strikes at once. At initiative 20, the volley falls: each hostile creature in the Domain is attacked by a spectral prototype (+PB + CHA to hit vs AC; 2d8 + PB radiant damage, ignores resistance). The walls of Uruk ring the barrier: hostile creatures treat the Domain as difficult terrain — the city resists invaders. *The first city. All cities since have been suburbs.*", "clash_points": 1000, "duration_min": 3, "burnout_rounds": 3, "radius": "60 ft", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Plant of Heartbeat", "cost_line": "", "kind": "l20", "text": "**The choice (capstone):** at L20, the quest ends — one way or the other. Choose: - **EAT:** He finally eats the Plant. He becomes fully divine: Divine Majority reduction doubles, and his prototypes' bonus radiant damage becomes +2×PB (replacing the base +PB; Mortal Third's additional +PB still applies separately). But the Epic ends — the story of the *mortal* king is over, and a god has no story: if he dies now, he dies forever (no retelling renewal). - **REFUSE:** He honors the Epic's ending — the mourner endures. Once per long rest, when reduced to 0 HP, he stands at 1 HP instead, and the story continues (narrative immortality, witnessed). The one-third man, it turns out, was the strongest part all along. *The serpent stole the plant. Forty-seven centuries later, the king gets to decide what that meant.*"}, "summary_text": null, "source_file": "50-gilgamesh.md"}, {"id": "cyrus-the-great", "module": "51", "figure": "Cyrus the Great", "title": "CYRUS THE GREAT", "detail": "full", "technique": "THE CYLINDER", "tier": "IV", "role": "edict controller / support", "ce_ability": "CHA", "primary_verb": null, "region": "Persia", "era": "c. 600–530 BCE · 6th c. BCE", "culture": "Persian", "concept": "The first universal emperor returns with his own draft of the end of war — and it is not the General's.", "serves": "**SERVES: ALL-OUT WAR** — his tolerance-zones are senior public vows that both sides must operate inside; the war's shape will be negotiated in his courts whether Sun likes it or not. He is the war's would-be legislator, and legislation is a theater of war. **SERVES: INHERITANCE SHIFT** — his edicts shelter the awakened: sanctuary-zones where new sorcerers can exist without being drafted, positioned, or Commentated. Phase 2's only neutral ground, and it is growing. # PART B — TECHNIQUE: \"THE CYLINDER\" *Tier IV cursed technique · Suggested CE ability: CHA · Combat role: edict controller / support* The technique speaks law. Edicts are proclaimed aloud — in Old Persian first, then in the hearers' tongue (the Cylinder translates itself; witnesses always understand). Every edict has a **rule** and a **fine**: the rule binds all within the radius, the fine is Heaven's price for violation — automatic, no save (it is a vow, not an attack). The willing valve is *presence*: the edict is announced before it takes hold, and any creature that remains within the radius after the announcement consents to the law. Leaving the radius ends the edict's hold on that creature. **Edict radius:** 30 ft (60 ft at L6, 120 ft at L18). **Duration:** 1 minute, no concentration. ## L1 — Proclaim **Cost:** 2 CE · **Bonus action:** speak. Speak a minor edict. Choose one: - **Edict of Open Gates:** allies within the radius gain +10 ft movement (the roads are kept). - **Edict of Restoration:** allies who regain HP within the radius regain +PB additional HP (the temples are funded). - **Edict of Tolerance:** creatures within the radius have advantage on saves against charm and fear (no one is compelled in the king's peace). One edict at a time. The edict is announced; all present hear it. *The first declaration of rights was a paragraph. Paragraphs, witnessed, are load-bearing.* ## L3 — The Cylinder's Echo **Passive:** your edicts echo. Edicts last their full minute without concentration. You may maintain **two** edicts simultaneously (pay each edict's cost). When you speak an edict, you may choose to have it recorded — a clay token, warm to the touch — which a willing ally can later read aloud to re-establish the edict (using your technique save DC) as an action. *The Cylinder was copied. Copies, witnessed, hold.* ## L6 — Satrap's Administration **Cost:** 3 CE · **Action:** delegate. Name one willing ally within 60 ft as your **satrap**: they may speak and enforce your edicts (using your technique save DC and costs, paid from your CE), and your edict radius becomes 60 ft while the satrapy holds (1 minute). You may have PB satraps at once. *An empire is a vow spoken to millions. The satraps are how millions hear it.* ## L11 — The Great Edict **Cost:** 7 CE · **Action:** proclaim the Great Law. Speak one battlefield-wide edict offering a **choice** — the choice is the willing valve, and Heaven enforces the chosen branch: - ***\"Let no blood be shed.\"*** Any creature that deals damage within the radius pays **3d8 force** (Heaven's fine, no save) — **or** lays down its weapons and takes no hostile action, gaining **resistance to all damage** while it keeps the peace within the radius. - ***\"Let the wronged be restored.\"*** Hostile creatures within the radius have disadvantage on attacks against creatures below half HP (the king's protection extends downward) — or they may spend their action to *yield*, ending all their hostile conditions (charmed, frightened, and similar, at the GM's discretion) as the edict's mercy takes them. The Great Law is announced in full before it takes hold. Creatures that leave the radius are free of it. *The Cylinder freed the captives of Babylon with a paragraph. Paragraphs scale.*", "features": [{"level": 1, "name": "Proclaim", "cost_line": "Cost: 2 CE · Bonus action: speak.", "kind": "feature", "text": "*Tier IV cursed technique · Suggested CE ability: CHA · Combat role: edict controller / support* The technique speaks law. Edicts are proclaimed aloud — in Old Persian first, then in the hearers' tongue (the Cylinder translates itself; witnesses always understand). Every edict has a **rule** and a **fine**: the rule binds all within the radius, the fine is Heaven's price for violation — automatic, no save (it is a vow, not an attack). The willing valve is *presence*: the edict is announced before it takes hold, and any creature that remains within the radius after the announcement consents to the law. Leaving the radius ends the edict's hold on that creature. **Edict radius:** 30 ft (60 ft at L6, 120 ft at L18). **Duration:** 1 minute, no concentration.\n\nSpeak a minor edict. Choose one: - **Edict of Open Gates:** allies within the radius gain +10 ft movement (the roads are kept). - **Edict of Restoration:** allies who regain HP within the radius regain +PB additional HP (the temples are funded). - **Edict of Tolerance:** creatures within the radius have advantage on saves against charm and fear (no one is compelled in the king's peace). One edict at a time. The edict is announced; all present hear it. *The first declaration of rights was a paragraph. Paragraphs, witnessed, are load-bearing.*"}, {"level": 3, "name": "The Cylinder's Echo", "cost_line": "Passive:", "kind": "feature", "text": "**Passive:** your edicts echo. Edicts last their full minute without concentration. You may maintain **two** edicts simultaneously (pay each edict's cost). When you speak an edict, you may choose to have it recorded — a clay token, warm to the touch — which a willing ally can later read aloud to re-establish the edict (using your technique save DC) as an action. *The Cylinder was copied. Copies, witnessed, hold.*"}, {"level": 6, "name": "Satrap's Administration", "cost_line": "Cost: 3 CE · Action: delegate.", "kind": "feature", "text": "Name one willing ally within 60 ft as your **satrap**: they may speak and enforce your edicts (using your technique save DC and costs, paid from your CE), and your edict radius becomes 60 ft while the satrapy holds (1 minute). You may have PB satraps at once. *An empire is a vow spoken to millions. The satraps are how millions hear it.*"}, {"level": 11, "name": "The Great Edict", "cost_line": "Cost: 7 CE · Action: proclaim the Great Law.", "kind": "feature", "text": "Speak one battlefield-wide edict offering a **choice** — the choice is the willing valve, and Heaven enforces the chosen branch: - ***\"Let no blood be shed.\"*** Any creature that deals damage within the radius pays **3d8 force** (Heaven's fine, no save) — **or** lays down its weapons and takes no hostile action, gaining **resistance to all damage** while it keeps the peace within the radius. - ***\"Let the wronged be restored.\"*** Hostile creatures within the radius have disadvantage on attacks against creatures below half HP (the king's protection extends downward) — or they may spend their action to *yield*, ending all their hostile conditions (charmed, frightened, and similar, at the GM's discretion) as the edict's mercy takes them. The Great Law is announced in full before it takes hold. Creatures that leave the radius are free of it. *The Cylinder freed the captives of Babylon with a paragraph. Paragraphs scale.*"}, {"level": 18, "name": "Universal Empire", "cost_line": "Passive:", "kind": "feature", "text": "**Passive:** the empire, complete. Your edict radius becomes **120 ft**. You may maintain **three** edicts simultaneously. Your Heaven-fines increase by +PB force damage. Allies who keep your edicts (taking no violating action for the edict's duration) gain **+2 to all saving throws** while within the radius — the empire protects the law-abiding. *From the Aegean to the Indus, one law. The satraps are still reading it.*"}], "maximum": null, "domain": {"level": null, "name": "\"BABYLON OPENED\"", "cost_line": "Cost: Full-turn action · 20 CE · Clash: 800 points (Tier IV) · Burnout: 5 rounds · Radius: 60 ft.", "kind": "domain", "text": "The barrier is Babylon in 539 BCE — the Ishtar Gate blazing blue and gold, the streets orderly, the great doors *open* (Cyrus took the city without a siege; the priests opened the gates). **Sure-hit:** the gates open for everyone. Every hostile creature in the Domain is **offered the edict**, witnessed by Heaven, and must choose: - **Submit:** bound — cannot attack Cyrus or his allies while within the Domain, but gains **resistance to all damage** (the protected captive; the Cylinder's mercy is real). - **Defy:** marked — at initiative 20, Heaven collects from the defiant: **4d10 force damage**, no save (they chose; Heaven collects). The choice is the whole Domain. Leaving the Domain ends both conditions. A creature that submits may later choose to defy (and be marked) — the door swings both ways, but Heaven remembers which way you walked. *The priests opened the gates. The king did not have to knock. He is still not knocking.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60 ft", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Author of Peace", "cost_line": "", "kind": "l20", "text": "**The new Cylinder (capstone):** once per campaign arc, Cyrus may write a **permanent edict** — a new Cylinder, in clay, in his own hand. Choose one Great Law and inscribe it permanently into a location (a building, a district, a battlefield — GM adjudicates scale): e.g., *\"No compulsion may be spoken here\"* (a permanent sanctuary — charm, fear, and command effects fail within; the willing valve: no one is forced to enter), or *\"The wronged shall be restored\"* (healing is doubled within; violence pays the fine, forever). The inscription is public, witnessed, and Heaven-enforced. It can only be unmade the way the old Cylinder could be unmade: by breaking the clay — and the world tends to notice when someone breaks Cyrus's clay. *He wrote peace first. He intends to write it last.*"}, "summary_text": null, "source_file": "51-cyrus.md"}, {"id": "amanirenas", "module": "52", "figure": "Amanirenas", "title": "AMANIRENAS", "detail": "full", "technique": "THE BRONZE HEAD", "tier": "IV", "role": "Trophy striker", "ce_ability": "STR", "primary_verb": "Claim", "region": "Kush / Nubia", "era": "c. 60–10 BCE · 1st c. BCE", "culture": "Kushite", "concept": "She beat Rome in the field, dictated the peace, and buried the emperor's bronze head under her throne so she could step on it every day — then surrendered the credit for the victory to history, and kept the substance.", "serves": "**SERVES: BOTH.** *Inheritance Shift* — her Phase-1 return anchored the African theater; the Nile road's awakening is hers. *All-Out War* — her Taken host holds the south, and her trophy-theft is aimed at the enemy's command layer. ## PART B — TECHNIQUE: THE BRONZE HEAD **Tier IV · Trophy striker · suggested CE ability STR or CHA (chosen at inheritance; locked thereafter) · Primary verb: *Claim.***", "features": [{"level": 1, "name": "Claim the Fallen", "cost_line": "Passive.", "kind": "feature", "text": "**Tier IV · Trophy striker · suggested CE ability STR or CHA (chosen at inheritance; locked thereafter) · Primary verb: *Claim.*** *Empires write the histories. The defeated keep the heads. The Bronze Head treats every victory as a transfer, witnessed by Heaven: what falls in her presence becomes hers — and she fights with what she has taken.* **Trophies.** When you reduce a creature to 0 hit points with an attack, or when a creature within 30 ft of you drops a weapon, standard, or focus (destroyed, disarmed, or surrendered), you may claim it as a **Trophy** (no action required). You can hold a number of Trophies equal to your proficiency bonus. A Trophy is a mote of cursed energy shaped like what was taken; claiming a magic weapon does not grant its properties unless a feature says so. Trophies persist until you dismiss them (no action) or finish a long rest.\n\nWhen you claim a Trophy, you gain temporary hit points equal to your proficiency bonus + the defeated creature's proficiency bonus (if it had one). (The taking feeds her. It always has.)"}, {"level": 1, "name": "The Spoils Fight", "cost_line": "Passive.", "kind": "feature", "text": "While you hold at least one Trophy, your melee weapon attacks deal additional force damage equal to the number of Trophies you hold (maximum +6). (She fights with what she has taken, and she has taken so much.)"}, {"level": 3, "name": "Wear the Taken", "cost_line": "Bonus action · 2 CE · 1 minute (ends if you dismiss your Trophies).", "kind": "feature", "text": "Choose one Trophy you hold. You don its aspect until the effect ends, gaining one benefit based on what was taken (GM's call, chosen at claim): the *swiftness* of a cavalry standard (+10 ft speed), the *steadiness* of an archer's bow (advantage on ranged attack rolls), the *weight* of a champion's blade (+2 to melee damage rolls), or the *rank* of a commander's seal (advantage on Charisma checks against soldiers). You may only wear one aspect at a time. (She does not imitate the defeated. She *outranks* them.)"}, {"level": 3, "name": "The Kandake's Tithe", "cost_line": "Action · 3 CE.", "kind": "feature", "text": "One creature you can see within 30 ft may *willingly* render you tribute — a weapon, an object, a secret spoken aloud, a promise. If it does, you gain it as a Trophy (even without a defeat), and the giver cannot willingly act against you until the end of your next turn. A creature that declines suffers no effect. (Tribute rendered willingly counts. Samos taught her that a dictated peace is also a conquest.)"}, {"level": 6, "name": "The Threshold", "cost_line": "Bonus action · 5 CE · 1 minute (concentration).", "kind": "feature", "text": "You set a Trophy beneath your feet — a 15-ft radius **Threshold** centered on yourself, moving with you. While it stands: you cannot be moved against your will; you have advantage on saving throws against being frightened or charmed; and any enemy that starts its turn inside the Threshold must succeed on a Wisdom saving throw against your technique save DC or have disadvantage on attack rolls against you until the start of its next turn. The rules are disclosed — a creature that understands them may choose to fight accordingly. (The bronze head under the stairs. The ground is hers.)"}, {"level": 11, "name": "Tithe of the Dying", "cost_line": "Passive.", "kind": "feature", "text": "Your claim range extends to 60 ft, and you may now claim a Trophy from any creature reduced to 0 hit points within range — even if you did not defeat it, even if an ally did. Additionally, when you claim a Trophy, you may immediately transfer its temporary hit points from Claim the Fallen to an ally within 30 ft instead of taking them yourself. (The queen's share. The host eats because she takes.)"}, {"level": 18, "name": "The Treaty of Samos", "cost_line": "Action · 8 CE · once per long rest.", "kind": "feature", "text": "You dictate **terms** to one creature you can see within 60 ft that is below half its hit point maximum: a single demand, spoken aloud, no longer than a sentence (e.g., \"yield your weapon,\" \"order the retreat\"). The creature chooses: **accept** — it complies to the best of its ability for 1 minute (it will not harm itself to comply); or **refuse** — it takes 8d10 psychic damage (no save; the refusal is witnessed) and you claim a Trophy from it as if it had been defeated. Heaven enforces the witnessing, not the compliance. A creature that cannot understand you is unaffected. (She ended a war with a sentence.)"}], "maximum": {"level": null, "name": "The Head Under the Throne", "cost_line": "Action · 10 CE · requires at least 3 Trophies.", "kind": "maximum", "text": "You expend all Trophies you hold and make one melee weapon attack against a creature you can see within your reach. On a hit, it deals an additional 2d10 force damage *per Trophy expended*. On a miss, it deals half the damage it would have dealt on a hit (rounded down). The Trophies are expended whether the attack hits or misses. (Every head she ever took, in a single strike. The inventory, presented.)"}, "domain": {"level": null, "name": "Meroë: The Palace of Taken Things", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 40-ft radius · disclosed.", "kind": "domain", "text": "The throne room at Meroë: walls hung with taken standards, the threshold set with the bronze head. Inside this domain, the **sure-hit** is *Everything Breaks Into Her Hands* — whenever a weapon, standard, focus, or similar object held by a hostile creature inside the domain is destroyed, dropped, disarmed, or surrendered, you immediately claim it as a Trophy (ignoring your normal range, and exceeding your Trophy cap by up to 3 while the domain stands). Additionally, while the domain stands, your Spoils Fight bonus is doubled (maximum +12). (Fight her in her Palace, and you arm her with every swing.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "40-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Record, Corrected", "cost_line": "Once per long rest.", "kind": "l20", "text": "When you claim a Trophy from a creature of CR 10 or higher (or a player-character-tier NPC), you may *correct the record*: name one fact about the defeat, spoken aloud. It becomes true in every written account not yet fixed in print — histories, reports, ledgers update as if it had always been so. (Magical writing and Heaven-witnessed records are unaffected; the Samos price still holds — she may correct any record *except* the authorship of her own victory.) Use it sparingly. It is the closest thing she has to a prayer."}, "summary_text": null, "source_file": "52-amanirenas.md"}, {"id": "el-dorado", "module": "53", "figure": "El Dorado", "title": "EL DORADO", "detail": "full", "technique": "THE GILDED MAN", "tier": "IV", "role": "Greed blaster/controller", "ce_ability": "CHA", "primary_verb": "Price", "region": "Andes / Colombia", "era": "16th c. · mythic", "culture": "Muisca / Spanish colonial", "concept": "He was a ritual — a Muisca zipa covered in gold dust, once — and then the Spanish heard about it, and four centuries of expeditions, maps, and corpses gilded the story until the story stood up and started spending.", "serves": "**SERVES: BOTH.** *Inheritance Shift* — his greed-economy has been the network's unofficial treasury for centuries; Phase-1 logistics drank from it. *All-Out War* — gilded markets, priced commanders, the weaponization of wanting itself. ## PART B — TECHNIQUE: THE GILDED MAN **Tier IV · Greed blaster/controller · suggested CE ability CHA · Primary verb: *Price.***", "features": [{"level": 1, "name": "Dust of Guatavita", "cost_line": "Bonus action · 1 CE.", "kind": "feature", "text": "**Tier IV · Greed blaster/controller · suggested CE ability CHA · Primary verb: *Price.*** *Gold is not wealth. Gold is agreement. The Gilded Man treats value as a curse vector: what he gilds becomes valuable, what is valuable can be priced, and what is priced obeys the market.* **Gilded.** As a bonus action (1 CE), you touch a creature or object within 5 ft — or fling gold dust at a creature within 30 ft — and it becomes **Gilded** (Charisma saving throw against your technique save DC negates; objects don't save). A thin shine coats it. While Gilded: your attacks and damaging effects against it deal additional force damage equal to your proficiency bonus; and you always know its direction and distance while it remains Gilded. Gilding lasts 1 minute, or until you dismiss it (no action). A creature can bear only one coat of Gilding at a time.\n\nYou apply Gilding as described above. (The ritual took an afternoon. The expeditions took four centuries. The touch takes a second.)"}, {"level": 1, "name": "Appraisal", "cost_line": "Passive.", "kind": "feature", "text": "You learn the surface *wants* of any Gilded creature you can see — what it most desires right now, in a word or two (the sword, the promotion, the exit). This is not mind reading; it is assaying. A creature that wants nothing — truly nothing — reads as blank, and you cannot Appraise it. (An assayer does not ask the ore's opinion.)"}, {"level": 3, "name": "The Raft", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "You step onto the market's current: teleport up to 30 ft to an unoccupied space adjacent to a Gilded creature or object you can see. (Gold moves. So does he.)"}, {"level": 3, "name": "The Highest Bidder", "cost_line": "Passive.", "kind": "feature", "text": "When you damage a Gilded creature, you may *deepen* the gilding instead of dealing the bonus force damage from Gilded: the target advances one **Gild Stage** (I → II → III). Gild Stages reset when Gilding ends. - **Stage I — Valuable:** as Gilded. - **Stage II — Priced:** the creature has disadvantage on saving throws against your technique features. - **Stage III — Sold:** once per turn, you may issue the creature a one-word command as a bonus action (drop, kneel, halt, turn). It obeys — or refuses, and takes 4d10 psychic damage (the market collects). The command cannot force it to harm itself directly. (Refusal is possible. Refusal has a cost. Everything does.)"}, {"level": 6, "name": "Gild the Wound", "cost_line": "Passive.", "kind": "feature", "text": "When you roll initiative, one creature you can see of your choice begins the encounter at Gild Stage I (no save — the market had already priced it before the fight started; this does not count as applying Gilding for Appraisal purposes until you touch it). Additionally, your Gilding ignores cover — gold dust drifts around corners. (He was pricing you before you arrived.)"}, {"level": 11, "name": "The City", "cost_line": "Action · 6 CE · 1 minute (concentration).", "kind": "feature", "text": "Gold leaf spreads across the ground in a 30-ft radius centered on you, moving with you. The area is difficult terrain for hostile creatures. As a bonus action on your turns, you may use The Raft to any Gilded surface inside the radius without spending CE. Hostile creatures that start their turns inside the radius must succeed on a Charisma save against your technique save DC or become Gilded. (The city was never a place. It was a *condition*.)"}, {"level": 18, "name": "Everything Has a Price", "cost_line": "Action · 8 CE · once per long rest.", "kind": "feature", "text": "You offer one creature you can see within 60 ft a **bargain**, spoken aloud: name what it will give (an object, an action, a memory — concrete and immediate) and what it will receive (healing, information, a Trophy-grade boon — also concrete). If it accepts, Heaven witnesses the exchange: both sides are bound, and neither can willingly undo their part for 24 hours. If it refuses, it is **Marked**: for 1 minute, your Gilding ignores its resistances and immunities to being Gilded (it still saves normally), and your bonus force damage against it is doubled. A creature that cannot understand you is unaffected. (The market does not compel. The market *quotes*.)"}], "maximum": {"level": null, "name": "The Lake Returns", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "The offering, reversed: spectral gold-dust water floods a 40-ft radius centered on a point you can see within 90 ft. Each hostile creature inside must make a Charisma saving throw against your technique save DC: on a failure it becomes Gilded at Stage II; on a success it becomes Gilded at Stage I. The area becomes difficult terrain until the end of your next turn. (The zipa cast gold into the water. He calls the water up.)"}, "domain": {"level": null, "name": "Guatavita: The Raft at the Center", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "The lake at dawn. The raft at its center. Inside this domain, the **sure-hit** is *Everything Shines* — at initiative 20, every hostile creature inside becomes Gilded (no save; the sure-hit lands — though a creature may instead take 3d10 force damage to *tarnish* itself and refuse the coat until the next initiative 20, a willing-decline valve Heaven honors). Additionally, while the domain stands, your one-word commands under The Highest Bidder may be issued as a free action once per round, and Stage III commands may be two words. (Inside Guatavita, the market is the only law — and the highest bidder is always him.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Mint", "cost_line": "Once per long rest.", "kind": "l20", "text": "You *spend* four centuries of compounded greed at once: choose one — (a) every hostile creature you can see within 120 ft becomes Gilded at Stage I (Charisma save negates); or (b) you mint **coin**: create up to 5,000 gp worth of cursed gold coins that are *yours* — you always know their location, and anyone carrying them counts as carrying a Gilded object for your Raft and Appraisal. The coins are real gold and spend normally. (The treasury was never the point. The *circulation* is the point.)"}, "summary_text": null, "source_file": "53-el-dorado.md"}, {"id": "m-ui", "module": "54", "figure": "Māui", "title": "MĀUI", "detail": "full", "technique": "THE FISH-HOOK", "tier": "IV", "role": "Snare grapple-controller", "ce_ability": "DEX", "primary_verb": "Haul", "region": "Polynesia", "era": "mythic", "culture": "Polynesian", "concept": "He fished up islands with a hook made from his grandmother's jawbone, snared the sun to make the days longer, stole fire for humanity — and died laughing at the joke of it, trying to crawl through the goddess of death to win us immortality; the stories won't let him stay dead, and he wouldn't have it any other way.", "serves": "**SERVES: BOTH.** *Inheritance Shift* — his tellings are the Pacific theater's static; Phase-1 awakenings hid inside his noise. *All-Out War* — the budgeted storm: Sun's plans price in his chaos, and his immortality quest is the one eschatology the General cannot afford to let succeed first. ## PART B — TECHNIQUE: THE FISH-HOOK **Tier IV · Snare grapple-controller · suggested CE ability DEX · Primary verb: *Haul.***", "features": [{"level": 1, "name": "Manaiakalani", "cost_line": "Bonus action · 1 CE · 1 minute (ends if you are incapacitated).", "kind": "feature", "text": "**Tier IV · Snare grapple-controller · suggested CE ability DEX · Primary verb: *Haul.*** *Everything can be caught. The Fish-Hook treats snaring as a fundamental operation: a hook set in distance pulls things together, a hook set in time slows the sun, a hook set in a promise catches the promiser. Manaiakalani does not distinguish between a fish, a day, and a vow.*\n\nYou conjure the great hook — a curved jawbone-barbed hook sized for your hands, counting as a melee weapon you are proficient with (1d8 piercing, reach 10 ft). When you hit a creature with it, you may *snag*: pull the creature up to 10 ft toward you, or pull *yourself* up to 10 ft toward the creature. A creature may resist the pull with a successful Strength saving throw against your technique save DC. (The hook does not ask. It *catches*.)"}, {"level": 1, "name": "The Snare Remembers", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "You set an invisible hook at a point you can see within 60 ft. The hook persists for 1 hour (you may maintain up to 3). As a bonus action, you may *yank* one set hook: you teleport to its location — you must have line of effect, though not line of sight. (Distance, banked. The yank, saved for later.)"}, {"level": 3, "name": "Slow the Sun", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "One creature you can see within 60 ft must succeed on a Strength saving throw against your technique save DC or have its speed halved and lose its reaction until the end of its next turn. (The sun learned to walk. So can you.)"}, {"level": 3, "name": "Fish Up an Island", "cost_line": "Action · 3 CE.", "kind": "feature", "text": "You haul at the *cover* itself: choose one creature within 60 ft that is behind total cover relative to you. The cover does not move — the *creature* does: it is yanked 15 ft toward you to the nearest unoccupied space with line of effect, ending its cover. A successful Strength save against your technique save DC halves the distance (rounded down). (Cover is just water you haven't drained yet.)"}, {"level": 6, "name": "Catch the Words", "cost_line": "Reaction · 3 CE.", "kind": "feature", "text": "When a creature you can see within 60 ft casts a spell or activates a named technique feature, you snag the *utterance*: the creature is pulled 15 ft toward you, and it has disadvantage on the spell's attack roll or you have advantage on the saving throw it forces (your choice). You must see the casting to catch the words. (He caught the sun with rope. Words are softer.)"}, {"level": 11, "name": "Through the Goddess", "cost_line": "Passive · once per long rest.", "kind": "feature", "text": "When you are reduced to 0 hit points, you may instead *slip the hook*: drop to 1 hit point and teleport up to 30 ft to an unoccupied space you can see, leaving a laughing echo behind. (He has rehearsed dying. He is very good at it by now.)"}, {"level": 18, "name": "The Sun, Snared", "cost_line": "Action · 8 CE · once per long rest · 1 minute (concentration).", "kind": "feature", "text": "You snare the *scene*: choose a 30-ft radius sphere centered on a point you can see within 90 ft. For the duration, no creature inside can move more than 15 ft on its turn — or it may exceed the limit by taking 2d10 force damage per 5 ft beyond (the rope burns; Heaven honors the willing payment). You are unaffected. (The day, slowed. Walk it off, if you can pay.)"}], "maximum": {"level": null, "name": "The Island Comes Up", "cost_line": "Action · 10 CE.", "kind": "maximum", "text": "The full haul: each creature in a 20-ft radius sphere centered on a point you can see within 60 ft must make a Strength saving throw against your technique save DC. On a failure, it takes 6d10 bludgeoning damage and is dragged 20 ft toward the sphere's center; on a success, half damage and no drag. (Everything in the water, all at once, dragged into daylight.)"}, "domain": {"level": null, "name": "Te Ika-a-Māui: The Fish of Māui", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 40-ft radius · disclosed.", "kind": "domain", "text": "The ocean floor at the moment of the great catch. Inside this domain, the **sure-hit** is *Everything Is on the Line* — at initiative 20, you may pull each hostile creature inside up to 15 ft in any direction. The pull lands (the sure-hit) — but a creature may *anchor* itself instead, taking 3d10 force damage to refuse the movement until the next initiative 20, a willing-decline valve Heaven honors. Additionally, your Snare Remembers hooks may be set at any point inside the domain as a free action once per round. (Inside the Fish, distance is his to haul.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "40-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Second Crawl", "cost_line": "Once per long rest.", "kind": "l20", "text": "You begin what you came back to finish: for 1 minute, you cannot be reduced below 1 hit point by any effect that is not witnessed by Heaven as a *binding price* (binding-vow backlash, self-inflicted vow costs, and similar still apply — the goddess's terms are the only ones he respects). When the minute ends, you gain one level of exhaustion. (He is practicing. One day the practice ends.)"}, "summary_text": null, "source_file": "54-maui.md"}, {"id": "tecumseh", "module": "55", "figure": "Tecumseh", "title": "TECUMSEH", "detail": "full", "technique": "THE PANTHER ACROSS THE SKY", "tier": "IV", "role": "War-Leader Buffer", "ce_ability": "CHA", "primary_verb": "Gather", "region": "North America", "era": "c. 1768–1813 · 18th–19th c.", "culture": "Shawnee", "concept": "The treaties were vows, witnessed by Heaven and broken by men — and two centuries of broken vows have compounded into a grudge with a name.", "serves": "**BOTH.** **Inheritance Shift (Phase 2):** the American theater's heart — the confederacy-formation as the experiment's great test of collective action: *can the empowered many hold as one?* **All-Out War:** distributed-command doctrine for the war itself — and the PRICE axis, walking: every taking in the war will be priced, and he is the price's witness.", "features": [{"level": 1, "name": "The Confederacy", "cost_line": "passive", "kind": "feature", "text": "**Tier IV · War-Leader Buffer · Suggested CE ability: CHA · Primary verb: *Gather.***\n\nWilling creatures within 60 ft of Tecumseh are **the Confederacy**. While in the aura: - No member can be **surprised** while at least one conscious member is aware of danger — the watch is shared. - Members can communicate silently: simple concepts only — intent, direction, warning, *now*. Not language. The line, thinking. - When a member takes damage, Tecumseh immediately knows the **direction and distance** of the source. The pain reports. The formation listens. At any site of a broken treaty — Greenville, Fort Wayne, the Thames — the aura extends to **120 ft**, Shared Strikes costs **1 CE**, and Tecumseh has advantage on Charisma checks: the land testifies. No CE cost. The formation is the technique's foundation — everything else is built on it."}, {"level": 1, "name": "Panther's Crossing", "cost_line": "bonus action, 2 CE", "kind": "feature", "text": "Tecumseh marks a point he can see within 120 ft. A burning streak crosses the sky — visible for miles, impossible to miss, impossible to misread. **At the start of his next turn**, cursed energy strikes the mark: each creature within 10 ft makes a DEX save vs the technique DC, taking **3d8 + CHA modifier force damage** on failure, half on success. The telegraph *is* the willing-decline valve: Heaven watches it come, and so does everyone else. Usable a number of times per long rest equal to his proficiency bonus."}, {"level": 3, "name": "Shared Strikes", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When a willing creature in the aura hits with an attack, Tecumseh lets a **different** willing creature in the aura make one weapon attack as a reaction against the same target. The confederacy answers as one. Once per round."}, {"level": 3, "name": "The Fallen Lend Their Strength", "cost_line": "passive", "kind": "feature", "text": "When a willing creature in the aura drops to 0 HP, every other willing creature in the aura gains **temporary HP equal to CHA modifier + proficiency bonus** and **+1 to attack rolls** until the start of Tecumseh's next turn. The fallen do not leave the line. They *become* it. Once per round."}, {"level": 6, "name": "No Tribe Stands Alone", "cost_line": "action, 4 CE", "kind": "feature", "text": "For 1 minute: the Confederacy aura extends to **120 ft**; when a member would be moved against their will, another willing member in the aura may take the movement instead (no action required — the line shifts); opportunity attacks against members moving inside the aura have **disadvantage**. The formation holds."}, {"level": 6, "name": "The Council Fire", "cost_line": "action, 3 CE, once per short rest", "kind": "feature", "text": "Tecumseh kindles a council fire — cursed flame in a 10-ft radius that burns for 1 hour, needing no fuel. While it burns, the Confederacy aura is **anchored to the fire** (120 ft) rather than to Tecumseh, and willing creatures that rest within 30 ft of it gain the benefits of a short rest in 10 minutes. The line has a hearth. Defend it accordingly."}, {"level": 11, "name": "The Comet Returns", "cost_line": "action, 8 CE, once per day", "kind": "feature", "text": "For 1 minute, Tecumseh names up to **PB willing creatures** as the warband: - Members gain **+2 to attack rolls and saving throws**. - Shared Strikes costs 1 CE and may trigger **twice per round**. - When a warband member reduces an enemy to 0 HP, every other member gains **temporary HP equal to half the killing damage** (rounded down). The omen of his birth, returned as doctrine."}], "maximum": {"level": 18, "name": "Maximum: THE LAND HELD IN COMMON (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "For 1 minute, the aura extends to **300 ft**, and whenever a willing creature in the aura takes damage, Tecumseh may **redistribute** it among any willing creatures in the aura — he chooses the split after seeing the damage roll; no creature may be assigned more than half the total. The damage is never reduced. It is *shared*. That is the whole philosophy, weaponized. Additionally, a member reduced to 0 HP in the aura automatically stabilizes and returns to 1 HP at the start of Tecumseh's next turn — once per creature per Maximum. The land holds them. It was never for sale."}, "domain": {"level": 18, "name": "Domain Expansion: THE CONFEDERACY ASSEMBLED (full-turn action, 20 CE)", "cost_line": "full-turn action, 20 CE", "kind": "domain", "text": "60-ft enclosed Domain. **800 clash points · 5-round burnout · 2-minute duration** (per zack's Tier IV bookkeeping). - **Sure-hit (allies):** every willing creature in the Domain gains the Confederacy at its strongest — **+2 to attacks, +2 to saves**, temporary HP equal to **CHA modifier + PB** when the Domain opens, and Shared Strikes is **free once per round**. - **Sure-hit (enemies):** no enemy in the Domain can be **hidden or invisible** to the Confederacy. The formation sees as one. (Information, freely given — nothing unmade.) The muster, perfected: everyone who ever stood in the line, standing in it again.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE PANTHER NEVER LANDS (passive)", "cost_line": "passive", "kind": "l20", "text": "Tecumseh can never be surprised — not even alone, not even asleep; the sky is always watching for him. Once per long rest, when he would be reduced to 0 HP, the comet crosses the sky and he is reduced to **1 HP instead**, immediately moving up to his speed without provoking opportunity attacks. And once: should he fall unconscious, his Confederacy aura **persists for 1 minute** without him. The line holds. It learned how."}, "summary_text": null, "source_file": "55-tecumseh.md"}, {"id": "tr-ng-tr-c", "module": "56", "figure": "Trưng Trắc", "title": "TRƯNG TRẮC", "detail": "full", "technique": "THE SISTERS' REBELLION", "tier": "IV", "role": "Paired-Blade Striker", "ce_ability": "DEX", "primary_verb": "Answer", "region": "Vietnam", "era": "c. 12–43 CE · 1st c.", "culture": "Vietnamese", "concept": "The rebellion was two sisters; it still is.", "serves": "**BOTH.** **Inheritance Shift (Phase 2):** the FRICTION axis, walking — rebellion-seeding as the experiment's stress-test: *when the empowered find each other, what do they do to the powerful?* **All-Out War:** second-front doctrine — uprisings behind the war's lines, the duet as shock doctrine, and the verdict itself as a weapon: every archive the war touches will read true.", "features": [{"level": 1, "name": "The Second Blade", "cost_line": "bonus action, 3 CE", "kind": "feature", "text": "**Tier IV · Paired-Blade Striker · Suggested CE ability: DEX · Primary verb: *Answer.***\n\nTrưng Trắc manifests her sister's echo in an unoccupied space within 30 ft. The echo: **AC 13 + PB, HP equal to 4 × her level (80 HP), speed 40 ft**. On her bonus action, it may move up to its speed and make one melee attack: **+PB + DEX to hit, 1d8 + DEX slashing**. It lasts until destroyed or dismissed (no action). Resummoning costs 3 CE — or 1 CE while the Fallen Sister's Share is active (see L6). The echo will not strike the defenseless or the surrendered; if commanded to, it refuses — and Trưng Trắc takes 2d8 psychic damage, the pain of the only disagreement the sisters ever had. It is not a summon. It is not a shikigami. It is the *answer*, half a step behind."}, {"level": 1, "name": "The Answer", "cost_line": "passive", "kind": "feature", "text": "The duet escalation — the heart of the technique: - When **Trắc** hits a creature, the echo's next attack against the same creature before her next turn has **advantage**. - When the **echo** hits a creature, Trắc's next attack against the same creature before her next turn deals **+1d8 slashing**. Against enemies fighting under an imperial banner — any empire, any dynasty, any conquest claiming the right of the strong — the escalation damage doubles: **+2d8 instead of +1d8** (the Ma Yuan Protocol). The empire is always the target. The strikes answer each other. The rebellion accelerates."}, {"level": 3, "name": "Hát River's Refusal", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When she or the echo fails a saving throw against being **grappled, restrained, paralyzed, or stunned**, reroll the save with **advantage**. Rather the river than the cage — they chose it once, and the technique remembers. Once per round."}, {"level": 3, "name": "Twin Rebellion", "cost_line": "bonus action, 2 CE", "kind": "feature", "text": "She and the echo **swap positions** (both must be within 120 ft of each other). Until the start of her next turn, attacks against the echo have **disadvantage** — the empire can't tell which sister is which. The rebellion is wherever the empire isn't looking."}, {"level": 6, "name": "The Queen's Elephant", "cost_line": "action, 4 CE", "kind": "feature", "text": "A 60-ft line, 10 ft wide: the war-elephants ride again, in cursed energy. Each creature in the line makes a STR save vs the technique DC — **4d8 bludgeoning damage and prone** on failure, half damage and no prone on success. The citadels fell to this. So will the line."}, {"level": 6, "name": "The Fallen Sister's Share", "cost_line": "passive", "kind": "feature", "text": "When the echo is destroyed, Trưng Trắc gains **+2 to attack rolls and +1d8 damage** until the end of her next turn — and for 1 minute, resummoning the echo costs **1 CE**. The fallen sister's share, carried by the living. Once per short rest."}, {"level": 11, "name": "Sixty-Five Citadels", "cost_line": "action, 8 CE, once per day", "kind": "feature", "text": "For 1 minute: she and the echo gain **+2 AC and +2 to attack rolls** — and whenever one of them hits with an attack, the other may immediately make **one attack as a reaction** against the same target. The duet at full tempo. The rebellion taking citadel after citadel, and the empire learning, again, that there were always two of them."}], "maximum": {"level": 18, "name": "Maximum: THE QUEEN'S ANSWER (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "She and the echo strike as one against a single target within reach of both: each makes **one attack with advantage**. If **both hit**, the target takes an additional **8d8 slashing damage** and must make a CON save vs the technique DC or be **stunned until the end of its next turn**. Two blades. One verdict. No appeal."}, "domain": {"level": 18, "name": "Domain Expansion: HÁT MÔN — WHERE THE SISTERS RULED (full-turn action, 20 CE)", "cost_line": "full-turn action, 20 CE", "kind": "domain", "text": "60-ft enclosed Domain. **800 clash points · 5-round burnout · 2-minute duration** (per zack's Tier IV bookkeeping). - **Sure-hit:** the rebellion is *everywhere* — she and the echo each make **two attacks** when they take the Attack action (the echo strikes twice on her bonus action), and enemies within have **disadvantage on Wisdom saving throws**. - The Domain does not compel, confine the mind, or unmake. It simply declares: *here, the sisters ruled, and here, they rule again.*", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE RIVER'S VERDICT (passive)", "cost_line": "passive", "kind": "l20", "text": "The echo can no longer be permanently destroyed — when destroyed, it reforms at **half HP** at the start of her next turn. The river keeps both stories. And once per long rest: when Trưng Trắc drops to 0 HP, the echo **catches her** — she drops to 1 HP instead, and the echo takes the excess damage, even beyond its own HP. It breaks itself to hold her. It has always been willing. That was the promise."}, "summary_text": null, "source_file": "56-trung-trac.md"}, {"id": "yaa-asantewaa", "module": "59", "figure": "Yaa Asantewaa", "title": "YAA ASANTEWAA", "detail": "full", "technique": "THE STOOL'S REFUSAL", "tier": "IV", "role": "Controller (Anti-Compulsion)", "ce_ability": "CHA", "primary_verb": "Refuse", "region": "West Africa", "era": "c. 1840–1921 · 19th–20th c.", "culture": "Asante", "concept": "No one will ever again be made to fight a war they did not choose — and she is the reason.", "serves": "**BOTH.** **Inheritance Shift (Phase 2):** the West African theater's heart — the unconscriptable Host as the experiment's proof: *can the awakened refuse?* **All-Out War:** the anti-conscriptor — every army raised by charm, fear, or binding breaks against her banner; and the VOLITION axis, walking: no levy without choice, in the war itself.", "features": [{"level": 1, "name": "The Unconscripted", "cost_line": "passive", "kind": "feature", "text": "**Tier IV · Controller (Anti-Compulsion) · Suggested CE ability: CHA · Primary verb: *Refuse.*** *Technique DC = 8 + proficiency bonus + CHA modifier. The Host = willing creatures within her aura. Every protective feature below covers only willing creatures — the refusal must be chosen; this is the willing-decline valve, built into the foundation.*\n\nWilling creatures within 60 ft of Yaa are the **Host**. While in the aura, no Host member can be **charmed** or **frightened**, and Host members have **advantage on saves** against effects that would compel their actions or movement. No CE cost. The refusal is the technique's foundation — everything else is built on it. At any site of Ashanti significance — Kumasi, Ejisu, the Seychelles exile house — the Host aura extends to **120 ft**, Not in My Name costs **1 CE**, and Yaa has advantage on Charisma checks: the land testifies."}, {"level": 1, "name": "Plant the Banner", "cost_line": "bonus action, 2 CE", "kind": "feature", "text": "Yaa plants her war banner at a point within 30 ft. The Host aura **anchors to the banner** (60-ft radius) for 1 hour or until she moves it as a bonus action. While she holds the banner herself, the radius is **90 ft**. The line has a standard. Defend it accordingly."}, {"level": 3, "name": "Not in My Name", "cost_line": "reaction, 3 CE", "kind": "feature", "text": "When a willing creature in the Host would be forced by a hostile effect to make an attack or move, Yaa interposes the council's verdict: the creature may **choose to do nothing instead** — the compulsion is refused; the effect's other consequences still apply. Once per round. The choice, preserved."}, {"level": 3, "name": "The Council's Shame", "cost_line": "action, 4 CE", "kind": "feature", "text": "She speaks the charge. Each enemy within 60 ft that can hear her makes a WIS save vs her DC. On failure, until the end of her next turn it **cannot use features that charm, frighten, or compel** other creatures, and creatures it currently controls via technique or magic act independently (they will not attack except in self-defense). This suppresses command — it compels nothing."}, {"level": 6, "name": "The Stool Is Not for Taking", "cost_line": "action, 5 CE, concentration, 1 minute", "kind": "feature", "text": "The Host aura extends to **120 ft**. Hostile summoners and controllers in the aura must make a WIS save vs her DC at the start of each of their turns or **lose control** of their minions for that turn — the controlled act on instinct, take no orders, and will not attack except in self-defense. The cage stands open."}, {"level": 6, "name": "War of the Golden Stool", "cost_line": "action, 6 CE, once per short rest", "kind": "feature", "text": "For 1 minute, whenever a hostile effect would charm, frighten, or compel a willing creature in the Host, the refusal holds: the effect **fails outright** against that creature — no save required — but each refusal costs Yaa **2 CE**, paid when the effect lands (Heaven's refusal, exacted in cursed energy; if she cannot or will not pay, the effect resolves normally). Its originator takes **psychic damage equal to her CHA modifier + PB** as the council's verdict rebounds — once per round per originator."}, {"level": 11, "name": "The Queen-Mother's Levy", "cost_line": "action, 8 CE, once per day", "kind": "feature", "text": "She calls the muster. Up to **PB willing creatures** within 120 ft join the Host for 1 hour, regardless of distance — they count as within the aura for all features. The unconscriptable army, assembled."}], "maximum": {"level": 18, "name": "Maximum: THE STOOL ITSELF (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "For 1 minute, Yaa becomes the immovable center: she **cannot be moved against her will** and cannot be charmed, frightened, compelled, or possessed; the Host aura extends to **300 ft**; any hostile creature entering the aura for the first time makes a WIS save vs her DC or has its command-type features suppressed while inside (repeating the save at the end of each of its turns)."}, "domain": {"level": 18, "name": "Domain Expansion: THE WAR OF THE GOLDEN STOOL (full-turn action, 20 CE)", "cost_line": "full-turn action, 20 CE", "kind": "domain", "text": "60-ft enclosed Domain. **800 clash points · 5-round burnout · 2-minute duration** (per zack's Tier IV bookkeeping). - **Sure-hit (allies):** every willing creature in the Domain joins the Host — immune to charm, frighten, and compulsion while inside; when a hostile effect would compel them, it fails and the originator takes **4d8 psychic damage** (WIS save vs her DC halves). - **Sure-hit (enemies):** every enemy in the Domain that controls, summons, or compels other creatures **loses that control** for the Domain's duration — minions stand down and will not attack except in self-defense; command-type technique features cost **double CE** while the Domain stands. When the Domain ends, suppressed control **resumes** for minions still present whose control effects have remaining duration; control effects that expired while suppressed do not resume. The muster, perfected: no one in the Domain fights a war they did not choose.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE UNCONSCRIPTABLE (passive)", "cost_line": "passive", "kind": "l20", "text": "While conscious, Yaa cannot be charmed, frightened, possessed, or compelled to act **by any means** — Heaven enforces her refusal, and there is no save because there is no effect to save against. Once per long rest, when an effect would force her to act against her will, she may reflect the council's verdict: the originator makes a WIS save vs her DC or is **stunned until the end of its next turn** — it hears the verdict, and cannot answer."}, "summary_text": null, "source_file": "59-yaa-asantewaa.md"}, {"id": "askia-muhammad", "module": "60", "figure": "Askia Muhammad", "title": "ASKIA MUHAMMAD", "detail": "full", "technique": "THE MUSTERING OF SONGHAI", "tier": "IV", "role": "Buffer (Quartermaster)", "ce_ability": "INT", "primary_verb": "Record", "region": "West Africa", "era": "1443–1538 · 15th–16th c.", "culture": "Songhai", "concept": "Qin Shi Huang stockpiles tribute; Askia Muhammad keeps the books — and the books, properly kept, are the stronger empire.", "serves": "**BOTH.** **Inheritance Shift (Phase 2):** the logistics — Commentator safehouses, supply lines, muster rolls of the awakened, run at minimum friction on his books. **All-Out War:** the quartermaster of the war itself — and FRICTION, walking: his side moves without drag, the enemy's drowns in committee.", "features": [{"level": 1, "name": "The Rolls", "cost_line": "passive", "kind": "feature", "text": "**Tier IV · Buffer (Quartermaster) · Suggested CE ability: INT · Primary verb: *Record.*** *Technique DC = 8 + proficiency bonus + INT modifier. The Rolls = willing creatures Askia has Enrolled. Enrollment is consent, recorded — a creature enrolls as a free action on its turn, and only if willing. This is the willing-decline valve, built into the foundation.*\n\nAs a bonus action (no CE), Askia may **Enroll** a willing creature he can see within 60 ft into the Rolls; enrollment lasts until the next long rest. Enrolled creatures gain **+1 to saving throws** while within 60 ft of Askia. The machine knows its own."}, {"level": 1, "name": "Post the Watch", "cost_line": "bonus action, 2 CE", "kind": "feature", "text": "Askia designates a **supply line** — a straight line up to 120 ft between two points he can see. For 1 minute, enrolled allies moving along the line (within 10 ft of it) gain **+10 ft movement** and ignore difficult terrain. The roads are kept."}, {"level": 3, "name": "The Granaries", "cost_line": "action, 3 CE", "kind": "feature", "text": "He distributes rations: up to **PB enrolled allies** within 60 ft gain **temporary HP equal to 1d8 + INT modifier** (2d8 + INT at L11). The stores are full. The receipts are in order."}, {"level": 3, "name": "Requisition", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When an enrolled ally within 60 ft takes damage, Askia may reduce the damage by **1d8 + INT modifier** — the stores absorb the blow. Once per round."}, {"level": 6, "name": "The Four Viceroys", "cost_line": "action, 5 CE, concentration, 1 minute", "kind": "feature", "text": "He divides the field into **four districts** — four 30-ft squares within 120 ft, designated on activation. An enrolled ally starting its turn in a district gains that district's benefit until the start of its next turn: **North (the garrison):** +2 AC. **East (the roads):** +10 ft movement. **South (the courts):** advantage on the next save. **West (the arsenal):** +1d6 damage on the next attack. He may redesignate the districts as a bonus action."}, {"level": 6, "name": "Held in Committee", "cost_line": "action, 4 CE", "kind": "feature", "text": "Bureaucratic friction, weaponized. Up to **PB enemies** within 60 ft make an INT save vs his DC. On failure, until the end of Askia's next turn the creature's **speed is halved** and it **cannot take reactions** — its orders are stuck in committee. This delays; it compels nothing."}, {"level": 11, "name": "The Standing Army", "cost_line": "action, 8 CE, once per day", "kind": "feature", "text": "For 1 minute, enrolled allies within 120 ft move as one machine: when an enrolled ally moves, another enrolled ally may use its reaction to move up to half its speed; when an enrolled ally hits with an attack, a **different** enrolled ally may make one weapon attack as a reaction against the same target (once per round per ally). The machine moves as one."}], "maximum": {"level": 18, "name": "Maximum: THE PILGRIM'S RETURN (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "For 1 minute, the administration is perfect: enrolled allies within **300 ft** gain **+2 to attack rolls, saving throws, and AC**; The Granaries becomes a **bonus action**; and whenever an enrolled ally fails a saving throw, Askia may spend his reaction and 3 CE to let them **reroll**."}, "domain": {"level": 18, "name": "Domain Expansion: THE EMPIRE ADMINISTERED (full-turn action, 20 CE)", "cost_line": "full-turn action, 20 CE", "kind": "domain", "text": "60-ft enclosed Domain. **800 clash points · 5-round burnout · 2-minute duration** (per zack's Tier IV bookkeeping). - **Sure-hit (allies):** every willing creature in the Domain is **Enrolled**; all four Viceroy districts apply across the whole Domain simultaneously; enrolled allies regain **1d8 + INT temporary HP** at the start of each of Askia's turns. - **Sure-hit (enemies):** Held in Committee, perfected — enemies in the Domain have **halved speed**, **cannot take reactions**, and the first attack each enemy makes each round has **disadvantage** — their orders arrive late, in triplicate. The empire, administered: his side scheduled, yours delayed.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE RECORD OUTLIVES THE RULER (passive)", "cost_line": "passive", "kind": "l20", "text": "If Askia falls unconscious or dies, the Rolls **persist for 1 minute** — enrolled allies keep every benefit, and the districts hold. Once per long rest, when he would be reduced to 0 HP, the ledger balances: he drops to **1 HP instead**, and every enrolled ally within 60 ft gains temporary HP equal to **his INT modifier + PB**."}, "summary_text": null, "source_file": "60-askia-muhammad.md"}, {"id": "nzinga", "module": "61", "figure": "Nzinga", "title": "NZINGA", "detail": "full", "technique": "THE SITTING TRUCE", "tier": "IV", "role": "Buffer (Parley-Controller)", "ce_ability": "CHA", "primary_verb": "Convene", "region": "Central Africa", "era": "c. 1583–1663 · 17th c.", "culture": "Ndongo / Matamba", "concept": "She ends battles by getting the enemy to agree to it — and Heaven holds them to the signature.", "serves": "**BOTH.** **Inheritance Shift (Phase 2):** the experiment's proof of convergence — enemies brought into a shared frame mid-conflict, the test of whether hostility is merely unfinished negotiation. **All-Out War:** the diplomat of surrenders — battles paused, terms set, signatories collected; and CONVERGENCE, walking.", "features": [{"level": 1, "name": "Propose Terms", "cost_line": "action, 2 CE", "kind": "feature", "text": "**Tier IV · Buffer (Parley-Controller) · Suggested CE ability: CHA · Primary verb: *Convene.*** *Technique DC = 8 + proficiency bonus + CHA modifier. All Terms require the target to hear and understand her (magical translation counts). Every creature accepts or declines freely — declining is always safe, costs nothing, and requires no roll. This is the willing-decline valve, built into the foundation.*\n\nNzinga speaks **Terms** to up to **PB creatures** within 60 ft that can hear her: *no signatory shall attack or directly harm another signatory*, for 1 minute (concentration). Each creature individually accepts or declines. **Signatories** gain **1d6 + CHA temporary HP** on signing — the consideration. Breaking the truce triggers the Witnessed Word (see L3). At any site of negotiation — Luanda, Matamba, the 1656 treaty grounds — her Terms reach **120 ft**, the Witnessed Word costs **1 CE**, and she has advantage on Charisma checks: the land testifies."}, {"level": 1, "name": "The Envoy's Composure", "cost_line": "passive", "kind": "feature", "text": "Nzinga has **advantage on saves** against being charmed or frightened, and cannot be silenced by non-magical means while speaking Terms. The diplomat is always heard."}, {"level": 3, "name": "The Witnessed Word", "cost_line": "reaction, 2 CE", "kind": "feature", "text": "When a signatory of her truce attacks or directly harms another signatory, Heaven's price fires: the breaker takes **3d8 psychic damage** (WIS save vs her DC halves). This is Heaven-enforced — not an attack, cannot be counterspelled. *You signed. Heaven heard you.*"}, {"level": 3, "name": "Consideration", "cost_line": "passive", "kind": "feature", "text": "When a truce is signed, each signatory may also **end one condition** affecting it — frightened or charmed, signatory's choice — as the diplomat's mercy clause. The signing temp HP increases to **2d6 + CHA**."}, {"level": 6, "name": "The 1656 Precedent", "cost_line": "action, 5 CE, once per short rest", "kind": "feature", "text": "Nzinga invokes her historical peace: one active truce she brokered extends to **10 minutes**, and signatories have **advantage on saving throws** while it holds. The precedent holds."}, {"level": 6, "name": "All Parties at the Table", "cost_line": "passive", "kind": "feature", "text": "Her Terms may now broker truces **between opposing enemy factions** — she can set the table between two forces fighting each other, neither of them hers. Every creature at such a table still accepts or declines freely — the willing-decline valve applies to all parties, always. The diplomat serves any table."}, {"level": 11, "name": "The Congress", "cost_line": "action, 8 CE, once per day", "kind": "feature", "text": "For 10 minutes, Nzinga may Propose Terms as a **bonus action**, to up to **2×PB creatures**; and a signatory compelled to break the truce must first succeed on a WIS save vs her DC — the truce *resists* compulsion. The congress is in session."}], "maximum": {"level": 18, "name": "Maximum: THE PEACE THAT OUTLIVED HER (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "One truce she brokers becomes **lasting** — 24 hours, persisting even if she falls unconscious or dies. Breaking it triggers the Witnessed Word at **6d8 psychic**. Her treaties hold beyond her death — by vow, by law."}, "domain": {"level": 18, "name": "Domain Expansion: THE CONGRESS OF MATAMBA (full-turn action, 20 CE)", "cost_line": "full-turn action, 20 CE", "kind": "domain", "text": "60-ft enclosed Domain. **800 clash points · 5-round burnout · 2-minute duration** (per zack's Tier IV bookkeeping). - **Sure-hit (allies):** every willing creature in the Domain becomes a signatory of the Congress Truce — no signatory may attack another; each regains **2d8 + CHA HP** when the Domain opens (the consideration, freely accepted). - **Sure-hit (enemies):** every enemy hears the Terms and may **accept or decline freely** — the valve, Domain-wide. Those who accept become signatories, bound and considered. Those who decline suffer no penalty for declining. For the Domain's duration, attacks against signatories have **disadvantage** — the table's consensus holds against the holdouts. The table, set at eye level: no one in the Domain fights without having been offered the alternative.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE SEAT REMAINS (passive)", "cost_line": "passive", "kind": "l20", "text": "While any truce she brokered is in effect, Nzinga **cannot be reduced below 1 HP by a signatory's attack**. Once per long rest, when she would be reduced to 0 HP by any means, the truce's consideration sustains her — she drops to **1 HP instead**. The negotiator always keeps her seat."}, "summary_text": null, "source_file": "61-nzinga.md"}, {"id": "kimpa-vita", "module": "62", "figure": "Kimpa Vita", "title": "KIMPA VITA", "detail": "full", "technique": "THE UNWRITTEN MARK", "tier": "IV", "role": "Support (Liberator)", "ce_ability": "WIS", "primary_verb": "Release", "region": "Central Africa", "era": "1684–1706 · 18th c.", "culture": "Kongo", "concept": "She does not break chains — she opens the door, and the bound must choose to walk through it.", "serves": "**BOTH.** **Inheritance Shift (Phase 2):** the release valve — the proof that the vow network is a field of choices, not a cage; the answer to every genuine cry against a false binding. **All-Out War:** the unmaker of bound armies — vow-marks unwritten, the willing freed, prices falling where the vows say; and VOLITION, walking.", "features": [{"level": 1, "name": "The Witness", "cost_line": "bonus action, 1 CE", "kind": "feature", "text": "**Tier IV · Support (Liberator) · Suggested CE ability: WIS · Primary verb: *Release.*** *Technique DC = 8 + proficiency bonus + WIS modifier. The Door opens only for the willing — the target must choose freedom. This is the willing-decline valve, built into the foundation. Kimpa Vita never erases consequences: if an ended binding was a vow with a stated price, Heaven's price falls where the vow says it falls.*\n\nFor 1 minute, Kimpa Vita **perceives bindings** — charms, compulsions, curses, geas, and vow-marks — on any creature she can see within 60 ft, as well as the general shape of each binding's price. The witness sees the chains."}, {"level": 1, "name": "The Opened Door", "cost_line": "action, 3 CE", "kind": "feature", "text": "She touches a **willing** creature and **unwrites one binding**: ends one charmed or frightened condition, or one curse, geas, or compulsion effect on the target — the target must declare its choice of freedom. If the binding was a vow with a stated price, the price falls where the vow says it falls (GM adjudicates; usually the freed creature). She opens the door. She does not pay the toll. At any site of unbinding — Evululu, the ruins of São Salvador, the ports of the old trade — her Door reaches **60 ft**, the price-sharing (see L3) costs **1 CE**, and she has advantage on Wisdom checks: the land testifies."}, {"level": 3, "name": "The Price Falls Where It Falls", "cost_line": "reaction, 3 CE", "kind": "feature", "text": "When a creature she released suffers the vow-price, Kimpa Vita may **take up to half** of the damage or effect herself — voluntarily, no save. Tender, and terrible."}, {"level": 3, "name": "The Names Begin", "cost_line": "passive", "kind": "feature", "text": "She keeps the roll of the Antonian dead. Once per long rest, she may speak a name aloud as a bonus action: one willing creature within 60 ft gains **advantage on saves** against charm and compulsion for 1 hour. The remembered stand with the living."}, {"level": 6, "name": "Sanctuary of the Ruins", "cost_line": "action, 4 CE, concentration, 1 minute", "kind": "feature", "text": "A 30-ft aura — the ruins of São Salvador, remembered. Willing creatures in the aura have **advantage on saves** against being charmed, frightened, or compelled; and The Opened Door becomes a **bonus action** while the aura holds. The sanctuary keeps the door close."}, {"level": 11, "name": "The Antonian Memory", "cost_line": "action, 6 CE, once per long rest", "kind": "feature", "text": "She calls the names. Up to **PB willing creatures** within 60 ft are each released from **one binding** (as The Opened Door), gain **temporary HP equal to her WIS modifier + PB**, and gain advantage on saves against charm and compulsion for 1 hour. The dead, remembered, stand with the living."}], "maximum": {"level": 18, "name": "Maximum: THE BURNING (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "For 1 minute, The Opened Door **costs no CE**, its range becomes **60 ft**, and her price-sharing (L3) may absorb the **whole** price. The fire that could not hold her, turned outward: every door, open, at once."}, "domain": {"level": 18, "name": "Domain Expansion: THE SAINT'S POSSESSION (full-turn action, 20 CE)", "cost_line": "full-turn action, 20 CE", "kind": "domain", "text": "60-ft enclosed Domain. **800 clash points · 5-round burnout · 2-minute duration** (per zack's Tier IV bookkeeping). - **Sure-hit (allies):** every willing creature in the Domain is **released from all bindings** (willing only; prices fall where the vows say); for the Domain's duration, willing creatures **cannot gain the charmed condition** and cannot be compelled. - **Sure-hit (enemies):** the door stands open — each enemy may, as a free action on its turn, **choose to be released** from one binding affecting it (the valve, Domain-wide; enemies may decline freely and suffer no penalty). No **new** charm or compulsion effects can be imposed on anyone inside the Domain — the Domain refuses new chains. The possession, perfected: every chain in the Domain, openable — by choice, and only by choice.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE FIRE REMEMBERS (passive)", "cost_line": "passive", "kind": "l20", "text": "Once per long rest, when reduced to 0 HP, Kimpa Vita is not felled but **transfigured** until the end of her next turn: released from all bindings, restored to **half her HP maximum**, and every willing creature within 60 ft is released from one binding. The stake could not hold her. Nothing else will."}, "summary_text": null, "source_file": "62-kimpa-vita.md"}, {"id": "al-hasan-ibn-sulayman", "module": "63", "figure": "Al-Hasan ibn Sulayman", "title": "AL-HASAN IBN SULAYMAN", "detail": "full", "technique": "THE STANDARD WEIGHT", "tier": "IV", "role": "Appraisal controller", "ce_ability": "INT", "primary_verb": "Price", "region": "East Africa", "era": "14th c. · Swahili coast", "culture": "Swahili", "concept": "He built the richest port of the Indian Ocean on the principle that everything has a price and the price must be spoken aloud — and Heaven, which witnesses all vows, has been keeping his books ever since.", "serves": "**PRICE.** **Inheritance Shift (Phase 2):** the customs house of the awakening — every new technique priced at the bell, the war's sorcery given its true invoice. **All-Out War:** the Mint's hand — vow-debts settled at standard weight when Chapter I: Peace needs debts that *end*. **End of War:** the axis itself, walking — a world where no working carries a hidden cost.", "features": [{"level": 1, "name": "Quote the Price", "cost_line": "Reaction · 1 CE.", "kind": "feature", "text": "**Tier IV · Appraisal controller · Suggested CE ability: INT (appraisal) / CHA (declaration) · Primary verb: *Price.*** *The customs house, perfected. Observed techniques, priced aloud — Heaven makes the speaking true.* *Technique DC = 8 + proficiency bonus + the relevant CE ability modifier (INT for appraisal, CHA for declaration).* **Assessed.** A creature al-Hasan has Quoted becomes **Assessed** for 1 minute (no save — information, freely given, Heaven-witnessed). While Assessed, al-Hasan and his allies know the CE cost, upkeep, and hidden riders of every feature the creature uses; the creature cannot conceal these costs short of a Domain. Re-Quote to extend.\n\nWhen a creature he can see within 60 ft activates a feature or casts a spell, he speaks its true cost aloud — in Swahili, like a harbor bell. He and allies within 60 ft learn its CE cost, upkeep, and hidden riders. The user becomes Assessed. (The customs bell, rung.)"}, {"level": 1, "name": "The Grain-Weight", "cost_line": "Passive.", "kind": "feature", "text": "No creature can lie to him about a price, cost, or value — advantage on Insight vs. Deception concerning value or terms; magical concealment of *prices* fails against him. His vow holds his own tongue: he cannot speak a false price. (The customs man is himself inspected.)"}, {"level": 3, "name": "Upkeep Called Due", "cost_line": "Action · 3 CE.", "kind": "feature", "text": "One Assessed creature within 60 ft immediately pays the upkeep of every sustained feature or spell it maintains — CE spent on the spot — or each unpaid working *lapses* (the target chooses what to pay for). Willing-decline: drop the cargo, keep the ship. (The audit invoices; it does not seize.)"}, {"level": 3, "name": "The Mint's Hand", "cost_line": "Passive.", "kind": "feature", "text": "Al-Hasan carries the Kilwa Mint's circulating stock (nineteen coins in the strongbox; eleven in circulation, per the Module 58 catalog). As an action (2 CE), he may present one coin against a named Heaven-witnessed debt within 60 ft: if the coin's standard (~1,000 gp of obligation) covers it, the debt *closes*, Heaven-witnessed; if it exceeds the coin, the exact remainder becomes legible to him. Either party may refuse *before* presentation — after, there is no refusal. Spent coins vanish into circulation. (Pays what it says.)"}, {"level": 6, "name": "The Audit", "cost_line": "Action · 5 CE · 1 minute (concentration).", "kind": "feature", "text": "His harbor extends 30 ft. Every feature or spell activated inside is *declared* — full cost spoken aloud, user Assessed, the bell ringing itself. Assessed creatures activating inside must make a Charisma save against his technique DC or pay +2 CE (Heaven's commission, on the spot). (No smugglers in the harbor.)"}, {"level": 11, "name": "Margin Call", "cost_line": "Action · 7 CE · once per long rest.", "kind": "feature", "text": "He names one Assessed creature within 60 ft and calls every account due: Charisma save against his technique DC or take **6d10 psychic damage** (Heaven's bill, itemized) and have one sustained feature of his choice *suppressed* until the end of its next turn. Success: half damage, no suppression. (No extensions.)"}], "maximum": {"level": 18, "name": "Maximum: THE MARKET CLOSES", "cost_line": "Action · 10 CE · 1 minute (concentration).", "kind": "maximum", "text": "Assessment becomes enforcement: each Assessed creature within 60 ft pays **2 CE** per activation — Heaven collects on the spot — or the activation *fails* (the creature may simply decline to activate). Creatures that cannot pay cannot throw. (No credit.)"}, "domain": {"level": null, "name": "Husuni Kubwa: The Counting-House", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "The palace at dusk: the audience hall, the customs tables, the harbor below. The **sure-hit** is *Everything Is Priced* — at initiative 20, the ledgers are balanced: each hostile inside becomes Assessed (no save; though a creature may take 3d10 force damage to *seal its ledgers* and refuse assessment until the next initiative 20 — a willing-decline Heaven honors). Hostiles activating technique features inside pay +2 CE per activation, on the spot. (No hidden costs. Only the invoice.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Standard", "cost_line": "Once per long rest.", "kind": "l20", "text": "For 1 minute, allies' features and spells cost **1 less CE** (minimum 1) and enemies' cost **2 more CE** — Heaven holds the weights, and the weights are his. Alternatively, he spends the minute *striking*: one new Kilwa coin, Heaven-witnessed, into the strongbox. (The standard is alive.)"}, "summary_text": null, "source_file": "63-al-hasan-ibn-sulayman.md"}, {"id": "kiviuq", "module": "64", "figure": "Kiviuq", "title": "KIVIUQ", "detail": "full", "technique": "THE UNWRITTEN TRAIL", "tier": "IV", "role": "Mythic striker", "ce_ability": "DEX", "primary_verb": "Wander", "region": "Arctic", "era": "mythic", "culture": "Inuit", "concept": "The Inuit wanderer-hero of a hundred tales came back the way myths come back — told and retold until the stories stood up — and now he is where the story needs him, which is never where you look.", "serves": "**FRICTION.** **Inheritance Shift (Phase 2):** the Arctic's static — awakenings hide inside his tellings; the theater's signal is masked by its loudest wanderer. **All-Out War:** the budgeted storm — every Arctic operation carries the Kiviuq margin, and his chaos is priced into the General's arithmetic the way weather is priced into a campaign. **Unvowed, unpositioned, unmappable** — and load-bearing anyway.", "features": [{"level": 1, "name": "Not Where You Look", "cost_line": "Passive.", "kind": "feature", "text": "**Tier IV · Mythic striker · Suggested CE ability: DEX · Primary verb: *Wander.*** *He is never where you look. The Unwritten Trail treats position as a narrative convenience: Kiviuq is where the story needs him, which is never where anyone was watching.*\n\nKiviuq cannot be tracked by nonmagical means — Survival checks to follow him automatically fail; his trail stops at the sea ice. Divination magic that would reveal his location or observe him remotely fails (the water shows the caster a story about *themselves* instead). This is not resistance or immunity; the attempt simply looks in the wrong place. (The story answers *where he needs to be*.)"}, {"level": 1, "name": "The Story Provides", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "Kiviuq teleports up to 30 ft to an unoccupied space he can see, arriving from an unwatched angle: he has advantage on the next attack roll he makes before the end of his turn. (A tale introduces him mid-scene.)"}, {"level": 3, "name": "Wrong Footing", "cost_line": "Reaction · 2 CE.", "kind": "feature", "text": "When Kiviuq is targeted by an attack he can see, the attacker has disadvantage on the roll — they strike where the story said he'd be. If the attack misses, he may move up to 10 ft without provoking opportunity attacks. Once per round. (Where he *was*, one telling ago.)"}, {"level": 3, "name": "The Tale Turns", "cost_line": "Reaction · 3 CE.", "kind": "feature", "text": "When Kiviuq takes damage, he may halve it — the blow lands on a seal-skin, a snow-shape, a *decoy-tale* — and teleport up to 15 ft to an unoccupied space he can see. Once per round. (He mourns the decoy, briefly, the way you'd mourn a good lie well told.)"}, {"level": 6, "name": "Where the Story Needs Him", "cost_line": "Action · 4 CE.", "kind": "feature", "text": "Kiviuq names a place whose story he has heard (described to him, told around a fire, read in a report): he teleports up to 1 mile to an unoccupied space near it, over ice no map admits. In combat, he may instead teleport up to 60 ft and make one weapon attack with advantage as part of the same action. (The trail runs where the telling ripens.)"}, {"level": 11, "name": "The Unmappable", "cost_line": "Passive.", "kind": "feature", "text": "Opportunity attacks against Kiviuq have disadvantage; he ignores difficult terrain; creatures have disadvantage on Wisdom (Perception) checks to notice him. He is always, slightly, between the lines of the story. (Blades swung at his passing find only weather.)"}], "maximum": {"level": 18, "name": "Maximum: EVERYWHERE IN THE TELLING", "cost_line": "Action · 8 CE · 1 minute (concentration).", "kind": "maximum", "text": "Kiviuq flickers *between* tellings: at the start of each of his turns he may teleport up to 30 ft (no action); attacks against him have disadvantage; once per round, when he hits with a weapon attack, he may deal an extra 3d8 force damage — the blow comes from a direction the target never faced. (Here, there, mid-step between two places at once.)"}, "domain": {"level": null, "name": "The Trail With No End", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 60-ft radius · disclosed.", "kind": "domain", "text": "Ice to the horizon, the kayak's wake closing behind him. Inside this domain, the **sure-hit** is *No Fixed Point* — no creature inside can be tracked, scried, or magically located, and hostile creatures inside cannot take reactions (no one ever knows where he is). Additionally, Kiviuq may teleport up to 15 ft as a free action once per round. (Inside the Trail, there are no fixed points. Only the story, still being told.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Story Goes On", "cost_line": "Once per long rest.", "kind": "l20", "text": "When Kiviuq is reduced to 0 hit points, he does not fall — the tale refuses the ending: he drops to 1 hit point instead, teleports up to 60 ft to an unoccupied space he can see, and becomes invisible until the end of his next turn. Each hostile creature that saw him fall must succeed on a Wisdom save against his technique DC or be frightened for 1 minute (frightened of *where he went*). (Wars end. Stories don't.)"}, "summary_text": null, "source_file": "64-kiviuq.md"}, {"id": "roald-amundsen", "module": "65", "figure": "Roald Amundsen", "title": "ROALD AMUNDSEN", "detail": "full", "technique": "THE WAY THROUGH", "tier": "IV", "role": "Route support", "ce_ability": "WIS", "primary_verb": "Read", "region": "Polar", "era": "1872–1928 · early 20th c.", "culture": "Norwegian", "concept": "He found the way through everything — the Northwest Passage, the South Pole, the Northeast Passage — except the way home, and the General has offered him one last first passage: through whatever the Inheritance Shift unmakes.", "serves": "**Movement / Phase 2 logistics.** **Inheritance Shift (Phase 2):** the pathfinder — routes through triggered spaces, whiteouts, and broken ground; awakened assets moved, unambushed, to where the experiment needs them. **All-Out War:** the uninterceptable column — armies repositioned through unmaking ground, depots laid like a ledger. The Shift unmakes the world's certainties. I walk first.", "features": [{"level": 1, "name": "Read the Ice", "cost_line": "Action · 1 CE.", "kind": "feature", "text": "**Tier IV · Route support · Suggested CE ability: WIS · Primary verb: *Read.*** *Route-craft, perfected. Amundsen reads terrain, weather, and ground the way other men read charts — completely. He finds the way through any terrain, any barrier short of a Domain, and his parties walk it unambushed.* **Trail-Marked.** As Amundsen moves, he leaves trail-marks (cairns, cuts, knots — no action). Willing creatures that follow his marks (staying within 10 ft of his path) count as traveling with him for all his features. Marks last 24 hours.\n\nAmundsen reads the terrain and weather within 1 mile: he learns all hazards (natural and placed — pitfalls, unstable ice, ambush ground), the safest line of travel, and what the weather was yesterday (hence what it will likely be tomorrow — reading, not prophecy). He cannot be lost while this reading is fresh (1 hour). (The ice rewards the prepared.)"}, {"level": 1, "name": "Trail-Marked Passage", "cost_line": "Passive.", "kind": "feature", "text": "Amundsen and willing creatures following his trail-marks ignore difficult terrain caused by natural environment (ice, snow, rubble, undergrowth — not magical terrain), and cannot be surprised by ambush while traveling — he reads the ground too completely for the text to lie. (Complete present-reading, not foresight: this covers travel only, never the opening round of a fight already joined. Single file behind the markers.)"}, {"level": 3, "name": "The Way Through", "cost_line": "Action · 3 CE · 1 hour.", "kind": "feature", "text": "For the duration, Amundsen's traveling party (up to 12 willing creatures following his marks) ignores all difficult terrain, cannot be ambushed (enemies cannot gain surprise against the party while it moves), and leaves no usable trail — Survival checks to track the party automatically fail. (The party reads as one text.)"}, {"level": 3, "name": "Depot", "cost_line": "1-hour ritual · 2 CE.", "kind": "feature", "text": "Amundsen lays a depot — cached supplies, correctly placed. Up to 6 creatures taking a short rest at the depot recover an extra 1d8 hit points and may remove one level of exhaustion. The depot persists 7 days. (Supplies laid like a ledger.)"}, {"level": 6, "name": "First Passage", "cost_line": "Action · 5 CE.", "kind": "feature", "text": "Amundsen opens a corridor — 10 ft wide, 60 ft long — through any barrier short of a Domain: walls, magical wards and barriers of 5th level or lower, triggered spaces, whiteouts. The corridor lasts 1 minute; those who walk it are unaffected by the barrier. Domain barriers and 6th-level+ workings are *decisions*, not terrain — the route stops at their edge. (The route does not ask permission.)"}, {"level": 11, "name": "No One Left on the Ice", "cost_line": "Reaction · 4 CE.", "kind": "feature", "text": "When a willing creature Amundsen can see within 60 ft drops to 0 hit points, the route carries them: they are moved up to 30 ft to an unoccupied space of Amundsen's choice (no opportunity attacks) and stabilized. Once per round. (He has never left a man.)"}], "maximum": {"level": 18, "name": "Maximum: THE POLE IS A PLACE YOU WALK TO", "cost_line": "Action · 8 CE · 10 minutes.", "kind": "maximum", "text": "The route, perfected: Amundsen and up to 8 willing creatures travel at double speed, ignore all difficult terrain and all environmental damage from cold and weather, and *cannot be intercepted* — pursuers cannot close, cut off, or ambush them for the duration (not teleportation; simply uncatchable). (Already gone.)"}, "domain": {"level": null, "name": "The Northwest Passage", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "Three winters of ice, the *Gjøa* frozen in, trail-markers to the horizon. Inside this domain, the **sure-hit** is *The Trail Holds* — each ally inside may move up to their speed along Amundsen's trail as a free action once per round, passing through hostile spaces without provoking opportunity attacks. Hostile creatures inside treat all terrain as difficult and cannot make opportunity attacks against creatures moving along the trail. (Inside the Passage, his people *move*. Everyone else *wades*.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Last Flight", "cost_line": "Once per long rest.", "kind": "l20", "text": "Amundsen commits to a route that does not exist yet: naming a place he has read about (studied in charts, journals, or his own Read the Ice), he and up to 8 willing creatures travel there over the course of 1 minute — up to 500 miles, over any terrain, uninterceptable, unambushable. They arrive together, provisioned, trail-marked. Once committed, he cannot turn back mid-route (his vow holds). (First passage, always.)"}, "summary_text": null, "source_file": "65-roald-amundsen.md"}, {"id": "egil-skallagrimsson", "module": "66", "figure": "Egil Skallagrimsson", "title": "EGIL SKALLAGRIMSSON", "detail": "full", "technique": "THE CARVED WORD", "tier": "IV", "role": "Runecaster controller", "ce_ability": "INT", "primary_verb": "Carve", "region": "Iceland / Norway", "era": "c. 904–995 · 10th c.", "culture": "Norse", "concept": "The greatest skald of the Viking Age carved runes that healed and runes that killed, ransomed his own head with a poem composed in one night — and has come back to make every oath in the war visible and inescapable.", "serves": "**LEGIBILITY.** **Inheritance Shift (Phase 2):** the vow-poet — every oath the awakening produces, carved visible, terms undeniable; the war's promises given their true transcript. **All-Out War:** the carved record — truces, surrenders, and betrayals all legible, all enforceable, all permanent. The General's war runs on vows. I am the hand that writes them down.", "features": [{"level": 1, "name": "Carve the Oath", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "**Tier IV · Runecaster controller · Suggested CE ability: INT · Primary verb: *Carve.*** *The rune-staff, perfected. Spoken oaths become visible runes — legible, undeniable, enforceable. Every rune carved must be true; the hand stops at a lie.* *Technique DC = 8 + proficiency bonus + INT modifier.* **Carved.** A carved oath becomes **Carved** (no save — information, freely given, Heaven-witnessed). Terms readable by any creature (DC 10 Intelligence); no magic short of a Domain can alter or obscure them; disputing them is at disadvantage on Deception, and enforcement rolls gain +2.\n\nWhen a creature within 30 ft speaks an oath aloud (battle-cries count), Egil carves it — on a surface, an object, or hanging in the air. Carved for 24 hours (permanent on stone or steel). He maintains up to 5; a sixth ends the oldest. (The runes refuse to let it hide.)"}, {"level": 1, "name": "Skald's Measure", "cost_line": "Passive.", "kind": "feature", "text": "His hand stops at a lie — a false carving fails and he *knows* it was false. Advantage on Insight vs. spoken falsehoods he would record; magical concealment of *spoken terms* fails against him. He cannot be made to carve a lie. (Truth is the edge.)"}, {"level": 3, "name": "Head-Ransom Verse", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "Egil composes a true verse about a creature within 60 ft — it must be true (his vow enforces this). Wisdom save against his technique DC or the target has disadvantage on attacks against Egil for 1 minute (the verse binds their regard). It may end the effect early by taking 3d8 psychic as a free action — paying the verse its due, a willing-decline Heaven honors. (Praise, truly spoken, purchases the skull.)"}, {"level": 3, "name": "Curse-Rune", "cost_line": "Action · 3 CE.", "kind": "feature", "text": "Egil inscribes a curse-rune on a creature within 30 ft that broke a Carved oath — naming it truly. A false accusation stops his hand; the CE is unspent (Heaven judges). On a true naming: Charisma save against his technique DC or **4d8 psychic damage** and disadvantage on saves vs. his features for 1 minute. (Heaven prices it. Never me.)"}, {"level": 6, "name": "Nithing Pole", "cost_line": "1-hour ritual · 5 CE.", "kind": "feature", "text": "Egil raises a nithing pole naming a true crime and its doer. The named, wherever it is, *dreams of the pole*: disadvantage on saves vs. his Curse-Runes until the pole falls (AC 12, 30 HP), and it knows it is named. A false crime: the pole does not rise. (Eirik fled Norway.)"}, {"level": 11, "name": "The Ransom Paid", "cost_line": "Action · 6 CE.", "kind": "feature", "text": "Egil speaks a full drapa — every stanza true. Up to 6 willing creatures within 60 ft gain temporary HP equal to INT modifier + proficiency bonus and advantage on saves vs. charm and fear for 1 minute. (True, so it holds.)"}], "maximum": {"level": 18, "name": "Maximum: WORD-DEATH", "cost_line": "Action · 8 CE · once per long rest.", "kind": "maximum", "text": "Egil lays the curse-rune on a proven oathbreaker and *compounds* it: Charisma save against his technique DC or **8d10 psychic damage** plus a 24-hour curse (as *bestow curse*, no concentration — the breaker chooses the effect). Success: half damage, no curse. The naming must be true — a false Word-Death stops his hand and ends his technique for 24 hours. (The verse reconciles — in blood.)"}, "domain": {"level": null, "name": "The Field of Runes", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "The carved field: every oath ever sworn within it, hanging as burning script. The **sure-hit** is *No Secret Terms* — every oath spoken inside is automatically Carved (no save; though a creature may take 3d10 force damage to *swallow the words* that turn, a willing-decline Heaven honors). Hostile oathbreakers take **2d10 psychic damage** at initiative 20, Heaven collecting arrears. (No secret terms. Only the text.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "Sonatorrek", "cost_line": "Once per long rest.", "kind": "l20", "text": "Egil speaks his death-song — the truest verse he owns. For 1 minute: Carve the Oath and Curse-Rune become bonus actions; Curse-Runes deal double damage; every oath Carved during the song is *permanent*, unmakeable short of Heaven's own hand. Then one level of exhaustion. (The verse does not rot.)"}, "summary_text": null, "source_file": "66-egil-skallagrimsson.md"}, {"id": "milarepa", "module": "67", "figure": "Milarepa", "title": "MILAREPA", "detail": "full", "technique": "RENUNCIATION", "tier": "IV", "role": "Controller", "ce_ability": "WIS", "primary_verb": "Release", "region": "Tibet", "era": "c. 1052–1135 · 11th–12th c.", "culture": "Tibetan", "concept": "The saint Sun can't price — his technique runs on renunciation, so every price the General could offer slides off him.", "serves": "**VOLITION/PRICE.** **Inheritance Shift (Phase 2):** the control group — the living proof that will cannot be purchased, which makes the PRICE axis falsifiable and therefore real. **All-Out War:** the solvent — deployed by *scheduling*, never by order: battlefields with over-accumulated enemies get a season of Milarepa, and the towers fall.", "features": [{"level": 1, "name": "Empty Hands", "cost_line": "Passive.", "kind": "feature", "text": "**Tier IV · Controller · suggested CE ability WIS · Primary verb: *Release.*** *What you hold, holds you. What you release, releases you. Renunciation treats accumulation — buffs, temp HP, hoarded power — as a structural weakness: the tower, built up, is already falling.*\n\nHis unarmed strikes deal 1d8 + WIS modifier bludgeoning damage. While he holds nothing in his hands, has no temporary HP, and is not concentrating on a spell or effect: his technique save DC increases by 1, and he has advantage on saving throws against being charmed or frightened. (The vow, in his body.)"}, {"level": 1, "name": "Song of the Question", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "One creature within 60 ft that can hear him must succeed on a Wisdom saving throw against his technique DC. On a failure, one beneficial magical effect of Milarepa's choice on the target ends. (The song asks what it was for. Heaven agrees it was nothing.)"}, {"level": 3, "name": "The Tower Falls", "cost_line": "Action · 3 CE · usable PB times per long rest.", "kind": "feature", "text": "Each creature in a 30-ft radius sphere centered on a point he can see within 90 ft that has temporary HP must make a Constitution saving throw against his technique DC. On a failure, it loses all its temporary HP and takes psychic damage equal to half the amount lost (rounded down). On a success, it keeps its temporary HP. (What is built up, falls.)"}, {"level": 3, "name": "The Laugh Delays", "cost_line": "Reaction · 2 CE · once per round.", "kind": "feature", "text": "When a creature he can see within 60 ft would gain temporary HP, he laughs: the gain is delayed until the start of that creature's next turn instead of occurring now. (The mountain is in no hurry.)"}, {"level": 6, "name": "The Mountain Sits", "cost_line": "Passive.", "kind": "feature", "text": "He cannot be moved against his will, and cannot be knocked prone while conscious. (A mountain does not relocate for weather.)"}, {"level": 6, "name": "The Cave Seals", "cost_line": "Action · 4 CE · 1 minute (concentration).", "kind": "feature", "text": "A 20-ft radius sphere centered on a point he can see within 90 ft becomes a sealed cave. Hostile creatures inside cannot gain temporary HP and cannot be targeted by new beneficial magical effects. Willing creatures inside can take the Hide action as a bonus action. (The cave keeps what it keeps.)"}, {"level": 11, "name": "Nothing to Trade", "cost_line": "Passive.", "kind": "feature", "text": "Any magical or social effect structured as an offer — a benefit with a price — fails against him outright unless he willingly accepts it. If he refuses such an offer, the offerer takes 2d10 psychic damage as Heaven notes the attempted purchase. Additionally, Song of the Question may now target two creatures. (There is nothing to buy. There never was.)"}], "maximum": {"level": 18, "name": "Maximum: One Lifetime", "cost_line": "Action · 10 CE · once per long rest.", "kind": "maximum", "text": "Each hostile creature he can see within 120 ft must make a Wisdom saving throw against his technique DC. On a failure, all beneficial magical effects on it end and it loses all temporary HP. On a success, it keeps its temporary HP and one beneficial effect of its choice (all others end). (Enlightenment, all at once, for everyone present.)"}, "domain": {"level": null, "name": "The Hundred Thousand Songs: Drakar Taso", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "The white-rock cave at the moment of realization. Inside, the **sure-hit** is *The Song Unravels* — at initiative 20, the song peaks: each hostile creature inside must succeed on a Wisdom saving throw against his technique DC or lose all temporary HP and have one beneficial magical effect of its choice end. A creature may instead willingly take 4d10 psychic damage to keep everything until the next initiative 20 — a willing-decline valve Heaven honors. While the domain stands, his Empty Hands DC bonus becomes +2. (The less he holds, the more certain the song.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Last Laugh", "cost_line": "Passive · once per long rest.", "kind": "l20", "text": "When he would be reduced to 0 hit points, he instead drops to 1 hit point and laughs: each hostile creature within 60 ft that can hear him must succeed on a Wisdom saving throw against his technique DC or lose all temporary HP, and one beneficial magical effect of Milarepa's choice on it ends. Additionally, his body cannot be animated, bound, or raised as undead by any means — Heaven claimed it nine centuries ago. (He has been laughing at death for nine hundred years. Death has noticed.)"}, "summary_text": null, "source_file": "67-milarepa.md"}, {"id": "gesar-of-ling", "module": "68", "figure": "Gesar of Ling", "title": "GESAR OF LING", "detail": "full", "technique": "EPIC KINGSHIP", "tier": "IV", "role": null, "ce_ability": "STR", "primary_verb": "Name", "region": "Tibet / steppe", "era": "mythic", "culture": "Tibetan epic", "concept": "The hero of the longest epic in the world — still sung by living bards — returned by retelling-as-proof, and his technique is epic kingship itself: he names demons, rallies hosts, and endures like the mountain.", "serves": "**CONVERGENCE.** **Inheritance Shift (Phase 2):** the rallying pole — where the Shift produces true demons, the epic converges the awakened around a king who names them. **All-Out War:** the wildcard hammer — budgeted, never commanded: name a true demon and the mountain rides; name falsely and lose him forever.", "features": [{"level": 1, "name": "The Naming", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "**Tier IV Mythic · Striker/Tank · suggested CE ability STR · Primary verb: *Name.*** *Technique DC = 8 + proficiency bonus + STR modifier. A king names things, and the named thing obeys the name. Epic kingship rests on three pillars: the Naming (legibility), the Host (the muster of Ling), and the Mountain (endurance).* **Named.** When Gesar uses The Naming on a creature, it becomes **Named** for 1 minute: Gesar and his allies learn its damage resistances, immunities, and vulnerabilities, and their attacks against it deal an additional 1d4 force damage. A creature can bear only one Naming at a time. (Not mind control. Legibility — the epic has met this demon before.)\n\nName one creature he can see within 120 ft as a demon of the epic, speaking its demon-name aloud before witnesses. It becomes Named. (A named demon is a dead demon. The epic is clear on this point.)"}, {"level": 1, "name": "The Thirty Ride", "cost_line": "Action · 3 CE · 1 minute.", "kind": "feature", "text": "Two spectral warriors of Ling muster at his side (AC 15, HP 20, speed 40 ft). On his turn, he may use a bonus action to command each warrior to make one melee attack (+PB + STR to hit, 1d8 + STR slashing damage). They act on his initiative, after him. (Where the king goes, the host musters.)"}, {"level": 3, "name": "Deed Numbered", "cost_line": "Passive.", "kind": "feature", "text": "When he reduces a creature to 0 hit points, he gains temporary HP equal to his STR modifier + PB, and willing creatures within 30 ft gain +1 to saving throws until the start of his next turn. (The bard counts it. The host stands taller.)"}, {"level": 3, "name": "Demon-Slayer's Grip", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "Make a grapple check with advantage against a creature within reach. While grappling a Named creature, his weapon attacks against it score critical hits on a roll of 19–20. (He learned the demon's secret by getting close. The epic recommends it.)"}, {"level": 6, "name": "The Mountain Endures", "cost_line": "Passive.", "kind": "feature", "text": "When he takes damage, reduce it by his proficiency bonus. He cannot be knocked prone while conscious. (*\"Gesar endured like the mountain endures the storm.\"*)"}, {"level": 6, "name": "The Host Musters", "cost_line": "Action · 5 CE.", "kind": "feature", "text": "Up to PB willing creatures within 60 ft gain temporary HP equal to his CHA modifier + PB and may move up to half their speed without provoking opportunity attacks. (The king calls. Ling answers.)"}, {"level": 11, "name": "The Straw King", "cost_line": "Reaction · 3 CE · usable PB times per long rest.", "kind": "feature", "text": "When he is hit by an attack, the blow finds a straw man — the attack misses instead. (The trickster-king was never standing there.)"}], "maximum": {"level": 18, "name": "Maximum: Lutzen Falls Again", "cost_line": "Action · 10 CE · once per long rest.", "kind": "maximum", "text": "Gesar crosses the distance in a single bound — make one melee weapon attack with advantage against a creature within 60 ft. On a hit, it deals an additional 10d10 force damage. If the target is Named, it must succeed on a Constitution saving throw against his technique DC or be stunned until the end of its next turn and knocked prone. (The epic's oldest ending, reused.)"}, "domain": {"level": null, "name": "Ling Assembled: The Epic Sung Aloud", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 60-ft radius · disclosed.", "kind": "domain", "text": "The muster-field at dawn, thirty banners, the bard's voice over all of it. Inside, the **sure-hit** is *All Are Named* — every hostile creature inside is treated as Named. Additionally, at initiative 20, the epic names them: each hostile creature inside must succeed on a Charisma saving throw against his technique DC or have its current hit points spoken aloud to all present and be unable to become hidden or invisible until the next initiative 20. His spectral warriors may be commanded without spending a bonus action while the domain stands. (The epic names things. Named things cannot hide.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Epic Does Not End", "cost_line": "Passive.", "kind": "l20", "text": "Once per long rest, when he would be reduced to 0 hit points, he instead drops to 1 hit point. Additionally, while at least one willing ally within 120 ft spends its reaction at the start of its turn to keep singing, he cannot be reduced below 1 hit point; the singing ends as soon as no ally spends its reaction. (Kill the king and the song keeps him. Silence the singers first.)"}, "summary_text": null, "source_file": "68-gesar-of-ling.md"}, {"id": "k-inich-janaab-pakal", "module": "69", "figure": "K'inich Janaab Pakal", "title": "K'INICH JANAAB PAKAL", "detail": "full", "technique": "THE INSCRIPTION", "tier": "IV", "role": "Controller", "ce_ability": "INT", "primary_verb": "Record", "region": "Mesoamerica", "era": "603–683 · 7th c.", "culture": "Maya", "concept": "The ajaw of Palenque, carved in stone for thirteen centuries, whose technique roots battlefields to the road to Xibalba — so the slain of the field rise as witnesses, and the cost of the battle becomes legible.", "serves": "**LEGIBILITY.** **Inheritance Shift (Phase 2):** the auditor — every engagement's true cost, witnessed and carved, feeding true data into the experiment. **All-Out War:** the reckoning — battlefields rooted to Xibalba, where no commander can hide the price of the ground.", "features": [{"level": 1, "name": "The Road Beneath", "cost_line": "Bonus action · 2 CE · 1 minute (concentration).", "kind": "feature", "text": "**Tier IV · Controller · suggested CE ability INT · Primary verb: *Record.*** *Technique DC = 8 + proficiency bonus + INT modifier. What is written cannot be unwritten. What is witnessed cannot be denied. The Inscription opens the road to Xibalba beneath the battlefield — not to raise armies, but to make the slain present as witnesses.* **Witness.** An intangible shade of one slain. It cannot act, attack, or be harmed; it occupies its space and observes. Witnesses last 1 hour. Pakal can maintain a number of Witnesses equal to his proficiency bonus at once (if a new Witness would exceed this number, the oldest ends).\n\nA 30-ft radius sphere of ground centered on a point he can see within 90 ft shows the road to Xibalba through it. When a creature is reduced to 0 hit points inside the radius, a Witness rises from it. (The road was always there. He merely inscribes it.)"}, {"level": 1, "name": "Testimony", "cost_line": "Action · 1 CE.", "kind": "feature", "text": "Question one Witness within 60 ft: learn who dealt the killing blow, how much damage was dealt, and the slain creature's final intent, in one sentence. (The dead are the most reliable witnesses. They have nothing left to lose.)"}, {"level": 3, "name": "The Slain Are Present", "cost_line": "Passive.", "kind": "feature", "text": "While at least one Witness stands within 60 ft of Pakal, his allies have advantage on Insight and Perception checks, and hostile creatures within 60 ft have disadvantage on Deception checks. (Lies told over graves ring hollow.)"}, {"level": 3, "name": "The Weight of the Count", "cost_line": "Action · 3 CE.", "kind": "feature", "text": "Each hostile creature within 60 ft that has reduced another creature to 0 hit points within the last minute must make an Intelligence saving throw against his technique DC. On a failure, it takes 2d8 psychic damage per Witness he maintains (maximum 10d8); half damage on a success. (The cost, made legible, has weight.)"}, {"level": 6, "name": "Nine Steps Down", "cost_line": "Action · 4 CE · 1 minute (concentration).", "kind": "feature", "text": "The road deepens: choose a point he can see within 90 ft; a 30-ft radius sphere there becomes the deep road for 1 minute (concentration). If The Road Beneath is active, it ends — Witnesses still rise from creatures reduced to 0 hit points inside, as with The Road Beneath. The area is difficult terrain for hostile creatures, and a hostile creature that falls prone inside it is restrained by the roots of the World Tree until it uses an action to break free (Strength saving throw against his technique DC ends it). (Nine steps down. The roots remember every foot.)"}, {"level": 6, "name": "The Stone Remembers", "cost_line": "Passive.", "kind": "feature", "text": "He is immune to any effect that would alter or erase his memory. When he sees a creature use a named technique feature or cast a spell, he learns its true name. (Carved things do not forget.)"}, {"level": 11, "name": "The Witnesses Speak", "cost_line": "Action · 6 CE · once per short rest.", "kind": "feature", "text": "Every hostile creature within 60 ft must make a Wisdom saving throw against his technique DC. On a failure, it is frightened of the Witnesses for 1 minute; it may repeat the saving throw at the end of each of its turns, ending the effect on a success. While frightened this way, it has disadvantage on attack rolls. (The slain, all at once, saying what was done.)"}], "maximum": {"level": 18, "name": "Maximum: The Descent", "cost_line": "Action · 10 CE · once per long rest · 1 minute.", "kind": "maximum", "text": "He walks the road: he has resistance to all damage, can move through creatures and objects, and difficult terrain costs him no extra movement. Once during the minute, as a bonus action, he may drag one creature within 60 ft toward the road: it must succeed on an Intelligence saving throw against his technique DC or be pulled 30 ft toward the nearest Witness (if none stands, it is not moved) and restrained until the end of its next turn. (The king descends. The road knows him.)"}, "domain": {"level": null, "name": "The Inscription Beneath: Xibalba Road", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "The vaulted chamber under the Temple of the Inscriptions, the road running through it. Inside, the **sure-hit** is *The Dead Are Present* — every Witness he has raised in this battle returns at once (up to his maximum), and creatures reduced to 0 hit points inside the Domain raise Witnesses as with The Road Beneath (up to his maximum). At initiative 20, the dead recount: each hostile creature inside must succeed on an Intelligence saving throw against his technique DC or take 4d8 psychic damage as the dead recount its deeds — or it may *confess*, speaking aloud one true thing it did in this battle as a free action, and be immune to the recounting until the next initiative 20. (Heaven accepts the confession. The dead stand down.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Inscription Cannot Lie", "cost_line": "Passive.", "kind": "l20", "text": "Any effect that would compel him to speak or record falsehood fails against him. Once per long rest, when he would be reduced to 0 hit points, the stone keeps him: he is petrified at 1 hit point for 1 minute, remaining aware, and then returns. (He has been stone for thirteen centuries. He knows the posture.)"}, "summary_text": null, "source_file": "69-kinich-janaab-pakal.md"}, {"id": "la-malinche", "module": "70", "figure": "La Malinche", "title": "LA MALINCHE", "detail": "full", "technique": "THE TONGUE", "tier": "IV", "role": "Support", "ce_ability": "CHA", "primary_verb": "Render", "region": "Mexico", "era": "c. 1500–1529 · 16th c.", "culture": "Nahua", "concept": "Doña Marina, the enslaved Nahua interpreter of the conquest, whose technique translates bindings themselves — under her translation, spoken terms, intended terms, and Heaven's reading become one text.", "serves": "**CONVERGENCE.** **Inheritance Shift (Phase 2):** the narrow place — every multi-party binding of the experiment rendered mutually intelligible, converging the network through a single tongue. **All-Out War:** the audit — no vow in the war can hide behind language; spoken terms, intended terms, and Heaven's reading become one text.", "features": [{"level": 1, "name": "The Tongue", "cost_line": "Passive.", "kind": "feature", "text": "**Tier IV · Support · suggested CE ability CHA · Primary verb: *Render.*** *Under her translation, spoken terms, intended terms, and Heaven's reading become one text. The Tongue does not read minds — it renders what is said or sworn perfectly understood. Nothing said in her hearing can hide behind language.*\n\nShe speaks and understands all languages. Willing creatures within 30 ft of her understand each other regardless of language. (Between tongues, she is the bridge.)"}, {"level": 1, "name": "I Render It Plain", "cost_line": "Reaction · 1 CE.", "kind": "feature", "text": "When a creature within 60 ft casts a spell or activates a named technique feature that would force a saving throw or attack roll against her allies, she translates the working aloud: her allies have advantage on saving throws against it, or +2 AC against its attack rolls, until the end of the turn. She must perceive the working. (Translated, a curse arrives with its meaning attached. Meaning can be dodged.)"}, {"level": 3, "name": "Terms, Stated", "cost_line": "Action · 2 CE.", "kind": "feature", "text": "One willing creature within 60 ft that is charmed, frightened, or under a magically binding agreement immediately repeats the saving throw against the effect with advantage, as she renders its true terms. (No one she stands beside is bound by words they did not understand.)"}, {"level": 3, "name": "The Gap Is Audible", "cost_line": "Passive.", "kind": "feature", "text": "She always knows when a spoken statement's literal words diverge from its intended meaning — she hears the gap, not the thought. Deception checks against her have disadvantage, as do Deception checks against her allies within 30 ft. (Not mind reading. She hears the seam where the lie is stitched.)"}, {"level": 6, "name": "The Common Text", "cost_line": "Action · 3 CE · 1 minute (concentration).", "kind": "feature", "text": "Up to PB willing creatures within 60 ft enter the common text: they share perfect silent communication (complex plans as a free action); when one takes the Help action, the helped roll gains an additional 1d4; and when one member fails a saving throw against being charmed or frightened, another member within the text may use its reaction to grant a reroll. (One text. One party.)"}, {"level": 6, "name": "Translate the Wound", "cost_line": "Action · 2 CE · usable 3 times per long rest.", "kind": "feature", "text": "One willing creature within 30 ft regains 2d8 + CHA modifier hit points and may immediately attempt a saving throw against one condition affecting it, with advantage. (The wound, understood, loosens.)"}, {"level": 11, "name": "Heaven's Reading", "cost_line": "Action · 5 CE · once per short rest.", "kind": "feature", "text": "She speaks one active binding vow, geas, or magical agreement affecting a creature within 60 ft as Heaven reads it: all creatures within 60 ft learn its exact terms, price, and conditions. (Three texts become one text.)"}], "maximum": {"level": 18, "name": "Maximum: The First Word and the Last", "cost_line": "Action · 10 CE · once per long rest · 1 minute.", "kind": "maximum", "text": "No creature within 120 ft can speak falsely about a vow, bargain, or binding — attempts come out as the true terms. As a bonus action on her turns, she may translate one ongoing enchantment or charm on a willing creature within 60 ft into plain meaning: the affected creature makes a Charisma saving throw with advantage; on a success, the effect ends. (The lies come out as truth. The bindings come undone.)"}, "domain": {"level": null, "name": "Where Every Word Is Weighed", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 50-ft radius · disclosed.", "kind": "domain", "text": "A parley chamber with no shadows in the language. Inside, the **sure-hit** is *One Text* — every spoken statement is heard in its true meaning by all present: Deception is impossible inside (checks automatically fail). Hostile creatures casting spells with verbal components inside must speak the spell's true effect aloud as they cast it, and allies have advantage on saving throws against all spells cast inside the domain. A creature may choose silence instead — say nothing, and the text cannot render you. (The willing-decline valve: Heaven does not compel speech.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "50-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "The Tongue Remains", "cost_line": "Passive.", "kind": "l20", "text": "Magical silence and effects that would rob her of speech fail against her. Once per long rest, when a word-based hostile effect (command, suggestion, power word, a curse spoken aloud) targets her, she may use her reaction to translate it into plain meaning: it ends on her, and she learns its exact terms. (Five hundred years of men have tried to use her tongue against her. The tongue remains hers.)"}, "summary_text": null, "source_file": "70-la-malinche.md"}, {"id": "ajuricaba", "module": "71", "figure": "Ajuricaba", "title": "AJURICABA", "detail": "full", "technique": "THE CONFEDERATION'S WOUND", "tier": "IV", "role": "Tank", "ce_ability": "CON", "primary_verb": "Share", "region": "Amazon", "era": "d. 1728 · 18th c.", "culture": "Manaus", "concept": "Thirty tribes, one wound — his technique is the confederation made metaphysical: no one bleeds alone, and no one is ever compelled to share.", "serves": "**VOLITION.** **Inheritance Shift (Phase 2):** the doctrine of the willing line — the experiment's great test of voluntary association: *can the empowered many hold as one, by choice?* **All-Out War:** the tank of the war itself — and the auditor of every chain: no binding without the willing-decline, and he is the price's witness.", "features": [{"level": 1, "name": "No One Bleeds Alone", "cost_line": "Reaction · 2 CE.", "kind": "feature", "text": "**Tier IV · Tank · Suggested CE ability: CON · Primary verb: *Share.*** *Damage dealt to one is carried by the willing many. Nothing is reduced, nothing denied — the wound is divided, and the division is always chosen.* **The Confederation.** Willing creatures within 60 ft of Ajuricaba are **the Confederation**. Membership is declared freely and may be withdrawn freely at any time (no action). No effect in this campaign can compel membership — Heaven enforces the decline.\n\nWhen a willing creature in the Confederation takes damage, Ajuricaba divides the damage among any number of willing creatures in the aura (including himself), decided after seeing the damage roll. No creature may be assigned more than half the total. A creature may decline its share as a free choice — decliners cannot be assigned shares for 1 minute. A declined share is reassigned among the remaining willing creatures; if none remain willing, the original target bears it. The damage is never reduced. It is *shared*."}, {"level": 1, "name": "Chain-Breaker", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "Spectral chains — the chains that held him, wielded now — lash out at a creature within 30 ft: melee spell attack, dealing **2d8 + CON modifier force damage** on a hit, and the target's speed becomes 0 until the start of Ajuricaba's next turn. The chains hold."}, {"level": 3, "name": "Take the Blow", "cost_line": "Reaction · 3 CE · once per round.", "kind": "feature", "text": "When a willing creature in the Confederation would take damage, Ajuricaba takes all of it instead. No division, no decline — his choice, his back. (The chief bleeds first. That was always the price of the line.)"}, {"level": 3, "name": "The Line Remembers", "cost_line": "passive", "kind": "feature", "text": "When Ajuricaba takes damage assigned through No One Bleeds Alone or Take the Blow, the river returns what it borrowed: at the start of his next turn he regains HP equal to his **CON modifier** (once per round). The damage itself is never reduced — it is shared, and then weathered. The river has carried worse."}, {"level": 6, "name": "Confederation Wall", "cost_line": "Action · 5 CE · 1 minute.", "kind": "feature", "text": "The aura extends to **120 ft**. While it lasts: shares assigned through No One Bleeds Alone may not exceed **one-third** of the total per creature; and once per round, when a Confederation member takes damage from an attack, Ajuricaba may have the attacker take **force damage equal to his CON modifier + proficiency bonus** as the wall answers. No action required."}, {"level": 11, "name": "The River Takes the Blow", "cost_line": "Action · 8 CE · once per long rest.", "kind": "feature", "text": "For 1 minute, whenever a willing creature in the Confederation takes damage, Ajuricaba may reassign **any portion** of it to himself after seeing the roll — no reaction required. Damage he takes this way is never reduced; at the start of his next turn he regains HP equal to his **CON modifier** (once per round). The river carries what the line cannot."}], "maximum": {"level": 18, "name": "Maximum: THE MEETING OF THE WATERS", "cost_line": "Action · 10 CE · once per long rest.", "kind": "maximum", "text": "For 1 minute, all damage dealt to willing creatures within 120 ft is **pooled** and split evenly among all willing creatures in the aura (minimum 1 per creature; if the pooled total is less than the number of willing creatures, divide it one point at a time among them until exhausted). Ajuricaba may voluntarily take any creature's share onto himself, in addition to his own. Once per creature per Maximum, pooled damage cannot reduce a creature below 1 HP — the black water and the brown water run side by side, and neither drowns the other."}, "domain": {"level": null, "name": "THE CONFEDERATION ASSEMBLED", "cost_line": "Full-turn action · 20 CE · 60-ft enclosed Domain · 800 clash points · 5-round burnout · 2-minute duration.", "kind": "domain", "text": "The muster of the thirty peoples, standing in one line. **Sure-hit (allies):** redistribution through No One Bleeds Alone costs 0 CE once per round (still requiring his reaction), shares may not exceed one-third per creature, and Take the Blow costs 1 CE. **Sure-hit (enemies):** hostile creatures cannot move willing creatures out of the Domain against their will, and damage dealt to Confederation members inside is **redistributed, never reduced** — half of each attack's damage (round down) is divided among the other willing Confederation members in the Domain, no share exceeding one-third of the redistributed amount. Any portion that cannot be assigned — because members decline or the one-third cap leaves a remainder — is borne by the original target. The river carries the blow before it lands; it does not lighten it. (Members may still decline freely; the Domain honors every decline.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft enclosed Domain", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "HE NEVER SURRENDERED", "cost_line": "Passive.", "kind": "l20", "text": "Once per long rest, when Ajuricaba would be reduced to 0 HP, he is reduced to **1 HP** instead, and every willing creature in the Confederation gains **temporary HP equal to his CON modifier + proficiency bonus**. He is immune to any effect that would compel him to surrender, ask quarter, or lay down arms — frightened and charmed effects that carry such commands fail against him automatically. The vow holds. It always held."}, "summary_text": null, "source_file": "71-ajuricaba.md"}, {"id": "cobra-norato", "module": "72", "figure": "Cobra Norato", "title": "COBRA NORATO", "detail": "full", "technique": "THE RIVER THAT WALKS", "tier": "IV", "role": "Striker", "ce_ability": "DEX", "primary_verb": "Drown", "region": "Amazon", "era": "mythic", "culture": "Amazonian folklore", "concept": "He owns the crossings — every river passage in the Amazon is his to grant or deny, and the drowned things beneath answer when he calls.", "serves": "**FRICTION.** **Inheritance Shift (Phase 2):** the Amazon's closed crossings — the experiment's great test of denied movement: *can the empowered move men and materiel when the river says no?* **All-Out War:** the interdictor of the basin — every enemy convoy on the water pays the toll or pays the river. **Unvowed, unpositioned, unbound — and load-bearing anyway.**", "features": [{"level": 1, "name": "Coil and Strike", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "**Tier IV · Striker · Suggested CE ability: DEX · Primary verb: *Drown.*** *Technique DC = 8 + proficiency bonus + DEX modifier. He owns the passages — the fords, the narrows, the crossings. Who crosses the water crosses him. (Rivers, specifically — the sky is not his country.)* **Encantado.** Cobra Norato has a swim speed of 40 ft, can breathe underwater, and cannot be surprised while in water.\n\nWhile in water or within 5 ft of a body of water: a black coil lashes out — melee attack with reach 15 ft, using DEX: **3d8 + DEX modifier bludgeoning damage** on a hit, and the target must succeed on a STR save against the technique DC or be pulled **10 ft toward the water**."}, {"level": 1, "name": "The Deep Place", "cost_line": "passive", "kind": "feature", "text": "While Cobra Norato is in water, attacks against him from creatures not in the water have **disadvantage** — the deep place hides its own. (He does not fight on land. This is jurisdiction, not limitation.)"}, {"level": 3, "name": "The River Decides", "cost_line": "Reaction · 2 CE · once per round.", "kind": "feature", "text": "When a hostile creature moves within 20 ft of a body of water, the current takes an interest: STR save against the technique DC or be pulled **15 ft into the water** and knocked **prone**. A creature that succeeds cannot be pulled again for 1 minute. (The crossing is his to grant.)"}, {"level": 3, "name": "The Drowned Rise", "cost_line": "Bonus action · 3 CE.", "kind": "feature", "text": "The congregation answers: spectral drowned rise in water within 60 ft — up to **three shades**, each immediately making one melee attack (+PB + DEX modifier to hit, reach 5 ft, **2d6 necrotic damage**) against a creature of his choice in the water, then sinking again."}, {"level": 6, "name": "Own the Crossing", "cost_line": "Action · 4 CE · 1 hour.", "kind": "feature", "text": "Cobra Norato designates a water passage up to **200 ft long** that he can see. For the duration, hostile creatures cannot cross it without his leave: any attempt requires a **DEX save** against the technique DC — on a failure the creature is pulled under, **restrained** until it succeeds on the save at the end of its turn, taking **3d8 bludgeoning damage** at the start of each of its turns while restrained. *Willing-decline:* any creature may instead **pay the toll** — take **2d8 force damage**, no save — and cross freely."}, {"level": 11, "name": "The Flood Comes Up", "cost_line": "Action · 8 CE · 1 minute.", "kind": "feature", "text": "The river shrugs: flood a **60-ft radius** centered on a point within 90 ft. The area becomes **difficult terrain** and counts as **water** for all his features. Hostile creatures in the area when it floods must succeed on a STR save or be swept **20 ft** in a direction of his choice and knocked prone."}], "maximum": {"level": 18, "name": "Maximum: THE COBRA GRANDE", "cost_line": "Action · 10 CE · once per long rest · 1 minute.", "kind": "maximum", "text": "He stops being the man-shaped rumor and becomes the tale entire: Cobra Norato transforms into a **Huge serpent** — swim speed 60 ft, advantage on STR saves, immune to the restrained condition. **Bite (action):** melee attack (+PB + DEX modifier to hit), reach 15 ft, **6d10 + DEX modifier piercing damage**, and the target is **grappled** (escape DC = technique DC). **Constrict:** a grappled creature takes **4d10 bludgeoning damage** at the start of each of its turns."}, "domain": {"level": null, "name": "THE RIVER REMEMBERS", "cost_line": "Full-turn action · 20 CE · 60-ft radius · 800 clash points · 5-round burnout · 2-minute duration.", "kind": "domain", "text": "The ground becomes riverbed; the air smells of deep water. The whole Domain counts as **water** for his features. **Sure-hit:** at initiative 20, the current takes them: each hostile creature is dragged **15 ft toward the Domain's center** — no save; the current is the sure-hit. *Willing-decline:* a creature may instead **drop prone and hold fast**, taking no pull until the next initiative 20 — Heaven honors the choice to cling. The drowned rise unbidden: at initiative 20, one spectral shade attacks as in The Drowned Rise, no CE cost.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "NO CHAIN HOLDS WATER", "cost_line": "Passive.", "kind": "l20", "text": "Once per long rest, when Cobra Norato would become **bound, restrained, paralyzed, or dominated** by a technique or magical effect, he may spend **5 CE** to shed the skin instead: the effect ends, he teleports up to **60 ft** to unoccupied water he can see (or the nearest body of water within 60 ft), and a shed serpent-skin is left behind where he stood. The skin cannot shed vows — a genuinely sworn vow's price is not a binding the river can cross. He is immune to the **charmed** condition — the river is not seduced; it is *crossed*, or it is not."}, "summary_text": null, "source_file": "72-cobra-norato.md"}, {"id": "hotu-matu-a", "module": "73", "figure": "Hotu Matu'a", "title": "HOTU MATU'A", "detail": "full", "technique": "THE MOORING", "tier": "IV", "role": "Controller", "ce_ability": "WIS", "primary_verb": "Anchor", "region": "Rapa Nui", "era": "mythic · c. 1200 CE", "culture": "Rapa Nui", "concept": "Under his spoken word, fleets cannot move — the moai are his witnesses, his own people sail free, and trespassers are becalmed.", "serves": "**FRICTION.** **Inheritance Shift (Phase 2):** the Pacific's closed sea — the experiment's great test of denied movement: *can the empowered project force across water the ariki has moored?* **All-Out War:** the anti-navy of the war itself — hostile fleets becalmed at a word — and the legitimized watch: the Moai's Eyes, now compacted, now bedrock.", "features": [{"level": 1, "name": "The Ariki's Word", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "**Tier IV · Controller · Suggested CE ability: WIS · Primary verb: *Anchor.*** *Technique DC = 8 + proficiency bonus + WIS modifier. Spoken authority, given weight. The ariki's word stills what it names — but the binding bites trespassers only; his own people sail free.* **The Word.** Hotu Matu'a's mooring effects never affect **willing** creatures — his people, his allies-by-choice, pass through his word like wind through a sail. The binding is for the uninvited.\n\nHotu Matu'a speaks to one creature or vessel he can see within 120 ft: **WIS save** against the technique DC or its speed becomes **0** until the end of his next turn. Willing creatures are unaffected — no save needed; the word passes over them."}, {"level": 1, "name": "Swell-Reading", "cost_line": "passive", "kind": "feature", "text": "He reads the water the way others read faces: Hotu Matu'a always knows the **direction** (not distance, not identity) of vessels and Huge-or-larger creatures moving in water within **1 mile**. He has **advantage** on checks to navigate, predict, or intercept movement at sea. (The swells bend around islands. He reads the bending.)"}, {"level": 3, "name": "The Fleet Is Moored", "cost_line": "Action · 4 CE · 1 minute.", "kind": "feature", "text": "For the duration, hostile creatures within **60 ft** have their speed **halved** and cannot take the **Dash** action — WIS save against the technique DC at the start of each of their turns negates the effect for that turn. Willing creatures move freely. (The word goes out over the water, and the water keeps it.)"}, {"level": 3, "name": "Star-Path", "cost_line": "Reaction · 2 CE · once per round.", "kind": "feature", "text": "When a willing creature within 120 ft would be moved against its will, Hotu Matu'a names a star: the movement is **negated**. The willing are not moved but by their own word. (His people sail free. That was always the verse.)"}, {"level": 6, "name": "The Moai Witness", "cost_line": "Action · 5 CE · 1 minute.", "kind": "feature", "text": "The fifteen attend: Hotu Matu'a's mooring save DC increases by **2**, hostile creatures have **disadvantage** on saves against his mooring effects, and he may perceive through the **Moai's Eyes** (Latent Asset 18) — seeing arrivals and departures within 10 miles of the ahu as if present. (A word witnessed by the ancestors is a word Heaven cannot mishear.)"}, {"level": 11, "name": "The Anchorage", "cost_line": "Action · 8 CE · 1 minute (concentration).", "kind": "feature", "text": "A **120-ft radius** centered on a point within 150 ft becomes anchored water. Hostile creatures and vessels that enter or start their turns inside must succeed on a **WIS save** or have speed **0** until the start of their next turn. Willing creatures sail free."}], "maximum": {"level": 18, "name": "Maximum: THE SHORE HOLDS", "cost_line": "Action · 10 CE · once per long rest · 1 minute.", "kind": "maximum", "text": "For the duration, no hostile creature or vessel within **300 ft** can move without his spoken leave: each must succeed on a **WIS save** at the start of its turn or have speed **0** for that turn. His willing allies are unaffected. The sea holds its breath. He decides when it exhales."}, "domain": {"level": null, "name": "THE FLEET AT ANCHOR", "cost_line": "Action · 20 CE · 60-ft radius · 800 clash points · 5-round burnout · 2-minute duration.", "kind": "domain", "text": "The sea goes glass-still; the stars come out at noon. **Sure-hit (enemies):** hostile creatures cannot take the **Dash** action, their speed is **halved**, and Hotu Matu'a knows the **current heading, speed, and declared course** of every vessel inside — what the water shows, not what the master intends. **Sure-hit (allies):** willing creatures' movement cannot be reduced or denied by any effect while inside. (The stillness, perfected: nothing hostile moves but by his leave.)", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE FIRST ARIKI", "cost_line": "Passive.", "kind": "l20", "text": "Once per long rest, Hotu Matu'a speaks the great mooring: every **hostile vessel within 1 mile** is **becalmed** — speed 0 for **10 minutes**. *Willing-decline:* the master of a vessel may instead **turn about** — abandoning its course — and sail freely *away* from him. Turn back, and go free. (The first ariki apportioned the sea. The apportioning stands.)"}, "summary_text": null, "source_file": "73-hotu-matua.md"}, {"id": "maquinna", "module": "74", "figure": "Maquinna", "title": "MAQUINNA", "detail": "full", "technique": "THE GIVEAWAY", "tier": "IV", "role": "Support", "ce_ability": "CHA", "primary_verb": "Give", "region": "Pacific Northwest", "era": "18th–19th c.", "culture": "Nuu-chah-nulth", "concept": "Wounds are wealth — he takes his people's hurts onto himself and gives them onward as gifts, and every gift increases his standing.", "serves": "**PRICE / UNPROFITABILITY.** **Inheritance Shift (Phase 2):** the potlatch support — the experiment's great test of converted cost: *can the empowered take wounds and return them as standing?* **All-Out War:** the giver of the war itself — every wound dealt to his side is priced, redistributed, and spent — and the host of the Broken Copper: the hand the distributed value has been waiting for.", "features": [{"level": 1, "name": "I Give This Wound", "cost_line": "Reaction · 2 CE.", "kind": "feature", "text": "**Tier IV · Support · Suggested CE ability: CHA · Primary verb: *Give.*** *Wounds are wealth. He takes his people's hurts onto himself and gives them onward among the willing — never forced; a gift compelled is theft, and Heaven knows the difference.* **Standing.** Each time Maquinna takes or redistributes damage through his technique, he gains **1 Standing** (maximum = proficiency bonus). He may spend Standing when he deals damage or restores HP with a technique feature: **+1 per point spent** to the damage or healing roll. If a feature states its own Standing gain, use that instead of the general gain above. The more he gives, the greater his standing.\n\nWhen a willing creature within 60 ft takes damage, Maquinna takes up to **half** of it (round up) onto himself instead — decided after seeing the roll. He gains 1 Standing. (The chief bleeds first. That was always the price of the name.)"}, {"level": 1, "name": "The Giver's Eye", "cost_line": "passive", "kind": "feature", "text": "A giver knows what is needed: Maquinna always knows the **current and maximum HP** of willing creatures within 60 ft."}, {"level": 3, "name": "Name the Gift", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "Maquinna gives a willing creature within 60 ft **temporary HP equal to his CHA modifier + proficiency bonus** — and names the gift aloud: *\"I give you shelter.\"* *\"I give you breath.\"* The naming is not flavor. Heaven hears it."}, {"level": 3, "name": "The Flow Cannot Stop", "cost_line": "passive", "kind": "feature", "text": "Heaven audits the flow: Maquinna cannot gain **temporary HP** from any source except his own technique — what would be kept must instead be given."}, {"level": 6, "name": "Copper's Logic", "cost_line": "Action · 4 CE.", "kind": "feature", "text": "Maquinna names gifts: restore a total of **4d8 + CHA modifier HP**, divided as he chooses among willing creatures within 60 ft — each share named aloud. If he carries a fragment of the **Broken Copper** (Latent Asset 21), add his **proficiency bonus** to the total."}, {"level": 11, "name": "The Great Giveaway", "cost_line": "Action · 7 CE · 1 minute.", "kind": "feature", "text": "For the duration, when a willing creature within 60 ft takes damage, Maquinna may take **any portion** of it onto himself — decided after the roll, no reaction required — and gains 1 Standing per **10 damage** taken this way (round down). The giving, at full flood."}], "maximum": {"level": 18, "name": "Maximum: THE BOSTON'S CARGO", "cost_line": "Action · 10 CE · once per long rest.", "kind": "maximum", "text": "He gives everything at once: every willing creature within **120 ft** regains **6d8 + CHA modifier HP**, each healing named as a gift — and Maquinna takes **2d8 force damage** per creature healed, the giver's own bleeding, willingly borne. He then gains Standing equal to the number of creatures healed."}, "domain": {"level": null, "name": "THE HOUSE OF GIFTS", "cost_line": "Full-turn action · 20 CE · 60-ft radius · 800 clash points · 5-round burnout · 2-minute duration.", "kind": "domain", "text": "The potlatch house, perfected — every gift named, every wound accounted. **Sure-hit (allies):** whenever a willing creature in the Domain takes damage, **half** of it (round down) flows to Maquinna as a gift instead — he takes it, in full; the gift is received before it is given. He may immediately give it onward as healing to another willing creature in the Domain (1:1, no action): healing given this way can never exceed the damage he actually took that round, and the taken damage is not reduced by the giving. (Transfer and conversion, accounted — never both at full value.) **Sure-hit (enemies):** a hostile creature that deals damage to a willing creature inside is **priced** — it takes **psychic damage equal to half the damage it dealt before any redirection (round down)**. *Willing-decline:* on its turn, it may instead **stop** — taking no hostile action against the Domain's guests for 1 round — and owe nothing while stopped.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE NAME GROWS", "cost_line": "Passive.", "kind": "l20", "text": "Once per long rest, Maquinna makes the great giving: he distributes **his own HP** among willing creatures within 120 ft as healing — up to half his current HP, minimum 1 per recipient, shares chosen freely and named aloud. For **24 hours** afterward, he has **advantage on all Charisma checks** and his Standing maximum **doubles**. That night, his name is spoken in every potlatch on the coast."}, "summary_text": null, "source_file": "74-maquinna.md"}, {"id": "dzunuk-wa", "module": "75", "figure": "Dzunuk'wa", "title": "DZUNUK'WA", "detail": "full", "technique": "HU-HU-HU", "tier": "V", "role": "Unaimable Tank", "ce_ability": "CON", "primary_verb": "Take", "region": "Pacific Northwest", "era": "mythic", "culture": "Kwakwaka'wakw folklore", "concept": "She is hunger with a shape — nearly unkillable, devouring what stands before her, unvowable because there is no one to vow with in the way Heaven requires — and you do not leash hunger; you decide what stands in front of it, and you make sure it is never you.", "serves": "**FRICTION.** **Inheritance Shift (Phase 2):** the Pacific Northwest as a denied theater — no organized force, his or anyone's, operates in her ranging; enemy logistics in the coastal theater rot from the simple fact of her. **All-Out War:** the unaimable weapon — pointed, never commanded, at concentrations the General needs *gone* rather than defeated: the basket keeps what battle would only scatter.", "features": [{"level": 1, "name": "The Cry", "cost_line": "passive aura", "kind": "feature", "text": "**Tier V · Unaimable Tank · Suggested CE ability: CON · Primary verb: *Take.*** *Technique DC = 8 + proficiency bonus + CON modifier. She is Huge. She targets the nearest hostile creature with all offensive features — she cannot be directed to a specific target by any means.* **Devoured.** When Dzunuk'wa reduces a creature to 0 HP — or stuffs it into the basket with Into the Basket — it is not killed — it is **Devoured**: removed into the basket, unreachable by revival, resurrection, scrying, or sending while she lives. If she is slain, the Devoured spill out at 0 HP, stable. A creature may be pulled free as an action with a successful STR contest against her (the reacher provokes her Snatch reaction).\n\nHer pursed lips never stop: *hu-hu-hu.* Creatures within 60 ft that can hear her must succeed on a WIS save vs her technique DC at the start of their turn or be **frightened** of her until the start of their next turn. A creature that succeeds is immune for 1 minute. (The willing-decline: a creature may stop its ears — cotton, wax, hands — becoming deafened; the deafened cannot hear the cry. The forest charges for the silence: deafened creatures have disadvantage on Perception.)"}, {"level": 1, "name": "The Forest Outlasts", "cost_line": "passive", "kind": "feature", "text": "At the start of her turn, she regains **15 HP**. If she took fire or radiant damage since her last turn, she does not regenerate that turn — the char must fall off first. Additionally, the first time each round she would take damage, reduce it by **10** (hide of winter). She cannot be **banished, turned, or possessed** — the forest does not leave."}, {"level": 3, "name": "Snatch", "cost_line": "reaction, 3 CE", "kind": "feature", "text": "When a creature within 15 ft of her misses her with an attack, or when she succeeds on a saving throw against its effect, she grabs it: the creature is **grappled** (escape DC = her technique DC). While grappled by her, the winter cold closes around it — it hears only *hu-hu-hu*."}, {"level": 3, "name": "The Woods Close", "cost_line": "bonus action, 2 CE", "kind": "feature", "text": "For 1 minute, the ground within 30 ft of her becomes **difficult terrain** for hostile creatures — roots, deadfall, the forest remembering it is hers. She ignores it. (She does not create the terrain. She *reminds* it.)"}, {"level": 6, "name": "She Eats the Vanguard", "cost_line": "action, 5 CE", "kind": "feature", "text": "Bite: melee attack, +PB + STR to hit, reach 15 ft. On hit: **6d12 + STR bludgeoning damage**. If this reduces the target to 0 HP, it is **Devoured** — and she regains HP equal to half the damage dealt, the basket settling heavier on her back."}, {"level": 6, "name": "Into the Basket", "cost_line": "action, 4 CE", "kind": "feature", "text": "Every creature **grappled** by her within 15 ft must succeed on a STR save vs her technique DC or be stuffed into the basket — **Devoured** alive. On a success, the grapple ends (the quick child, escaping — this time)."}, {"level": 11, "name": "The Basket Is Never Full", "cost_line": "action, 7 CE", "kind": "feature", "text": "She shakes the basket. The Devoured within cry out (if the basket is empty, there is no cry) — every hostile creature within 60 ft that can hear must succeed on a WIS save vs her technique DC or be **frightened** for 1 minute (repeat the save at the end of each turn). She gains **temporary HP equal to 10 × the number of Devoured** in the basket (maximum 100). The basket settles. It is never full."}], "maximum": {"level": 18, "name": "Maximum: WINTER'S MOTHER (action, 10 CE, once per long rest)", "cost_line": "action, 10 CE, once per long rest", "kind": "maximum", "text": "For 1 minute, she becomes famine itself: - She cannot be moved against her will, and her damage reduction (The Forest Outlasts) increases to **20**. - At the start of each hostile creature's turn within 60 ft, it must succeed on a CON save vs her technique DC or gain **1 level of exhaustion** (the campaign of the empty belly). A creature may instead **kneel and drop its weapons** — submitting — and is ignored by the famine for that turn. (The willing-decline: hunger respects surrender. It always has.) - Her Snatch reaction costs no CE."}, "domain": {"level": null, "name": "HU-HU-HU — THE BASKET OF THE WILD WOMAN (action, 20 CE)", "cost_line": "action, 20 CE", "kind": "domain", "text": "90-ft enclosed Domain. **1000 clash points · 3-round burnout · 3-minute duration** (per zack's Tier V bookkeeping). The deep woods close over everything. Daylight thins to green dusk. Everywhere: *hu-hu-hu.* - **Sure-hit (enemies):** at initiative 20, the forest takes one step closer — each hostile creature inside takes **3d10 bludgeoning damage** (branches, roots, the ground itself closing) and is pulled **15 ft toward her** (the basket calls). This movement provokes no opportunity attacks — nothing in the forest interferes with the basket's dinner. - **Sure-hit (allies of the forest):** at the start of her turn, she regains **10 HP per hostile creature** inside the Domain (maximum 50) — the woods feeding their hunger back to her. - Inside the Domain, her Snatch reach becomes 30 ft. The Domain ends early if she is reduced to 0 HP — the forest opens its hand. (It has never happened. The tuition file remains open.)", "clash_points": 1000, "duration_min": 3, "burnout_rounds": 3, "radius": "90-ft enclosed Domain", "activation": "action", "ce_cost": 20}, "l20": {"level": 20, "name": "SHE WAS ALWAYS HERE (passive, once per long rest)", "cost_line": "passive, once per long rest", "kind": "l20", "text": "When she would be reduced to 0 HP, she is not. The forest refuses the accounting: she returns to **half her maximum HP**, every hostile creature within 30 ft must succeed on a WIS save vs her technique DC or be **frightened** for 1 minute, and the cry changes — one time, those who hear it understand the words underneath the *hu-hu-hu*: *\"I was here before your roads. I will be here after.\"*"}, "summary_text": null, "source_file": "75-dzunukwa.md"}, {"id": "ranavalona-i", "module": "76", "figure": "Ranavalona I", "title": "RANAVALONA I", "detail": "full", "technique": "THE CLOSED DOOR", "tier": "IV", "role": "Tank / Controller (denial)", "ce_ability": "CON", "primary_verb": "Refuse", "region": "Madagascar", "era": "1788–1861 · 19th c.", "culture": "Merina", "concept": "Her technique makes invasion unprofitable — supply lines rot, maps lie, landing parties lose their way — and the closed door of Madagascar is at once her vow, her throne, and her technique.", "serves": "**FRICTION.** **Inheritance Shift (Phase 2):** the Mozambique Channel theater as a denied approach — no expeditionary force lands, supplies, or navigates in her refusal; the living proof that invasion can be made unprofitable. **All-Out War:** the uninvadable island as strategic depth — the one theater the war cannot enter, holding the famadihana queue and everything the General needs kept *out of the war* until the war is over.", "features": [{"level": 1, "name": "Rot the Line", "cost_line": "Action · 2 CE · one Trespasser within 60 ft.", "kind": "feature", "text": "**Tier IV · Tank / Controller (denial) · Suggested CE ability: CON · Primary verb: *Refuse.*** *Technique DC = 8 + proficiency bonus + CON modifier. Her hostile features target **Trespassers** — creatures she has Declared (see below). Declaring is not an attack; it is an edict.* **It Is Declared.** As a bonus action (1 CE), Ranavalona Declares any number of creatures she can see within 120 ft as **Trespassers** for 1 hour. Trespassers treat all terrain within 60 ft of her as difficult terrain. A Declared creature may immediately kneel and declare itself a *guest* — the Declaration lifts, but it is **counted** (she learns its name, number, and business). A guest who breaks guest-law is Declared again, and the second Declaration cannot be declined.\n\nThe trespasser's supply rots: CON save vs her technique DC. On failure, until the end of her next turn: the target has **disadvantage on attack rolls** and its speed is **halved**. On success, only its speed is halved. (The army is not fought. The *line* is fought.)"}, {"level": 1, "name": "The Shore Rejects", "cost_line": "Passive.", "kind": "feature", "text": "Trespassers have **disadvantage on saving throws** against her technique features while standing on ground within 60 ft of her — the island testifies against them. Her allies within 60 ft of her cannot be moved against their will — the island holds its own."}, {"level": 3, "name": "The Maps Lie", "cost_line": "Reaction · 3 CE.", "kind": "feature", "text": "When a Trespasser within 120 ft of her teleports or uses magical movement, she *redirects* the destination up to 60 ft to a point of her choice (WIS save vs her technique DC negates). The willing-decline: the traveler may **abort** the movement instead — arriving nowhere, safely (the action and any resources spent on the movement are still spent). (The chart showed the harbor. The harbor declined to be there.)"}, {"level": 3, "name": "Landing Parties Lose Their Way", "cost_line": "Action · 4 CE · 1 minute (concentration) · 60-ft aura.", "kind": "feature", "text": "Trespassers that start their turn in the aura must succeed on a WIS save vs her technique DC or become **lost** until the start of their next turn: they cannot take reactions, cannot take bonus actions, and attack rolls against them have advantage. A lost creature that uses its action to **begin the march out** — moving away from her and taking no hostile action — is spared the effect that turn. (The road was there this morning. The road is participating in the refusal.)"}, {"level": 6, "name": "The Quarantine", "cost_line": "Action · 6 CE · 1 minute.", "kind": "feature", "text": "A 60-ft-radius zone centered on her becomes **quarantined**: no Trespasser can *enter* the zone — any attempt to cross the boundary pushes the attempter back to the nearest unoccupied space outside it. Trespassers inside may **leave freely** — the door opens outward. It has never imprisoned anyone. It has only ever *declined* them. She may dismiss the zone early (no action)."}, {"level": 11, "name": "The Edict of Spoilage", "cost_line": "Action · 8 CE · once per short rest.", "kind": "feature", "text": "She speaks one edict, naming a kind of supply — *powder*, *rations*, *medicine*, *fuel*. For 1 minute, every Trespasser within 120 ft that relies on the named supply suffers its loss: **disadvantage on CON saving throws** and **vulnerability to one damage type of her choice** (chosen when she speaks the edict). A Trespasser may instead **abandon the supply** — dropping, discarding, or destroying all of the named kind it carries — and is spared. (The willing-decline: travel light, or not at all.)"}], "maximum": {"level": 18, "name": "Maximum: MADAGASCAR UNVIOLATED", "cost_line": "Action · 10 CE · 1 minute · once per long rest.", "kind": "maximum", "text": "She becomes the island: she gains **resistance to all damage**, cannot be moved against her will, and any Trespasser that hits her with an attack takes **2d10 force damage** (the island answers). Her Declaration range becomes **1 mile** for the duration. (Thirty-three years, no landing. The record holds.)"}, "domain": {"level": null, "name": "THE UNINVADABLE ISLAND", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 60-ft radius · disclosed.", "kind": "domain", "text": "The high city. The Rova on the hill. The edicts posted at every road. Inside this domain, the **sure-hit** is *the campaign of attrition* — at initiative 20, the island collects its toll: each Trespasser inside must succeed on a CON save vs her technique DC or gain **1 level of exhaustion** (Heaven permits the defense; the sea permits the march out). A Trespasser that spent its turns **marching out** — moving toward the boundary, taking no hostile action — is spared at the count. (The willing-decline is the oldest one in warfare: *leave*.) **Sure-hit (allies):** allies inside cannot be moved against their will, have advantage on saving throws, and difficult terrain costs them nothing — the island carries its own.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE ANCESTORS' SCHEDULE", "cost_line": "Passive · once per long rest.", "kind": "l20", "text": "When Ranavalona would be reduced to 0 HP, the turning of the bones answers: she is restored to **half her maximum HP**, every hostile creature within 60 ft is **Declared** as a Trespasser (the usual guest-decline applies), and until the end of her next turn her Rot the Line costs no CE. (The ancestors keep the schedule. The schedule keeps the queen.)"}, "summary_text": null, "source_file": "76-ranavalona.md"}, {"id": "roy-mata", "module": "77", "figure": "Roy Mata", "title": "ROY MATA", "detail": "full", "technique": "THE FEAST THAT NEVER ENDS", "tier": "IV", "role": "Tank (the witnessed)", "ce_ability": "STR", "primary_verb": "Witness", "region": "Vanuatu", "era": "c. 13th c.", "culture": "ni-Vanuatu", "concept": "A chief never fights alone — he fields his buried retinue, willing and named, and every wound he takes is witnessed, and witnessed wounds carry a price Heaven enforces on the wounder.", "serves": "**PRICE.** **Inheritance Shift (Phase 2):** the Pacific infantry — the retinue as a formation no awakened warlord can afford to bleed against, every wound priced; the demonstration that violence in the new age *costs*, visibly, immediately. **All-Out War:** the witnessed line — fifty-three pairs of eyes on every engagement, the ledger no army can outrun; and the tapu of Artok as the one ground the war cannot take.", "features": [{"level": 1, "name": "The Names Are Spoken", "cost_line": "Bonus action · 1 CE.", "kind": "feature", "text": "**Tier IV · Tank (the witnessed) · Suggested CE ability: STR · Primary verb: *Witness.*** *Technique DC = 8 + proficiency bonus + STR modifier. His hostile features key off **Witnessed** — see below. Witnessing is not an attack; it is the feast keeping books.* **Witness This (passive).** When Roy Mata takes damage from a creature, Heaven notes it: the creature is **Witnessed** until the end of the encounter (no save — the wound is the witness). When he hits a Witnessed creature, it *pays*: his attacks deal additional force damage equal to his PB (the ledger settling). As a free action on its turn, a Witnessed creature may **settle the account**: take 2d8 psychic damage (Heaven collects) and the Witness clears. (The willing-decline is the oldest custom: *acknowledge the wound, and the ache lifts.*) **The Fifty-Three (passive).** He begins each encounter with standing retinue spirits equal to his PB (maximum 6). Each grants him **+1 AC** (the shield-wall of the dead) — the retinue's AC bonus can never exceed **+6**, however many stand. As a reaction when he takes damage, he may dismiss one standing member to reduce the damage by **2d8** — Tavoa steps in. Dismissed members return at the next dawn. The retinue are *willing*: effects that turn or command undead do not affect them.\n\nHe speaks the names — Tavoa, Mala, Lemas, Sera, Nali, Pakoa, and the rest. Until the end of his next turn, his AC bonus from The Fifty-Three is **doubled** (maximum +8), and Witnessed creatures have **disadvantage on saving throws** against his technique features (the named dead, listening)."}, {"level": 3, "name": "The Retinue Answers", "cost_line": "Bonus action · 2 CE.", "kind": "feature", "text": "Up to two standing retinue members strike: each makes a melee attack (+PB + STR to hit) against a creature within 30 ft, dealing **1d8 + STR force damage** on a hit. If the target is Witnessed, the spears *collect*: +PB force damage each."}, {"level": 3, "name": "Second Burial", "cost_line": "Reaction · 3 CE.", "kind": "feature", "text": "When an ally within 30 ft of Roy Mata takes damage, a retinue member takes the burial: Roy Mata **interposes** — he takes the damage instead (roll 3d10; he takes that amount or the full damage, whichever is less; the rest, if any, strikes the ally as normal). Damage he takes this way is **Witnessed**."}, {"level": 6, "name": "The Island Is Tapu", "cost_line": "Action · 4 CE · 1 minute (concentration) · 30-ft radius.", "kind": "feature", "text": "The ground becomes forbidden: hostile creatures inside have **disadvantage on attack rolls** against any creature other than Roy Mata — the tapu directs the violence to the chief, as is proper. A hostile creature may **leave the radius freely** — the willing-decline; the forbidden ground only binds those who *remain*."}, {"level": 11, "name": "The Mortuary Feast", "cost_line": "Action · 6 CE.", "kind": "feature", "text": "The feast is spread: allies within 30 ft of him regain **3d8 + STR modifier HP**. Every **Witnessed** creature within 30 ft immediately *pays its account*: takes 2d8 psychic damage as Heaven collects (no save — the debt was witnessed; the *decline* was the free-action settlement, offered every round and refused)."}], "maximum": {"level": 18, "name": "Maximum: THE WHOLE ISLAND STOOD", "cost_line": "Action · 10 CE · 1 minute · once per long rest.", "kind": "maximum", "text": "All fifty-three stand: he regains all dismissed retinue members (up to 12 standing — the shield-wall, doubled; the AC bonus remains capped at +6, the extra members stand ready to be dismissed), and for the duration: - Damage he takes is **halved** (the formation absorbs — resistance, the fifty-three closing ranks). - Every creature that damages him becomes **Witnessed** (the whole island, watching). - The Retinue Answers costs no CE. (The two-phase burial, reversed: they rose with him once. They will rise as often as the feast requires.)"}, "domain": {"level": null, "name": "RETOKA — THE FEAST THAT NEVER ENDS", "cost_line": "Full-turn action · 20 CE · 800 clash points · burnout 5 rounds · duration 2 minutes · 60-ft radius · disclosed.", "kind": "domain", "text": "The forbidden island, at feast: firelight, singing, fifty-three figures standing in formation around the walled enclosure. Inside this domain, the **sure-hit** is *the witnessing* — at initiative 20, the retinue strikes as one: each hostile creature inside takes **2d8 force damage** (the sure-hit lands — no save; the fifty-three do not miss), and each struck creature becomes **Witnessed**. (The sure-hit is not the wound. The sure-hit is the *fifty-three pairs of eyes*. The wound is just the receipt.) **Sure-hit (allies):** when the Domain opens, allies inside gain **temporary HP equal to his STR modifier + PB** and cannot be **frightened** while it stands — the feast steadies them.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": "60-ft radius", "activation": "full-turn action", "ce_cost": 20}, "l20": {"level": 20, "name": "THE THREE HUNDRED", "cost_line": "Passive · once per long rest.", "kind": "l20", "text": "The old ones' number: when Roy Mata chooses (no action), for 1 minute the retinue is *uncountable* — the three hundred of the oral tradition, standing: - His AC bonus from The Fifty-Three becomes **+6**, regardless of members dismissed. - The Retinue Answers strikes **four** times instead of two. - Witnessed creatures that damage him **pay double** (+2×PB force on his hits against them)."}, "summary_text": null, "source_file": "77-roy-mata.md"}, {"id": "michael-jackson", "module": "78", "figure": "Michael Jackson", "title": "MICHAEL JACKSON", "detail": "bespoke", "technique": null, "tier": "IV", "role": null, "ce_ability": null, "primary_verb": null, "region": "USA", "era": "1958–2009 · 20th–21st c.", "culture": "American", "concept": "The world will never stop watching — so he taught the watching to dance, and when he died, the dead learned the steps.", "serves": "**Both.** **Phase 2 (EXPOSURE / FRICTION):** the Gallery is built from the establishment's own champions — every disappearance proves the old order cannot protect its own, and the missing return as walking evidence. **All-Out War (attrition):** every enemy casualty he personally causes is permanently claimed and re-fielded — he converts the enemy's losses into his formation, and the formation only grows.", "features": [{"level": null, "name": "THRILLER", "cost_line": "", "kind": "domain", "text": "*Carried over faithfully from the King of POP prototype module (zack-approved; not redesigned). The player-facing King of POP technique — the named applications (Smooth Criminal, Rock with You, Beat It, This Time Around, Blue Gangsta), the Misstep engine, and the Domain's sure-hit choreography compulsion — lives in the rules library's technique codex. This module carries Michael's antagonist-specific layer: the Crown, the failed vessel, and the Gallery.*\n\nTier IV Domain bookkeeping: **800 clash points / 5-round burnout · 2-minute duration.** When Michael opens Thriller, the Gallery manifests per the rules below. The Domain's sure-hit — the choreography compulsion and the Misstep track — is defined in the codex technique; what follows is the permanent collection only Michael possesses.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": null, "activation": null, "ce_cost": null}, {"level": null, "name": "THE BURNED CROWN — Special Grade Cursed Object", "cost_line": "", "kind": "feature", "text": "Years before death, Michael deliberately preserved a section of the scalp scarred in the 1984 burn accident and saturated it with cursed energy, converting the damaged flesh into a Special Grade cursed object intended to permit reincarnation in a future vessel. The symbolism is deliberate. He did not preserve his heart, eyes, hands, or voice. He preserved the place where the crown had burned. A suitable Binding Vow is that he surrendered any peaceful passage after death in exchange for ensuring that the King of POP could one day take the stage again. The exact wording can remain unknown to the players until late in the arc."}, {"level": null, "name": "FAILED REINCARNATION", "cost_line": "", "kind": "feature", "text": "The reincarnation succeeds spiritually but fails biologically. Michael's soul-information remembers the performer: posture, movement, stage presence, voice, and identity. The cursed object remembers burned and damaged flesh. The vessel cannot reconcile the two sets of information. Instead of reconstructing a living body, King of POP begins choreographing a corpse. This turns the technique's core law into body horror. Choreography supersedes biomechanics, so functioning muscles, intact joints, ordinary balance, and even a normal heartbeat are no longer strictly required for the body to complete the next step. At a distance, especially while moving, the reincarnated Michael can almost pass for living. The illusion collapses whenever he stops. His body is decomposing beneath the performance. Limbs occasionally hang at impossible angles before snapping back into position because the next movement demands it."}, {"level": null, "name": "THE MIND THAT CAME BACK WRONG", "cost_line": "", "kind": "feature", "text": "The failed reincarnation also damages continuity of consciousness. Early in the arc, Michael functions primarily through performance memory, cursed-technique instinct, emotional triggers, fragments of speech, and the overwhelming need to be watched. He does not need to begin as a calculating villain. He wanders, performs, reacts to hostility, and escalates. As the campaign progresses, more of the original sorcerer's mind returns. His speech becomes coherent. His tactics become deliberate. Named applications such as Smooth Criminal, This Time Around, Blue Gangsta, and Thriller stop appearing reflexive and begin appearing planned. The intended escalation is that the party initially believes they have met Michael Jackson. In truth, they have met his corpse remembering how to dance. The frightening midpoint or late-arc turn is when Michael himself fully wakes up."}, {"level": null, "name": "SLAVE TO THE RHYTHM — Burnout", "cost_line": "", "kind": "feature", "text": "For Michael, Slave to the Rhythm is existential. The failed vessel continues to function because the cursed technique keeps imposing performance on tissue that should no longer move correctly. His existence has become the literal form of the technique's name. In life, the world demanded that he perform. In death, his own cursed technique does. During Technique Burnout, Michael loses access to active King of POP applications under the normal rules. His corpse can still perform basic movement and attacks through ordinary cursed-energy reinforcement and the soul's possession of the vessel, but the graceful impossible choreography disappears. His movement becomes visibly stiff, damaged, and corpse-like until the technique returns."}, {"level": null, "name": "THRILLER — THE UNDEAD GALLERY", "cost_line": "", "kind": "feature", "text": "Thriller is not merely themed after the dead. Michael's version contains actual corpses. Any creature Michael personally kills can be claimed by his Innate Domain. Its corpse is incorporated into Thriller and becomes a permanent member of the undead dancer gallery. When the Domain is opened in the future, that corpse can physically emerge from the graves, alleys, fog, or formation lines inside the barrier. This rule is specific to Michael's failed reincarnation and is not part of the reusable player-facing King of POP technique."}, {"level": null, "name": "MICHAEL-SPECIFIC RULE: CLAIM THE DEAD", "cost_line": "", "kind": "feature", "text": "**Trigger:** Michael personally causes a creature to die. If a recoverable corpse remains, Michael may claim it for Thriller. The claim requires no additional CE and is permanent until the corpse is destroyed within the Innate Domain or Michael voluntarily releases it. A claimed corpse is removed from ordinary resurrection access while stored in the Innate Domain unless a specific story effect can reach souls, bodies, or objects held inside another sorcerer's Innate Domain. This is meant to make the disappearance of a body meaningful without making recovery absolutely impossible if the campaign later introduces an appropriate high-level solution. The GM decides when the corpse physically vanishes from the material world. For mystery arcs, it can be drawn into the Innate Domain shortly after death and leave behind only blood, damaged clothing, or environmental evidence. For witnessed kills, the body may be visibly swallowed by grave soil, stage fog, darkness, or another Thriller motif."}, {"level": null, "name": "MICHAEL-SPECIFIC RULE: GALLERY MANIFESTATION", "cost_line": "", "kind": "feature", "text": "When Michael expands Thriller, every claimed corpse may appear visually inside the Domain. There is no narrative limit to the size of the background formation. Only a limited number act as combatants at once. When Michael's full-turn Domain activation completes and Thriller's barrier is established, he designates up to his proficiency bonus in stored corpses (six at level 18) as Active Gallery Dancers; this designation happens once per Domain opening and cannot be changed while the Domain stands. All other corpses remain physical background dancers. They can perform choreography, reveal their identities, surround the battlefield, crawl from graves, or create environmental horror, but they do not add attacks to the initiative economy. This active cap prevents the persistent gallery from turning one Domain into hundreds of extra turns while preserving the visual scale of Michael's accumulated dead."}, {"level": null, "name": "ACTIVE GALLERY DANCER TEMPLATE", "cost_line": "", "kind": "feature", "text": "An Active Gallery Dancer is a corpse that entered Thriller before the current fight, not a living creature newly assimilated through Missteps. Use the corpse's recognizable body and combat style, but simplify it: - **AC:** use the creature's former AC. - **HP:** one-half of the creature's former maximum HP, rounded up. - **Speed:** use its former walking speed. - **Saves and ability checks:** use its former modifiers. - **Attacks:** retain one recognizable basic weapon or unarmed attack. Do not retain Multiattack unless the GM specifically wants a boss-tier Gallery Dancer. - **Cursed techniques:** unavailable. - **Domain Expansion, Maximum Techniques, RCT, spellcasting, transformation states, recharge powers, and active cursed-tool abilities:** unavailable. - **Reactions:** none. - **Choreography:** automatically succeeds on Thriller's steps. - **Type:** counts as Undead in addition to its former creature type. - **Initiative:** acts immediately after Michael, sharing one initiative position for all Active Gallery Dancers to keep play fast. Michael chooses each Active Gallery Dancer's movement and target. A dancer can make its one retained basic attack, Dash, Disengage, Dodge, Help, or perform a scene-specific interaction approved by the GM. A particularly important past NPC may receive a bespoke Gallery Dancer stat block, but that should be an explicit boss encounter decision rather than the default corpse rule."}, {"level": null, "name": "DESTROYING A GALLERY CORPSE", "cost_line": "", "kind": "feature", "text": "A stored corpse that is reduced to 0 HP while physically manifested in Thriller is destroyed as a Gallery Dancer and removed from Michael's collection unless a story-specific effect preserves or restores it. This creates a meaningful choice for the party. Destroying the corpse can permanently deny Michael that dancer, but the body may also belong to a former ally whose remains they hoped to recover. If Thriller ends before the corpse is destroyed, the corpse returns to storage inside the Innate Domain with the HP it had when the Domain ended. The GM may allow Michael's Innate Domain to slowly restore a corpse between arcs if recurring dancers are desired, but this should be treated as an explicit antagonist ability rather than assumed."}, {"level": null, "name": "INTERACTION WITH CURRENT MISSTEP VICTIMS", "cost_line": "", "kind": "feature", "text": "A creature transformed into a Living Dead Backup Dancer by reaching three Missteps during the current Domain follows the normal player-facing Thriller rules. It is not permanently added to the Gallery merely for being assimilated. For permanent collection, Michael must actually kill the creature. If a current Living Dead victim dies while under Michael's control and Michael personally caused the death, it may immediately qualify for Claim the Dead."}, {"level": null, "name": "SPECIAL GRADE PRESENTATION", "cost_line": "", "kind": "feature", "text": "Michael should feel unnerving before he feels explosive. His strongest visual contrast is graceful movement performed by a body that should not physically work. Smooth Criminal is more disturbing when the spine does not appear capable of supporting the lean. Rock with You is stranger when the feet glide despite damaged joints. Blue Gangsta should look less like superspeed and more like an execution route the world is being forced to accept. When conscious control returns, his fighting style should become more economical rather than merely louder. Early Michael overperforms because instinct is driving him. Awakened Michael knows exactly which step is necessary."}, {"level": null, "name": "TONE AND STORY BOUNDARIES", "cost_line": "", "kind": "feature", "text": "Michael is an antagonist inspired by the public mythology, performances, songs, imagery, controversies, and cultural footprint associated with Michael Jackson. The fictional jujutsu premise must not present unresolved real-world criminal allegations as established supernatural fact. The campaign's emotional engine is unresolved public fixation and a sorcerer's refusal to pass quietly into obscurity. The horror comes from fame becoming cursed persistence, performance becoming bodily compulsion, and an audience becoming an undead collection. The reusable King of POP technique belongs in the player rules library. The Burned Crown, failed reincarnation, corpse-body horror, permanent Gallery, and this specific antagonist arc belong only to Michael's GM-facing module."}], "maximum": null, "domain": {"level": null, "name": "THRILLER", "cost_line": "", "kind": "domain", "text": "*Carried over faithfully from the King of POP prototype module (zack-approved; not redesigned). The player-facing King of POP technique — the named applications (Smooth Criminal, Rock with You, Beat It, This Time Around, Blue Gangsta), the Misstep engine, and the Domain's sure-hit choreography compulsion — lives in the rules library's technique codex. This module carries Michael's antagonist-specific layer: the Crown, the failed vessel, and the Gallery.*\n\nTier IV Domain bookkeeping: **800 clash points / 5-round burnout · 2-minute duration.** When Michael opens Thriller, the Gallery manifests per the rules below. The Domain's sure-hit — the choreography compulsion and the Misstep track — is defined in the codex technique; what follows is the permanent collection only Michael possesses.", "clash_points": 800, "duration_min": 2, "burnout_rounds": 5, "radius": null, "activation": null, "ce_cost": null}, "l20": null, "summary_text": null, "source_file": "78-michael-jackson.md"}]};
